(window.GIM_TS=window.GIM_TS||{})["Shevuot.3"]={"from":72,"a":[["\u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מזו אין לשמוע ממנה],\u0006 ואין לדייק ממה שלא נאמרו הדברים במשנה.","שנינו במשנה: \u0003שבועת הפקדון כיצד? \"תן לי פקדון שיש לי בידך\" כו'.\u0004 ובהמשך עסקה המשנה במי שהיו חמשה תובעים אותו, ונשבע לכולם. ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003כלל\u0004 שבועה לכמה אנשים בנוסח אחד — \u0003אינו חייב אלא\u0004 משום שבועה \u0003אחת,\u0004 אם \u0003פרט\u0004 — \u0003חייב על כל אחת ואחת, דברי ר' מאיר. ר' יהודה אומר:\u0004 אם אמר \u0003\"שבועה לא לך ולא לך ולא לך\"\u0004 — \u0003חייב על כל אחת ואחת.\u0004","\u0003ר' אליעזר אומר:\u0004 דווקא אם אמר \u0003\"לא לך ולא לך ולא לך שבועה\"\u0004 שאמר לשון שבועה בסוף — \u0003חייב על כל אחת ואחת. ר' שמעון אומר: עד שיאמר שבועה לכל אחת ואחת\u0004 כלומר, שיפרש מלת \"שבועה\" בכל אחת.","ובפירוש דברי ר' מאיר ור' יהודה נחלקו שמואל ור' יוחנן, \u0003אמר רב יהודה אמר שמואל: כללו של ר' מאיר\u0004 מה שרואה ר' מאיר ככלל (\"ולא לך ולא לך\", בו' החיבור) — הרי הוא \u0003פרטו של ר' יהודה,\u0004 ו\u0003כללו של ר' יהודה\u0004 מה שהוא רואה אותו כביטוי אחד (\"לא לך, לא לך\", בלי ו' החיבור) — הוא \u0003פרטו של ר' מאיר. ו\u0004אילו","\u0003ר' יוחנן אמר: הכל מודים ב\"ולא לך\" שהוא פרט,\u0004 וגם ר' מאיר. \u0003לא נחלקו אלא\u0004 כשאמר \u0003\"לא לך\", שר' מאיר אומר:\u0004 גם זה הוא \u0003פרט, ור' יהודה אומר: כלל. ואיזהו כללו של ר' מאיר\u0004 שחייב רק משום שבועה אחת? כשאומר \u0003\"שבועה שאין לכם בידי\".\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 שהם מפרשים באופן שונה את דברי ר' מאיר? ומשיבים: \u0003שמואל דייק\u0004 \u0005[מדייק]\u0006 \u0003מ\u0004לשון ה\u0003ברייתא, ור' יוחנן דייק ממתניתין\u0004 \u0005[מדייק ממשנתנו].\u0006 ומפרטים: \u0003שמואל דייק\u0004 \u0005[מדייק]\u0006 מן ה\u0003ברייתא,\u0004 כיצד? \u0003מדקאמר\u0004 \u0005[ממה שאומר]\u0006 \u0003ר' יהודה: \"ולא לך\" פרטא הוי\u0004 \u0005[פרט הוא]\u0006 שחייב על כל אחת ואחת, \u0003מכלל\u0004 הדברים אתה למד \u0003דשמעיה\u0004 \u0005[ששמע אותו]\u0006 את \u0003ר' מאיר\u0004 ש\u0003אמר: כללא הוי\u0004 \u0005[כלל הוא]\u0006, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה:\u0004 לא, \u0003פרטא הוי\u0004 \u0005[פרט הוא].\u0006","\u0003ור' יוחנן אמר:\u0004 ניתן להסביר גם אחרת, ולומר: \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003לר' מאיר פרטא הוי\u0004 \u0005[פרט הם],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה: ב\"ולא לך\" מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך, ב\"לא לך\" פליגנא עלך\u0004 \u0005[חולק אני עליך].\u0006 \u0003ושמואל,\u0004 מה הוא משיב על כך? סבור הוא: אם כך הוא, הרי \u0003עד דאודי ליה אודויי, לפלוג עליה איפלוגי\u0004 \u0005[עד ש\u0006הוא \u0005מודה לו, שיחלוק עליו],\u0006 שתמוה הוא שר' יהודה אומר במה הוא מודה לו, כאשר היה ראוי לו לפרש דווקא במה הוא חולק עליו. עד כאן דנו בדיוקו של שמואל.","\u0003ור' יוחנן דייק ממתניתין\u0004 \u0005[מדייק ממשנתנו],\u0006 כיצד? \u0003מדקאמר\u0004 \u0005[ממה שאומר]\u0006 \u0003ר' מאיר\u0004 במשנה, שהיא בסתם שיטת ר' מאיר: \u0003\"שבועה שאין לכם בידי\" כללא הוי\u0004 \u0005[כלל הוא],\u0006 \u0003מכלל\u0004 הדברים אתה למד שאם אומר \u0003\"ולא לך\" פרטא הוי\u0004 \u0005[פרט הוא];\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שלשיטתו \u0003\"ולא לך\" כללא הוה\u0004 \u0005[כלל הוא],\u0006 הרי \u0003אדמשמע לן\u0004 \u0005[עד ש\u0006הוא \u0005משמיע לנו]\u0006 \u0003\"שבועה שאין לכם בידי\"\u0004 שהוא כלל, \u0003נשמעינן\u0004 \u0005[שישמיע לנו]\u0006 ש\u0003\"שבועה לא לך ולא לך ולא לך\"\u0004 הוא כלל, למרות שיש בו פירוט, וממילא נלמד \u0003כל שכן\u0004 אם אמר \u0003\"שבועה שאין לכם בידי\"\u0004 שכלל הוא.","\u0003ו\u0004אילו \u0003שמואל אמר\u0004 \u0005[אומר]\u0006 שכך יש לפרש את דברי ר' מאיר: \u0003כל האומר \"ולא לך\",\u0004 הרי אף הוא \u0003כאומר \"שבועה שאין לכם בידי\" דמי\u0004 \u0005[נחשב].\u0006","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"לא לך ולא לך ולא לך\"\u0004 חייב על כל אחת ואחת. שאומר \"ולא\" בו', ומחשיב זאת ר' מאיר כפרט, וקשה לשמואל! ומתקנים: \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"לא לך\u0004 לא לך לא לך\" בלא ו'.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה: \u0003\"תן לי פקדון ותשומת יד וגזל ואבידה\"\u0004 וכו', \"שבועה שאין לך בידי פקדון ותשומת יד\" וכו' — חייב על כל אחת ואחת. משמע שכשיש ו' נחשב הדבר כפרט לדברי ר' מאיר, ושלא כדברי שמואל! ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 בלי ו': \u0003\"תשומת יד גזל אבידה\".\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת מן המשנה: \u0003\"תן לי חטין ושעורין וכוסמין\",\u0004 וקשה לשמואל! ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 גם כאן: \u0003\"שעורין כוסמין\"\u0004 בלא ו'.","ושואלים: \u0003והאי תנא כל הכי שביש תני ואזיל\u0004 \u0005[ו\u0006כי \u0005תנא זה כל כך משבש שונה והולך]?\u0006 שקשה לומר שבכל מקום שיבש התנא את הלשון והוסיף ו' שלא לצורך, עד שצריך לתקן אותם משפט אחר משפט! \u0003אלא\u0004 צריך לומר לשיטת שמואל כי \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]?\u0006 לא כשיטת ר' מאיר, אלא כשיטת \u0003רבי היא,\u0004 ש\u0003אמר: לא שנא\u0004 \u0005[אינו שונה]\u0006 אם אמר \u0003\"כזית כזית\", ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003\"כזית וכזית\"\u0004 — שניהם \u0003פרטא הוי\u0004 \u0005[פרט הם].\u0006","ואומרים: \u0003תא שמע מדידיה\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 ראיה \u0005מ\u0006דברי ר' מאיר \u0005עצמו]\u0006 במשנתנו, ששנינו \u0003ר' מאיר אומר: אפילו \"חטה ושעורה וכוסמת\"\u0004 — \u0003חייב על כל אחת ואחת!\u0004 משמע שאף שמוסיף ו' פרט הוא, שלא כדברי שמואל! ומתקנים: \u0003תני\u0004 \u0005[שנה]\u0006 גם כאן: \u0003\"חטה שעורה כוסמת\".\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"אפילו\"?\u0004 מה החידוש כשאומר בלשון זו? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: אפילו חטה בכלל חטין, ושעורה בכלל שעורין, וכוסמת בכלל כוסמין,\u0004 שלא התכוון לפרט של חיטה אחת, אלא למין חיטים, מין שעורים.","שנינו במשנה: \u0003\"תן לי פקדון ותשומת יד גזל ואבידה שיש לי בידך\" כו'. \"תן לי חטין ושעורין\u0004 וכוסמין שיש לי בידך\", ואמר לו: \"שבועה שאין לך בידי\" — אינו חייב אלא אחת. ואם אמר: \"שבועה שאין לך בידי חטין ושעורין וכוסמין\" — חייב על כל אחת ואחת. ועל כך \u0003אמר ר' יוחנן:\u0004 אם היה שווה \u0003פרוטה מכולם\u0004 בחיטים בשעורים ובכוסמין, אף שאין בכל מין שיעור שווה פרוטה, הריהי \u0003מצטרפת\u0004 לחייבו משום שבועת הפקדון.","\u0003פליגי בה\u0004 \u0005[חלוקים בכך]\u0006 בפירוש דברים אלה \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מה ששנינו במשנה שחייב על כל אחת ואחת — \u0003אפרטי מיחייב\u0004 \u0005[על הפרטים\u0006 הוא \u0005חייב],\u0006 על החיטים, על השעורים ועל הכוסמים, הריהו מביא קרבן משום שבועה, אבל \u0003אכללי לא מיחייב\u0004 \u0005[על הכללים איננו חייב].\u0006 על מה שאמר בתחילה: \"שבועה שאין לך בידי\", אינו מביא קרבן לעצמו. ולפיכך מה שאמר ר' יוחנן שפרוטה אחת מכולם יחד מצטרפת, מתייחס לדין הקודם במשנה, שאמר: \"שבועה שאין לך בידי\" ולא פירט. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אכללי נמי מיחייב\u0004 \u0005[על הכללים גם כן הוא חייב],\u0006 שחייב להביא קרבן גם על השבועה הכללית שאמר תחילה. ולפיכך גם אם אין בכל אחד מהם שווה פרוטה, אם יש בכולם יחד שווה פרוטה — הרי זה מתחייב בקרבן משום השבועה הכללית, לדעת ר' יוחנן.","ומקשים, \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003הרי כאן חמש עשרה חטאות\u0004 שהיו חמישה תובעים ולכל אחד מהם נשבע על שלושה דברים — חיטים, שעורים, כוסמים; \u0003ואם איתא\u0004 \u0005[אכן]\u0006 חייב גם על הכללים — \u0003עשרים\u0004 חטאות \u0003הויין\u0004 \u0005[הן],\u0006 שהרי יש שבועה כללית \"שאין לך בידי\", ושלוש שבועות פרטיות (חיטים, שעורים, כוסמים) לכל תובע! ומשיבים: \u0003האי תנא\u0004 \u0005[תנא זה],\u0006 \u0003דפרטי קא חשיב\u0004 \u0005[את\u0006 החיובים שיש \u0005בפרטים\u0006 הוא \u0005מונה],\u0006 \u0003דכללי לא קא חשיב\u0004 \u0005[\u0006את החיוב \u0005של הכללים אינו מונה].\u0006","ומקשים לצד האחר: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 בברייתא אחרת: \u0003הרי כאן עשרים חטאות,\u0004 ואם כן הוא מחשיב כללים! ומשיבים: \u0003ההיא,\u0004 אותה ברייתא, גם היא אינה מונה את הכללים, אלא היא עוסקת במקרה אחר, בחטאות שמתחייב כשמכחיש לחמישה אנשים על ארבע טענות שונות, \u0003פקדון ותשומת יד וגזל ואבידה.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: היו חמשה תובעין אותו, ואמרו לו \"תן לנו פקדון תשומת יד וגזל ואבידה שיש לנו בידך\", אמר לאחד מהן \"שבועה שאין לך בידי פקדון תשומת יד גזל ואבידה, ולא לך ולא לך ולא לך ולא לך\", מהו\u0004 דינו? האם \u0003אחדא מיחייב\u0004 \u0005[על\u0006 שבועה \u0005אחת\u0006 הוא \u0005חייב]\u0006 לכל אחד מן האנשים שאמר להם \"ולא לך\", משום שכלל את כל הדברים באמירה אחת \"ולא לך\","],["\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אכל חדא וחדא מיחייב\u0004 \u0005[על כל אחת ואחת\u0006 מן התביעות \u0005מתחייב]\u0006 לכל אחד ואחד?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003הרי כאן עשרים חטאות.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אי דפריש\u0004 \u0005[אם שפירש]\u0006 לכל אחד מן התובעים את כל התביעות, וכי \u0003ר' חייא מנינא אתא לאשמועינן\u0004 \u0005[מנין בא להשמיענו]?\u0006 וכי אין אנו יכולים למנות לבד?! \u0003אלא לאו דלא פריש\u0004 \u0005[האם לא\u0006 מדובר במקרה \u0005שלא פירש]\u0006 לכל אחד ואחד, אלא שפירט לאחד ולאחרים אמר \"ולא לך\", \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003פרטא הוי\u0004 \u0005[פרט הוא].\u0006","שנינו במשנה: הטוען \u0003\"אנסת ופתית את בתי\",\u0004 והנתבע מכחיש ונשבע לשקר, שר' שמעון פוטר משום שהוא קנס, שאם היה מודה בו לא היה מתחייב על פי עצמו. וחכמים מחייבים משום שיש בזה גם תביעת בושת ופגם, שהן תביעות ממון שיכול להתחייב על פי עצמו. \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון? הואיל ועיקר\u0004 התביעה \u0003קנס הוא תובע,\u0004 ושאר הדברים רק נספחים להם.","\u0003אמר רבא: משל\u0004 של \u0003ר' שמעון,\u0004 להסביר את דבריו, \u0003למה הדבר דומה? לאדם שאמר לחבירו: \"תן לי חטין ושעורין וכוסמין שיש לי בידך\", אמר לו: \"שבועה שאין לך בידי חטין\", ואשתכח\u0004 \u0005[ונמצא]\u0006 ש\u0003חטין הוא דלית ליה\u0004 \u0005[שאין לו],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שעורין וכוסמין אית ליה\u0004 \u0005[יש לו]\u0006 — שהוא \u0003פטור\u0004 משבועת הפקדון, לפי \u0003דכי אשתבע\u0004 \u0005[שכאשר נשבע]\u0006 על ה\u0003חטין, אקושטא משתבע\u0004 \u0005[באמת נשבע].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם],\u0006 בדוגמה שהבאת, \u0003בחטין קא כפר ליה\u0004 \u0005[הוא כופר לו],\u0006 \u0003בשעורין וכוסמין לא קא כפר ליה\u0004 \u0005[אינו כופר לו]\u0006 כלל, \u0003הכא בכולה מילתא הוא דקא כפר ליה\u0004 \u0005[\u0006אבל \u0005כאן בכל הדבר הוא כופר לו],\u0006 שהרי אמר שלא אנס ולא פיתה כלל! \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא לאומר לחבירו: \"תן לי חטין ושעורין וכוסמין שיש לי בידך\",\u0004 ואמר לו: \u0003\"שבועה שאין לך בידי כלל\", ואשתכח\u0004 \u0005[ונמצא]\u0006 ש\u0003חטין הוא דלית ליה\u0004 \u0005[שאין לו],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שעורין וכוסמין אית ליה\u0004 \u0005[יש לו]\u0006 — \u0003דמיחייב\u0004 \u0005[ש\u0006במקרה זה הריהו \u0005חייב]\u0006 משום שבועת הפקדון! ואם כן לא זהו ההסבר לדברי ר' שמעון. \u0003אלא\u0004 כמו ש\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר\u0004 בשם \u0003ר' יוחנן: לדברי ר' שמעון\u0004 — \u0003קנס הוא תובע\u0004 כשהוא טוען שאנס או פיתה את בתו, \u0003ולא בושת ופגם,\u0004 שאינו תובע אותם באמירה זו, ולכן פטור הנשבע, שהרי כפר בטענה של קנס. \u0003לדברי חכמים\u0004 — \u0003אף בושת ופגם הוא תובע,\u0004 ומשום כך חייב. \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 \u0003אמר רב פפא, ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003לא שביק איניש מידי דקיץ ותבע מידי דלא קיץ\u0004 \u0005[אין אדם מניח דבר שקצוב\u0006 כמו הקנס \u0005ותובע דבר שאינו קצוב]\u0006 כמו בושת ופגם שצריך אומדן. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא שביק מידי דכי מודה ביה לא מיפטר\u0004 \u0005[אין\u0006 אדם \u0005מניח דבר שאם מודה בו\u0006 הנתבע \u0005אינו נפטר],\u0006 כבושת ופגם, \u0003ותבע מידי דכי מודה ביה מיפטר\u0004 \u0005[ותובע\u0006 רק \u0005דבר שאם מודה בו נפטר]\u0006 כמו הקנס.","","","\u0003שבועת הדיינין\u0004 כלומר, השבועה שהדיינים משביעים מדין תורה את מי שמודה במקצת הטענה, חלה כאשר \u0003הטענה\u0004 שטוען התובע היא בדבר ששווה לפחות \u0003שתי כסף, וההודאה\u0004 שמודה הנתבע היא לפחות \u0003בשוה פרוטה. ו\u0004תנאי נוסף בענין זה, ש\u0003אם אין ההודאה ממין הטענה,\u0004 אלא מודה לו הנתבע בדבר שלא טען — \u0003פטור.\u0004","\u0003כיצד?\u0004 אם אמר לו: \u0003\"שתי כסף לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא פרוטה\u0004 (של נחושת)\"— הרי זה \u0003פטור,\u0004 משום שמה שטען לא הודה לו. אבל אם אמר: \u0003\"שתי כסף ופרוטה לי בידך\",\u0004 ואמר לו \u0003\"אין לך בידי אלא פרוטה\"\u0004 — הרי זה \u0003חייב.\u0004","אמר לו: \u0003\"מנה\u0004 (מאה דינרים) \u0003לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי\u0004 כלום\" — הרי זה \u0003פטור.\u0004 אבל אם אמר לו: \u0003\"מנה לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא חמישים דינר\"\u0004 — \u0003חייב,\u0004 משום שהודה במקצת.","ואולם במקרה שהודה במקצת, שאמר לו: \u0003\"מנה לאבא בידך\",\u0004 ועכשיו שמת אני תובע ממך, ואמר לו הנתבע: \u0003\"אין לך בידי אלא חמשים דינר\"\u0004 — \u0003פטור\u0004 משבועה זו, \u0003מפני שהוא כמשיב אבידה,\u0004 שהיה יכול במקרה זה לכפור בכל.","ודנים באופן נוסף של כופר בכל שהוזכר לעיל. אמר לו: \u0003\"מנה לי בידך\",\u0004 ו\u0003אמר לו\u0004 הנתבע: \u0003\"הן\", למחר אמר לו\u0004 התובע: \u0003\"תנהו לי,\u0004 שהרי הודית\", ואמר לו הנתבע: \u0003\"נתתיו לך\"\u0004 — הרי זה \u0003פטור.\u0004 אבל אם אמר לו למחר: \u0003\"אין לך בידי\"\u0004 — \u0003חייב\u0004 לשלם לו, שהרי כבר הודה שחייב. אמר לנתבע \u0003\"מנה לי בידך\", אמר לו: \"הן\",\u0004 אמר לו התובע: \"אם כן, \u0003אל תתנהו לי אלא בעדים\", למחר אמר לו: \"תנהו לי\",\u0004 ואמר לו הנתבע: \u0003\"נתתיו לך\"\u0004 — הרי זה \u0003חייב\u0004 לשלם, \u0003מפני שצריך ליתנו בעדים\u0004 כפי שהתנה עימו.","","ושבים לדון בפרטי הדינים של מודה במקצת. אם אמר לו: \u0003\"ליטרא זהב יש לי בידך\",\u0004 ואמר הנתבע: \u0003\"אין לך בידי אלא ליטרא כסף\"\u0004 — \u0003פטור,\u0004 שהרי לא הודה לו במה שתבעו. אבל אם אמר לו \u0003\"דינר זהב יש לי בידך\",\u0004 ואמר לו הנתבע \u0003\"אין לך בידי אלא דינר כסף\", ו\u0004כן \"יש לך בידי \u0003טריסית\", ו\u0004כן \u0003פונדיות, ו\u0004כן \u0003פרוטה\u0004 — \u0003חייב,\u0004 ומדוע? \u0003שהכל מין מטבע אחת,\u0004 שהוא תובע ממנו ממון והודה לו בסכום קטן יותר.","וכן אם תבע אותו: \u0003\"כור תבואה לי בידך\",\u0004 ואמר הנתבע: \u0003\"אין לך בידי אלא לתך\u0004 (חצי כור) של \u0003קטנית\"\u0004 — \u0003פטור,\u0004 שאין ההודאה ממין הטענה, שהודה לו בדבר שלא טען. אבל אם אמר: \u0003\"כור פירות לי בידך\",\u0004 ואמר לו \u0003\"אין לך בידי אלא לתך קטנית\"\u0004 — \u0003חייב,\u0004 לפי \u0003שהקטנית בכלל פירות.\u0004","אם \u0003טענו חטין והודה לו\u0004 הנתבע \u0003בשעורין\u0004 — \u0003פטור\u0004 משבועה, \u0003ורבן גמליאל מחייב\u0004 שבועה.","\u0003הטוען לחבירו בכדי שמן\u0004 שהוא חייב לו כך וכך כדים של שמן, \u0003והודה לו\u0004 לא בשמן, אלא \u0003בקנקנים\u0004 בכדים המכילים את השמן — \u0003אדמון אומר: הואיל והודה לו מקצת ממין הטענה ישבע,\u0004 שהרי תבע ממנו קנקנים ובהם שמן. \u0003וחכמים אומרים: אין ההודאה ממין הטענה,\u0004 שאינו מודה לו בשמן שתבע. \u0003אמר רבן גמליאל: רואה אני\u0004 ומקבל \u0003את דברי אדמון.\u0004","\u0003טענו כלים וקרקעות, והודה בכלים וכפר בקרקעות,\u0004 או הודה \u0003בקרקעות וכפר בכלים\u0004 — \u0003פטור,\u0004 משום שאין נשבעים על קרקעות, ומטעם זה גם אם \u0003הודה במקצת הקרקעות\u0004 — \u0003פטור.\u0004 אבל אם הודה \u0003במקצת הכלים\u0004 — \u0003חייב\u0004 שבועה על הכל, \u0003שהנכסים שאין להן אחריות\u0004 (מיטלטלין) \u0003זוקקין\u0004 (מביאים) \u0003את הנכסים שיש להן אחריות\u0004 (קרקעות) \u0003לישבע\u0004 גם \u0003עליהן,\u0004 אף שעליהם לבדם אין חייבים להישבע.","\u0003אין נשבעין על טענת חרש שוטה וקטן, ואין משביעין את הקטן, אבל נשבעין לקטן ולהקדש.\u0004","ושואלים: \u0003היכי משבעינן ליה\u0004 \u0005[איך משביעים אותו]\u0006 הדיינים? \u0003אמר רב יהודה אמר רב: משביעין אותו בשבועה האמורה בתורה, דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי אברהם לאליעזר: \u0003\"ואשביעך בה' אלהי השמים\"\u0004 (בראשית כד, ג).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: כמאן\u0004 \u0005[כמי]\u0006 נאמר דבר זה? האם הוא \u0003כ\u0004דעת \u0003ר' חנינא בר אידי,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 בשבועה שיזכיר \u0003שם המיוחד?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש לפרש זאת \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שדי \u0003בכינוי, ונפקא מינה\u0004 \u0005[ויוצא מזה]\u0006 מדברי רב דבר אחר, שכמו שבשבועה האמורה בתורה אמר אברהם \"שים נא ידך תחת ירכי, ואשביעך\" (בראשית כד ב), כך בשבועת הדיינים \u0003צריך לאתפושי חפצא בידיה\u0004 \u0005[להתפיס חפץ\u0006 של קדושה \u0005בידו]\u0006 כדי שתחול השבועה, \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: האי דיינא דאשבע\u0004 \u0005[דיין זה שהשביע]\u0006 רק \u0003\"בה' אלהי השמים\",\u0004 בלי להתפיס חפץ, \u0003נעשה כמי שטעה בדבר משנה\u0004 שחוזר בו מדינו, \u0003וחוזר\u0004 ומשביע שנית. \u0003ואמר רב פפא: האי דיינא דאשבע\u0004 \u0005[דיין זה שהשביע]\u0006 \u0003בתפלין, נעשה כמי שטעה בדבר משנה וחוזר.\u0004","","","ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רבא, ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כשיטתו]\u0006 של \u0003רב פפא. הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רבא,\u0004 שאם השביעו רק בשם — חוזר, \u0003דהא לא נקיט חפצא בידיה\u0004 \u0005[שהרי אינו מחזיק חפץ\u0006 קדוש \u0005בידו],\u0006 \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כשיטתו]\u0006 של \u0003רב פפא\u0004 לגבי תפילין, שחוזר, \u0003דהא נקיט חפצא בידיה\u0004 \u0005[שהרי\u0006 הוא \u0005מחזיק חפץ\u0006 של קדושה \u0005בידו],\u0006 שאף שאינו ספר תורה, מכל מקום דבר של קדושה הוא. ועוד הלכות בענין זה.","\u0003שבועה\u0004 עושים אותה כשהנשבע \u0003מעומד, תלמיד חכם\u0004 — \u0003מיושב. שבועה\u0004 נשבעים לכתחילה כשהנשבע מחזיק \u0003בספר תורה, תלמיד חכם\u0004 — \u0003לכתחלה\u0004 נשבע \u0003בתפלין.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שבועת הדיינין אף היא בלשונה נאמרה\u0004 כלומר, בכל לשון שהנשבע מבין, ולאו דווקא בלשון הקודש.","","וכך \u0003אומרים לו\u0004 לנשבע לפני שישבע: \u0003הוי יודע,\u0004"],["\u0003שכל העולם כולו נזדעזע בשעה שאמר הקדוש ברוך הוא בסיני: \"לא תשא את שם ה' אלהיך לשוא\u0004 כי לא ינקה ה' את אשר ישא את שמו לשוא\" (שמות כ, ז).","\u0003וכל עבירות שבתורה נאמר בהן \"ונקה\"\u0004 (שמות לד, ז)\u0003, וכאן נאמר \"לא ינקה\". וכל עבירות שבתורה נפרעין ממנו\u0004 בלבד, \u0003וכאן ממנו וממשפחתו, שנאמר: \"אל תתן את פיך לחטיא את בשרך\"\u0004 (קהלת ה, ה), שהחוטא בפיו בשבועת שוא גורם להעניש גם את בשרו, \u0003ואין בשרו אלא קרובו, שנאמר: \"ומבשרך לא תתעלם\"\u0004 (ישעיהו נח, ז).","\u0003וכל עבירות שבתורה נפרעין ממנו\u0004 בלבד, \u0003וכאן ממנו ומכל העולם כולו, שנאמר: \"אלה וכחש\u0004 ורצח וגנב ונאף . . . על כן תאבל הארץ ואמלל כל יושב בה\" (הושע ד, ב—ג).","ומקשים על דברי הברייתא: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שאין נפרעים מכל העולם \u0003עד דעביד להו\u0004 \u0005[שעושה אותם]\u0006 את המעשים הרעים האמורים בכתוב זה \u0003לכולהו\u0004 \u0005[כולם]!\u0006 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מפני אלה אבלה הארץ\"\u0004 (ירמיהו כג, י), שמפני האלה — השבועה בלבד אבלה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בדומה לכך בכתוב שאנו עוסקים בו: \u0003\"על כן תאבל הארץ ואמלל כל יושב בה\"\u0004 (הושע ד, ג).","וממשיכה הברייתא, ועוד אומרים לו: \u0003וכל עבירות שבתורה, אם יש לו זכות תולין לו שנים ושלשה דורות\u0004 עד שנפרעים מצאצאיו, \u0003וכאן\u0004 בשבועת שקר \u0003נפרעין ממנו לאלתר\u0004 (מיד), \u0003שנאמר: \"הוצאתיה נאם ה' צבאות ובאה אל בית הגנב ואל בית הנשבע בשמי לשקר ולנה בתוך ביתו וכלתו ואת עציו ואת אבניו\"\u0004 (זכריה ה, ד),","\u0003\"הוצאתיה\"\u0004 — משמע \u0003לאלתר, \"ובאה אל בית הגנב\"\u0004 — \u0003זה הגונב דעת הבריות,\u0004 כגון \u0003שאין לו ממון אצל חבירו וטוענו\u0004 תביעת ממון \u0003ומשביעו,\u0004 וגורם לשבועת חינם, \u0003\"ואל בית הנשבע בשמי לשקר\"\u0004 — \u0003כמשמעו, \"ולנה בתוך ביתו וכלתו ואת עציו ואת אבניו\"\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת, דברים שאין אש ומים מכלין אותן,\u0004 כאבנים, \u0003שבועת שקר מכלה אותן.\u0004 עד כאן האזהרה שמזהירים את הנשבע.","\u0003אם אמר: \"איני נשבע\"\u0004 — \u0003פוטרין אותו מיד\u0004 ודנים בו את דין הראוי לו, שחייב לשלם. \u0003ואם אמר \"הריני נשבע\"\u0004 — \u0003העומדין שם אומרים זה לזה\u0004 את הפסוק: \u0003\"סורו נא מעל אהלי האנשים הרשעים האלה\"\u0004 פן תיספו בכל חטאתם\" (במדבר טז, כו). \u0003וכשמשביעין אותו, אומרים לו: הוי יודע, שלא על דעתך\u0004 לפי כוונתך \u0003אנו משביעין אותך, אלא על דעת המקום ועל דעת בית דין\u0004 לפי הכוונה שיש בליבם,","\u0003שכן מצינו במשה רבינו, כשהשביע את ישראל\u0004 על קיום התורה \u0003אמר להן: דעו, שלא על דעתכם אני משביע אתכם אלא על דעת המקום ועל דעתי, שנאמר: \"ולא אתכם לבדכם\u0004 אנכי כורת את הברית הזאת ואת האלה הזאת\" (דברים כט, יג), כלומר לא רק על דעתכם.","ואגב כך דורשים את המשך הכתוב: \u0003\"כי את אשר ישנו פה\"\u0004 (דברים כט, יד), \u0003אין לי אלא אותן העומדין על הר סיני\u0004 שהם בכלל שבועה זו, \u0003דורות הבאים ו\u0004כן \u0003גרים העתידין להתגייר מנין? תלמוד לומר: \"ואת אשר איננו\"\u0004 (דברים כט, יד).","\u0003ואין לי אלא\u0004 שהשבועה כוללת \u0003מצוה שקיבלו עליהם מהר סיני, מצו‍ת העתידות להתחדש\u0004 על ידי חכמים, \u0003כגון מקרא מגילה, מנין\u0004 שגם הן בכלל הברית והשבועה? \u0003תלמוד לומר\u0004 במגילת אסתר: \u0003\"קימו וקבלו...\u0004 להיות עושים את שני הימים האלה\" (אסתר ט, כז), \u0003קיימו\u0004 באותה שעה מצוות \u0003מה שקבלו\u0004 על עצמם \u0003כבר\u0004 בסיני בשבועה.","ותחילה מבררים את הדברים שבברייתא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"שבועת הדיינים \u0003אף היא בלשונה נאמרה\"?\u0004","\u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005],\u0006 \u0003אלו נאמרין בכל לשון: פרשת סוטה, וידוי מעשר\u0004 (לאחר השנה השלישית לשמיטה, שאז בא כל אדם למקדש ומתוודה שנתן את כל המעשרות כראוי), \u0003קריאת שמע, ותפלה, וברכת המזון, ושבועת העדות ושבועת הפקדון; וקאמר נמי\u0004 \u0005[ואמר גם כן]\u0006 בברייתא זו ש\u0003שבועת הדיינין אף היא בלשונה נאמרה,\u0004 שנאמרת בכל לשון.","ועוד שנינו בברייתא. \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003אומרין לו: הוי יודע, שכל העולם כולו נזדעזע בשעה שאמר הקדוש ברוך הוא: \"לא תשא את שם ה' אלהיך לשוא\".\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שכל העולם נזדעזע בשעה שאמר הקב\"ה מצוה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דאתיהב\u0004 \u0005[שניתנה]\u0006 \u0003בסיני,\u0004 שהעולם כולו נזדעזע אז, והרי \u0003עשר דברות\u0004 כולן \u0003נמי אתיהב\u0004 \u0005[גם כן ניתנו]\u0006 בסיני!","\u0003ואלא\u0004 תאמר \u0003משום דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה],\u0006 ושואלים: \u0003ומי חמירא\u0004 \u0005[והאם\u0006 היא \u0005חמורה\u0006 יותר\u0005]\u0006 משאר כל המצוות? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו הן\u0004 עבירות \u0003קלות\u0004 — \u0003עשה ולא תעשה, חוץ מ\"לא תשא\"\u0004 שהיא חמורה, \u0003חמורות\u0004 — \u0003זו כריתות ומיתות בית דין, ו\"לא תשא\" עמהן!\u0004 על כל פנים, אינה חמורה יותר מדברות אחרות שיש בהן עונש מיתה!","\u0003אלא\u0004 צריך לומר שהזעזוע והפחד המיוחד בזמן מתן מצוה זו, הוא \u0003כדקתני טעמא\u0004 \u0005[כמו ששנה\u0006 את \u0005טעם\u0006 הדבר\u0005]\u0006 בהמשך: \u0003וכל עבירות שבתורה נאמר בהן \"ונקה\", וכאן נאמר \"לא ינקה\".\u0004","ושואלים: \u0003וכל עבירות שבתורה לא נאמר בהן \"לא ינקה\"? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ונקה לא ינקה\"\u0004 (שמות לד, ז)!","ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 ונתפרש \u0003לכ\u0004 דברי \u0003ר' אלעזר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: אי אפשר לומר \"ונקה\"\u0004 שהקב\"ה מנקה על כל העבירות, \u0003ש\u0004הרי \u0003כבר נאמר \"לא ינקה\",\u0004 ומצד אחר, \u0003אי אפשר לומר \"לא ינקה\"\u0004 — \u0003שכבר נאמר \"ונקה\"! הא\u0004 \u0003כיצד? מנקה הוא לשבים, ואינו מנקה לשאינן שבים.\u0004","נאמר שם: \u0003כל עבירות שבתורה נפרעין ממנו, וכאן ממנו וממשפחתו.\u0004 ושואלים: \u0003וכל עבירות שבתורה ממשפחתו לא?\u0004","\u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במי שעובד למולך: \u0003\"ושמתי אני את פני באיש ההוא ובמשפחתו\u0004 והכרתי אותו\" (ויקרא כ, ה). \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון: אם הוא חטא, משפחתו מה חטאת?\u0004 ולמה הם נענשים? \u0003לומר לך: אין לך משפחה שיש בה מוכס\u0004 שגובה מסים שלא כדין, \u0003שאין כולה מוכסין\u0004 שכולם נחשבים כמוהו, \u0003ו\u0004כיוצא בזה אין משפחה \u0003שיש בה לסטים שאין כולה לסטים, מפני שמחפין עליו\u0004 ומגינים עליו!","ומשיבים: \u0003התם בדינא אחרינא\u0004 \u0005[שם,\u0006 בעבירות אחרות, נענשים הם \u0005בדין,\u0006 בעונש \u0005אחר],\u0006 קל יותר משלו, \u0003הכא בדינא דידיה\u0004 \u0005[כאן,\u0006 לענין שבועה, נענשת משפחתו \u0005בעונש שלו].\u0006 \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 \u0003\"והכרתי אותו\"\u0004 האמור בעובד למולך (ויקרא כ, ה), \u0003מה תלמוד לומר? לפי שנאמר\u0004 תחילה: \u0003\"ושמתי אני את פני\" ויקרא כ, ה),\u0004 \u0003יכול כל המשפחה כולה בהיכרת? תלמוד לומר:\u0004 \"והכרתי \u0003אותו\",\u0004 להדגיש: \u0003אותו בהיכרת, ולא כל המשפחה כולה בהיכרת,\u0004 אלא הם נענשים בעונש אחר.","ועוד נאמר בברייתא: \u0003וכל עבירות שבתורה נפרעין ממנו, וכאן ממנו ומכל העולם כולו, שנאמר: \"אלה וכחש\"\u0004 (הושע ד, ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"על כן תאבל הארץ\"\u0004 (ויקרא כ, ג). ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שאין נפרעים מכל העולם כולו \u0003עד דעביד להו\u0004 \u0005[שעושה\u0006 אותן\u0005]\u0006 את כל העבירות הללו \u0003לכולהו\u0004 \u0005[כולן]\u0006 האמורות באותו פסוק, \"אלה וכחש ורצח וגנב ונאף\"! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מפני אלה אבלה הארץ\"\u0004 (ירמיה כג, י), הרי שדי בעבירה זו להאביל את הארץ.","ושואלים: \u0003וכל עבירות שבתורה מכל העולם לא? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכשלו איש באחיו\"\u0004 (ויקרא כו, לז), וכוונתו \u0003איש בעון אחיו,\u0004 \u0003מלמד שכל ישראל ערבים זה בזה.\u0004 ואם כן, משמע שבכל חטא מחייב את כל העולם כולו בחטאיו!"],["ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003שיש\u0004 אפשרות \u0003בידם למחות ולא מיחו,\u0004 ואילו בענין שבועה מדובר גם במקום שלא היה בידם למחות.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה ההבדל]\u0006 \u0003בין רשעים\u0004 של \u0003משפחתו לרשעים דעלמא\u0004 \u0005[של העולם],\u0006 \u0003בין צדיקים\u0004 של \u0003משפחתו לצדיקים דעלמא\u0004 \u0005[של העולם]?\u0006","ומשיבים: \u0003הוא בשאר עבירות\u0004 שבתורה נענש \u0003בדיניה\u0004 \u0005[בדין שלו]\u0006 בעונש שכתוב בו, \u0003ורשעים\u0004 של \u0003משפחה\u0004 שמחפים עליו — \u0003בדין חמור, ורשעים דעלמא\u0004 \u0005[של העולם]\u0006 שיכלו למחות בו ולא מחו — \u0003בדין הקל.\u0004 \u0003צדיקי דהכא והכא\u0004 \u0005[הצדיקים של כאן וכאן],\u0006 אלו ממשפחתו שלא חיפו עליו, ואלו של העולם שלא יכלו למחות בידו, \u0003פטירי\u0004 \u0005[פטורים].\u0006","אבל \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שבועה\u0004 — \u0003הוא ורשעים\u0004 של \u0003משפחה\u0004 נידונים \u0003כדיניה\u0004 \u0005[כמו הדין שלו],\u0006 באותו עונש, \u0003ורשעים דעלמא\u0004 \u0005[של העולם],\u0006 אלו שיכלו למחות ולא מחו, נידונים \u0003בדין חמור, וצדיקי דהכא והכא\u0004 \u0005[והצדיקים של כאן וכאן]\u0006 של משפחתו ושל העולם, נידונים על כל פנים \u0003בדין הקל,\u0004 למרות שנהגו כשורה, ובזה חמור עונש השבועה משאר עבירות יותר.","שנינו בברייתא: \u0003אם אמר: \"איני נשבע\"\u0004 — \u0003פוטרין אותו מיד, ואם אמר: \"הריני נשבע\"\u0004 — \u0003העומדים שם אומרים זה לזה: \"סורו נא מעל אהלי האנשים הרשעים האלה\"\u0004 (במדבר טז, כו). ושואלים: \u0003בשלמא ההוא דקא משתבע קאי באיסורא\u0004 \u0005[נניח זה שנשבע עומד באיסור],\u0006 שהוא עומד להישבע לשקר, \u0003אלא ההוא דקא משבע ליה אמאי\u0004 \u0005[זה שמשביע אותו מדוע]\u0006 הוא נכלל בלשון \"האנשים הרשעים\"?","ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכמו ששנויה\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן טרפון אומר: \"שבעת ה' תהיה בין שניהם\"\u0004 (שמות כב, י) — \u0003מלמד שחלה שבועה\u0004 ועונשה \u0003על שניהם.\u0004","ועוד אמרו בברייתא \u0003וכשמשביעין אותו, אומרים לו: הוי יודע שלא על דעתך\u0004 אלא על דעת המקום ועל דעת בית דין. ואומרים: \u0003למה לי למימרא ליה הכי\u0004 \u0005[מדוע לו לומר כך]?\u0006 \u0003משום\u0004 המעשה ב\u0003קניא\u0004 \u0005[קנה]\u0006 של \u0003רבא,\u0004 שהנתבע הכניס את הכסף שהיה חייב לתובע בתוך מקל חלול, ונתנו לתובע להחזיק בו, ואז נשבע שכבר נתן לו. שאף שנשבע על האמת, מכל מקום היתה זו לפי דעתו, ולא לפי דעת בית הדין שהשביעוהו.","שנינו במשנה: כדי לחייב בשבועת מודה במקצת, צריכה \u0003הטענה\u0004 להיות \u0003שתי כסף.\u0004 ונחלקו רב ושמואל בפירוש המדוייק של הדברים. \u0003אמר רב:\u0004 כוונת הדברים היא, ש\u0003כפירת טענה שתי כסף\u0004 כלומר, כאשר הוא כופר בטענה, צריך שיהא הסכום שכופר בו שווה שתי כסף לפחות. \u0003ושמואל אמר:\u0004 דווקא ה\u0003טענה עצמה שתי כסף,\u0004 אבל לענין הכפירה, \u0003אפילו לא כפר אלא בפרוטה ולא הודה אלא בפרוטה\u0004 — \u0003חייב.\u0004","\u0003אמר רבא: דיקא מתניתין כותיה\u0004 \u0005[מדוייקת משנתנו כשיטתו]\u0006 של \u0003רב, וקראי כותיה\u0004 \u0005[והמקראות\u0006 מדוייקים \u0005כשיטתו]\u0006 של \u0003שמואל. דיקא מתניתין כותיה\u0004 \u0005[מדוייקת משנתנו כשיטתו]\u0006 של \u0003רב, דקתני\u0004 \u0005[ששנה]:\u0006 \u0003הטענה שתי כסף וההודאה שוה פרוטה, ואילו כפירת טענה\u0004 שהיא שוה \u0003פרוטה לא קתני\u0004 \u0005[שנה].\u0006 \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 במשנה אחרת ברשימת דברים שדינם בשווה פרוטה: \u0003ההודאה\u0004 שיעורה \u0003בפרוטה, ואילו כפירה בפרוטה לא קתני\u0004 \u0005[שנה],\u0006 משמע שהיא בשיעור שונה.","ומצד אחר, \u0003וקראי כותיה\u0004 \u0005[והמקראות\u0006 מדוייקים \u0005כשיטתו]\u0006 של \u0003שמואל, דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת מודה במקצת: \u0003\"כי יתן איש אל רעהו כסף או כלים לשמר\"\u0004 (שמות כב ו), ולמדים משם להשוות את הכלים והכסף, \u0003מה כלים\u0004 הם לפחות \u0003שנים\u0004 (לשון רבים), \u0003אף כסף שנים\u0004 (שתי כסף), ומן הצד השני, \u0003מה כסף דבר חשוב אף כל דבר חשוב, וקאמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 שיש לחייב שבועה במקרה \"אשר יאמר \u0003כי הוא זה\"\u0004 (שמות כב ח), שהנתבע מודה במקצת טענה זו של \"כסף או כלים\", וכופר במקצת ממנה, כלומר גם בפחות משתי כסף.","\u0003ורב,\u0004 כיצד מסביר הוא את הכתוב? \u0003ההוא\u0004 \"כי הוא זה\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 רק \u0003להודאה במקצת הטענה.\u0004 שהביטוי משמעו שהנתבע מודה במקצת, אבל אין מדובר על הכפירה, שהיא צריכה להיות שתי כסף לפחות. \u0003ושמואל\u0004 מהיכן הוא למד דין זה? \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003\"הוא\" וכתיב\u0004 \u0005[כתוב]\u0006 \u0003\"זה\",\u0004 והרי זו כפילות, ללמדנו \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כפר במקצת ואודי\u0004 \u0005[והודה]\u0006 \u0003במקצת\u0004 — \u0003חייב.\u0004","\u0003ורב\u0004 כיצד הוא מסביר את הכפילות? \u0003חד\u0004 \u0005[אחד]\u0006 \u0003להודאה במקצת הטענה, וחד\u0004 \u0005[ואחד]\u0006 \u0003להודאה\u0004 שצריכה להיות \u0003ממין הטענה. ושמואל,\u0004 מה הוא משיב לכך? הרי יש צורך ללמוד דבר זה! הוא סבור שגם אם אין הכתוב מיותר, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003ממילא שמעת מיניה\u0004 \u0005[למדת ממנו]\u0006 ש\u0003חסרה לה טענה?\u0004 שהרי אם הטענה היא שתי כסף (כפי שלמדנו מן הכתוב \"כי יתן... כסף או כלים\") והודה במקצת, נמצא ממילא שהוא כופר בפחות משתי כסף! ובאמת יש בכך קושי על שיטת רב, שהרי גם הוא מודה לכאורה שהטענה שתי כסף.","\u0003אלא אמר לך\u0004 \u0005[אומר לך]\u0006 \u0003רב: \"כסף\" כי אתא מעיקרא\u0004 \u0005[כאשר בא מתחילה]\u0006 בכתוב (\"כי יתן... כסף\") ולמדנו שהוא שתי כסף, \u0003לכפירה הוא דאתא\u0004 \u0005[שבא],\u0006 שכופר בטענה בשווה שתי כסף, ולא שהטענה עצמה שתי כסף. ש\u0003אם\u0004 לא נפרש \u0003כן, לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק: \u0003\"כי יתן איש אל רעהו כלים לשמר\", ואנא אמינא\u0004 \u0005[ואני אומר]:\u0006 \u0003מה כלים שנים אף כל שנים,\u0004 ובכלל זה שתי כסף, ואם כן \u0003\"כסף\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי? אם אינו ענין לטענה,\u0004 שלא נתחדש בה דבר על ידי ההוספה \"כסף\", \u0003תנהו ענין לכפירה,\u0004 שאין כפירה בפחות מסכום זה.","\u0003ושמואל,\u0004 מה הוא למד מייתור זה? \u0003אמר לך\u0004 \u0005[אומר הוא לך]:\u0006 \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 \u0003\"כלים\" ולא כתב\u0004 \u0005[היתה כותבת]\u0006 \u0003\"כסף\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003כלים שנים אף כל שנים, אבל דבר חשוב לא בעינן\u0004 \u0005[אין אנו צריכים],\u0006 ומדובר כשטוען אף על דברים חסרי ערך, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שצריך להיות כמו הכסף, שהוא דבר חשוב.","ומנסים להביא ראיה ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"שתי כסף יש לי בידך\",\u0004 והשיב הנתבע: \u0003\"אין לך בידי אלא פרוטה\"\u0004 — \u0003פטור; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003חסרה לה טענה,\u0004 שכיון שהודה בפרוטה נמצא שהכפירה היא בשתי כסף חסר פרוטה? \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 על דבריו של \u0003שמואל!\u0004","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003שמואל: מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003שוה קתני\u0004 \u0005[שנה]?\u0006 שתובעו שווה שתי כסף? \u0003דוקא קתני\u0004 \u0005[שנה],\u0006 שתובעו ממש שתי מטבעות כסף. וכיון שהודה בפרוטה על נחושת נמצא כי \u0003מה שטענו לא הודה לו, ומה שהודה לו לא טענו,\u0004 ודווקא משום כך הוא פטור.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך\u0006 אתה מפרש\u0005],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה,\u0006 המשכה של המשנה\u0005]:\u0006 \u0003\"שתי כסף ופרוטה יש לי בידך\", \"אין לך בידי אלא פרוטה\"\u0004 — \u0003חייב; אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמדובר במשנה בתובע \u0003שוה\u0004 שתי כסף — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003חייב\u0004 במקרה זה, שלא כבמקרה הקודם, משום שכאן הוא כופר בשתי כסף. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר בכסף \u0003דוקא,\u0004 שתבעו שתי מטבעות כסף וגם פרוטה — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הרי גם במקרה זה, \u0003מה שטענו\u0004 (מטבעות כסף) \u0003לא הודה לו,\u0004 ובזה כפר הנתבע בכל, \u0003ומה שהודה לו לא טענו!\u0004","ודוחים: \u0003מידי הוא טעמא\u0004 \u0005[כלום הוא\u0006 \u0005הטעם,\u0006 ההסבר\u0005]\u0006 \u0003אלא ל\u0004שיטת \u0003שמואל,\u0004 לשיטתו אין זו קושיה כלל, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב נחמן אמר שמואל: טענו חטין ושעורין\u0004 יחד \u0003והודה לו באחד מהן\u0004 — \u0003חייב\u0004 שהרי כפר במקצת טענתו. ואף כאן, טענו בשתי כסף ובפרוטה, שהיא טענה אחת, והודה לו בפרוטה, ולשיטת שמואל נחשב הדבר כהודאה במקצת.","ומעירים: כהבנה זאת שמדובר במשנה בתובע שתי מטבעות כסף, \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסופה,\u0006 בהמשכה של המשנה\u0005]:\u0006 \u0003\"ליטרא זהב יש לי בידך\",\u0004 והשיב לו: \u0003\"אין לך בידי אלא ליטרא כסף\"\u0004 — \u0003פטור; אי אמרת בשלמא\u0004 \u0005[אם אומר אתה]\u0006 כשיטת רב, ש\u0003דוקא קתני\u0004 \u0005[שנה]\u0006 במשנה, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003פטור\u0004 במקרה זה, שהרי הודה שלא ממין הטענה, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמדובר במשנה במי שתובע \u0003שוה\u0004 כסף, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור\u0004 כשאמר \"אין לך בידי אלא ליטרא כסף\"? והרי \u0003ליטרא\u0004 כסף \u0003טובא הוי\u0004 \u0005[הרבה הוא],\u0006 ובכלל זה בוודאי כפירה של שתי כסף!","\u0003אלא מדסיפא\u0004 \u0005[מ\u0006תוך ש\u0005סופה]\u0006 של המשנה מדבר שטענו בכסף \u0003דוקא\u0004 ולא בשווה כסף, \u0003רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 מדבר בטוען שתי כסף \u0003דוקא.\u0004","ואם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על שיטתו של \u0003רב?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב: כולה מתניתין\u0004 \u0005[כל משנתנו]\u0006 מדברת בטוענו \u0003שוה\u0004 כסף, כשיטתי, \u0003ו\u0004אולם המקרה שטוען \u0003ליטרא זהב שאני\u0004 \u0005[שונה],\u0006 ששם הוא תובע זהב דווקא, שהרי אינו תובעו סכום מסויים של דינרי זהב, אלא זהב במשקל."],["\u0003תדע\u0004 שמשנתנו עוסקת בשאר ההלכות בשווה, \u0003דקא תני סיפא\u0004 \u0005[שהוא שונה בסופה]\u0006 בהמשכה של המשנה: הטוען \u0003\"דינר זהב לי בידך\",\u0004 והנתבע אומר: \u0003\"אין לך בידי אלא דינר כסף וטריסית ופונדיון ופרוטה\"\u0004 — \u0003חייב, שהכל מין מטבע [אחת] הן; אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר בטוען ב\u0003שוה\u0004 דינר זהב — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003חייב,\u0004 שהרי מודה במקצת הסכום שנתבע, \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר בטוען דינר זהב \u0003דוקא\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הרי טענו זהב והודה לו בכסף או נחושת!","\u0003אמר ר' אלעזר:\u0004 כאן מדובר \u0003בשטענו בדינר מטבעות,\u0004 כלומר טענו שהוא חייב לו מטבעות בשווי דינר זהב, ובכלל זה כל מטבע שהוא. ונמצא שההודאה ממין הטענה היא. \u0003ו\u0004אף שאין בזה לעצמו חידוש, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 בדין זה ש\u0003פרוטה בכלל מטבע איתא\u0004 \u0005[ישנה],\u0006 והמודה בה נחשב כמודה במקצת כשתובע ממנו מטבעות. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 הדבר מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 את ההסבר לדין זה: \u0003שהכל מין מטבע אחת.\u0004","ושואלים: \u0003ורב\u0004 שסבור כי מדובר בתביעה של שווה כסף, כיצד מסביר הוא נימוק זה? ומה משנה אם מין אחד הם או לא? ומשיבים: לדעתו הנימוק הוא שונה, \u0003שהכל דין מטבע אחת\u0004 כלומר, הואיל והמשנה מדברת בשווה כסף, ולא בדווקא, אם כן כל המטבעות דין מטבע אחת יש להן (ר\"י מיגאש).","ואגב כך שואלים: \u0003ור' אלעזר, לימא\u0004 \u0005[האם לומר],\u0006 \u0003מדסיפא\u0004 \u0005[מ\u0006כך \u0005ש\u0006את \u0005סופה]\u0006 של המשנה \u0003כשמואל\u0004 הוא \u0003מתרץ, רישא נמי\u0004 \u0005[תחילתה גם כן]\u0006 \u0003כשמואל סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שיש לפרשה בדווקא, שהוא סבור כמותו לענין כפירת טענה?","ודוחים: \u0003לא, סיפא\u0004 \u0005[סופה]\u0006 \u0003דוקא\u0004 מפרש בשיטה זו, משום שכך נראית לו משמעות המשנה, \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003שהכל מין מטבע אחת, ו\u0004אולם \u0003רישא\u0004 \u0005[תחילתה]\u0006 אין אנו יודעים אם הוא מפרש \u0003כרב או כשמואל.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 עוד ראיה לענין השאלה האם מדובר במשנתנו בתביעה בדווקא או בשווה כסף, ממה ששנינו בברייתא, שהטוען: \u0003\"דינר זהב זהוב לי בידך\",\u0004 והשיב לו הנתבע: \u0003\"אין לך בידי אלא דינר כסף\"\u0004 — \u0003חייב,\u0004 משום שתבע ממנו מטבע, וזה כפר לו במטבע. ועל כל פנים לענייננו נדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"זהב זהוב\"\u0004 משמעו מטבע זהב, \u0003הא סתמא\u0004 \u0005[אבל בסתם]\u0006 אם היה אומר רק \"דינר זהב\" — \u0003שוה קאמר ליה\u0004 \u0005[אומר לו],\u0006 וכדברי רב!","\u0003אמר רב אשי,\u0004 אפשר לתרץ לדברי שמואל כי \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003כל האומר \"דינר זהב\", כאומר \"דינר זהב זהוב\" דמי\u0004 \u0005[נחשב],\u0006 וכוונתו דווקא למטבע של דינר.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא שיש בה \u0003לסיועיה\u0004 \u0005[לסייע]\u0006 \u0003לרב:\u0004 הטוען לחבירו: \u0003\"סלע לי בידך\",\u0004 והשיב לו: \u0003\"אין לך בידי\u0004 \u0003אלא סלע חסר שתי כסף\"\u0004 — \u0003חייב,\u0004 ואם אמר שיש לו בידו רק סלע \u0003חסר מעה\u0004 — \u0003פטור.\u0004 משמע שכיון שלא היתה הכפירה בשתי כסף — אינו חייב שבועה, וכרב.","\u0003אמר רב נחמן בר יצחק אמר שמואל: לא שנו\u0004 שצריכה הטענה להיות בשווי שתי כסף כדי לחייב שבועה, \u0003אלא בטענת מלוה והודאת לוה\u0004 במקצת, \u0003אבל\u0004 במקרה אחר שחייב אדם שבועה לחבירו, ב\u0003טענת מלוה והעדאת עד אחד\u0004 כדברי המלוה, שחייב הלווה להישבע כדי להכחיש את העד, \u0003אפילו לא טענו\u0004 המלוה \u0003אלא בפרוטה\u0004 — \u0003חייב.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במקור לחיוב שבועה זו: \u0003\"לא יקום עד אחד באיש לכל עון ולכל חטאת\"\u0004 (דברים יט, ט), ונדייק מכאן: \u0003לכל עון ולכל חטאת הוא\u0004 ש\u0003אינו קם,\u0004 שאין מחייבים אדם בעונש על סמך עדות עד אחד, \u0003אבל קם הוא\u0004 עד אחד ומועיל \u0003ל\u0004חיוב \u0003שבועה. ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל מקום ששנים מחייבין אותו ממון\u0004 בעדותם, \u0003עד אחד מחייבו שבועה.\u0004 וכיון ששני עדים מחייבים אדם בכל תביעת ממון מפרוטה ומעלה, אף עד מחייבו שבועה בכגון זה.","\u0003ואמר רב נחמן אמר שמואל: טענו חטין ושעורין והודה לו באחד מהן\u0004 — \u0003חייב.\u0004","\u0003אמר לו ר' יצחק: יישר\u0004 יפה אמרת, \u0003וכן אמר ר' יוחנן.\u0004 ושואלים: כיון שדייק ר' יצחק לומר שכך אומר ר' יוחנן, האם נלמד \u0003מכלל\u0004 זה \u0003דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 \u0003ריש לקיש\u0004 בענין זה? ומשיבים: באותו ענין לא היתה דרך לברר את דעת ריש לקיש. ומפרטים, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003מישהא הוה שהי ליה\u0004 \u0005[שוהה היה לו]\u0006 וממתין לסיום דברי ר' יוחנן \u0003ושתיק ליה\u0004 \u0005[ושותק לו],\u0006 ולא ידע ר' יצחק האם לאחר מכן חלק עליו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003מישתא הוה שתי ליה\u0004 \u0005[שותה היה\u0006 ריש לקיש \u0005באותה שעה]\u0006 \u0003ושתיק ליה\u0004 \u0005[ושותק לו],\u0006 ולא הגיב.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שנסייע לו]\u0006 מלשון משנתנו: \u0003טענו חטין והודה לו בשעורין\u0004 — \u0003פטור, ורבן גמליאל מחייב.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003טענו חטין והודה לו בשעורין\u0004 הדין כן, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה טוענו \u0003חטין ושעורין והודה לו באחד מהן\u0004 — \u0003חייב!\u0004","ודוחים: אפשר לומר \u0003לא, הוא הדין\u0004 ש\u0003אפילו\u0004 טוענו \u0003חטין ושעורין נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, והאי דקמיפלגי\u0004 \u0005[וזה שהם חלוקים]\u0006 \u0003ב\u0004טוענו \u0003חטין\u0004 דווקא, הרי זה מנוסח בצורה זו כדי \u0003להודיעך כחו\u0004 של \u0003רבן גמליאל,\u0004 כמה היה מחייב שבועה, אפילו במודה שלא ממין הטענה כלל.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003טענו כלים וקרקעות, הודה בכלים וכפר בקרקעות, בקרקעות וכפר בכלים\u0004 — \u0003פטור,\u0004"],["\u0003הודה במקצת קרקעות\u0004 — \u0003פטור, במקצת כלים\u0004 — \u0003חייב.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום שטענו \u0003כלים וקרקעות,\u0004 ש\u0003קרקע לאו\u0004 \u0005[אינה]\u0006 \u0003בת שבועה היא, הא\u0004 \u0005[אבל]\u0006 אם היה טוענו \u0003כלים וכלים\u0004 שני מיני מיטלטלים, כגון חיטים ושעורים, \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כלים וקרקעות,\u0004 והודה באחד מהם — \u0003חייב!\u0004","ודוחים: \u0003הוא הדין\u0004 ש\u0003אפילו כלים וכלים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003כלים וקרקעות\u0004 — \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003הודה במקצת כלים\u0004 — \u0003חייב\u0004 שבועה \u0003אף על הקרקעות.\u0004","ומקשים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 במשנה זו, את ההלכה ש\u0003זוקקין?\u0004 הרי כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 במסכת קידושין: נכסים שאין להם אחריות \u0003זוקקין את הנכסים שיש להן אחריות לישבע עליהן!\u0004","ומשיבים: \u0003הא\u0004 \u0005[זו]\u0006 ההלכה במשנה כאן \u0003עיקר,\u0004 שהיא מדברת כולה בדין שבועות, \u0003ההיא\u0004 במסכת קידושין \u0003אגב גררא נסבה\u0004 \u0005[דרך גרירה לקחה],\u0006 שמתוך ששנו שם שנכסים שאין להם אחריות נקנים עם נכסים שיש להם אחריות, הוסיפו בדרך אגב גם דין הזקקה לשבועה. עד כאן דנו בשיטת שמואל.","\u0003ור' חייא בר אבא אמר ר' יוחנן: טענו חטין ושעורין והודה לו באחת מהן\u0004 — \u0003פטור.\u0004 ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק\u0004 על דברי שמואל: \u0003יישר, וכן אמר ר' יוחנן,\u0004 הרי שדעתו של ר' יוחנן כשמואל! ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[אמוראים הם]\u0006 שנחלקו בדבר זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יוחנן.\u0004 ומביאים ראיות נגד דברי ר' חייא בר אבא בשם ר' יוחנן.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003טענו חטין והודה לו בשעורין\u0004 — \u0003פטור, ורבן גמליאל מחייב.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003טענו חטין והודה לו בשעורין\u0004 פטור, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה טוענו \u0003חטין ושעורין והודה לו באחד מהן\u0004 — \u0003חייב!\u0004","ודוחים: \u0003הוא הדין\u0004 ש\u0003אפילו חטין ושעורין נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, והאי דקתני הכי\u0004 \u0005[וזה ששנה כך]\u0006 — \u0003להודיעך כחו\u0004 של \u0003רבן גמליאל,\u0004 עד כמה הוא מחייב שבועה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003טענו כלים וקרקעות, והודה בכלים וכפר בקרקעות, בקרקעות וכפר בכלים\u0004 — \u0003פטור. הודה במקצת קרקע\u0004 — \u0003פטור, במקצת כלים\u0004 — \u0003חייב.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שטענו \u0003כלים וקרקעות\u0004 פטור, ש\u0003קרקע לאו בת שבועה היא, הא\u0004 \u0005[אבל]\u0006 אם טענו \u0003כלים וכלים דומיא\u0004 \u0005[בדומה]\u0006 לדין של \u0003כלים וקרקעות\u0004 כלומר, משני מינים — \u0003חייב\u0004 שבועה!","ודוחים: \u0003הוא הדין\u0004 ש\u0003אפילו כלים וכלים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003הודה במקצת כלים\u0004 — \u0003חייב אף על הקרקעות.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בכך? דין \u0003זוקקין?\u0004 הרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה במסכת קידושין: נכסים שאין להם אחריות \u0003זוקקין את הנכסים שיש להן אחריות לישבע עליהן!\u0004 ומסבירים: \u0003הא\u0004 \u0005[זו]\u0006 משנתנו \u0003עיקר\u0004 ההלכה היא, \u0003ההיא אגב גררא נסבה\u0004 \u0005[דרך גרירה לקחה].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא בר ממל לר' חייא בר אבא,\u0004 שנינו בברייתא: \u0003טענו שור והודה לו בשה,\u0004 או טענו \u0003שה והודה לו בשור\u0004 — \u0003פטור, טענו בשור ושה והודה לו באחד מהן\u0004 — \u0003חייב!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבן גמליאל היא,\u0004 שמחייב אפילו במודה שלא ממין הטענה. הקשה לו: \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003רבן גמליאל\u0004 היא, \u0003אפילו רישא נמי\u0004 \u0005[ראשה גם כן],\u0006 בכופר בשור ומודה בשה, צריך להתחייב שבועה!","\u0003אלא, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003אדמון היא,\u0004 שהוא סבור מצד אחד שההודאה צריכה להיות ממין הטענה, ומצד אחר הוא סבור שהתובע את חבירו כדי שמן, והלה מודה לו בקנקנים — חייב שבועה. וסברתו היא שהתובע דורש גם את הקנקנים וגם את השמן, וכיון שהודה בקנקנים הריהו כמודה במקצת הטענה. והוסיף ר' חייא בר אבא ואמר: \u0003ולא דחויי מדחינא לך\u0004 \u0005[ואין אני מדחה אותך],\u0006 בלבד בתירוץ כלשהו, \u0003אלא תלמוד ערוך הוא בפיו של ר' יוחנן: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003אדמון היא.\u0004","\u0003אמר רב ענן אמר שמואל:\u0004 מי שרצה לתבוע מחבירו חיטים ושעורים, \u0003טענו חטין וקדם\u0004 הנתבע \u0003והודה לו בשעורין, אם כמערים\u0004 להודות לפני שימשיך התובע בתביעתו ויתבע גם את השעורים — \u0003חייב\u0004 להישבע, \u0003אם במתכוין\u0004 להודות רק בשעורים — \u0003פטור.\u0004","\u0003ואמר רב ענן אמר שמואל: טענו שתי מחטין והודה לו באחת מהן\u0004 — \u0003חייב; לפיכך יצאו כלים\u0004 ונתפרשו בכתוב \u0003למה שהן\u0004 שלא הגדירה התורה באלה כלים מדובר, ובכל כלי, אפילו זול וקטן ביותר, קיים דין מודה במקצת.","\u0003אמר רב פפא: טענו כלים ופרוטה, והודה בכלים וכפר בפרוטה\u0004 — \u0003פטור. הודה בפרוטה וכפר בכלים\u0004 — \u0003חייב.\u0004","ומעירים: שתי הלכות אלה, \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כרב וחדא\u0004 \u0005[ואחת]\u0006 \u0003כשמואל. חדא\u0004 \u0005[אחת],\u0006 הראשונה, שאם כפר בפרוטה פטור — \u0003כרב,\u0004 ש\u0003אמר: כפירת טענה שתי כסף. חדא\u0004 \u0005[אחת],\u0006 השניה, שאם כפר בכלים חייב — \u0003כשמואל,\u0004 ש\u0003אמר: טענו חטין ושעורין והודה לו באחת מהן\u0004 — \u0003חייב.\u0004","שנינו במשנה: טענו \u0003\"מנה לי בידך\",\u0004 והשיב לו: \u0003\"אין לך בידי\"\u0004 — \u0003פטור. אמר רב נחמן:\u0004 אמנם פטור מדין תורה, \u0003ו\u0004מכל מקום \u0003משביעין אותו\u0004 את הנתבע \u0003שבועת היסת,\u0004 שבועה שתיקנו חכמים. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003חזקה אין אדם תובע אלא אם כן יש לו עליו.\u0004 ואף שהנתבע כופר בכל ראוי לברר הדבר בכל האפשר על ידי שבועה.","ומקשים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005]\u0006 \u0003חזקה אין אדם מעיז פניו בפני בעל חובו,\u0004 ואם כופר הכל — מן הסתם אמת הוא אומר! ומשיבים: ניתן להבין שאף כפירה בכל אינה העזת פנים גמורה, אלא \u0003אשתמוטי הוא דקא משתמיט ליה\u0004 \u0005[משתמט הוא לו],\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 הנתבע בלבו: אדחה את הפרעון \u0003עד דהוה\u0004 \u0005[שיהיה]\u0006 \u0003לי ופרענא ליה\u0004 \u0005[ואפרע לו].\u0006","\u0003תדע,\u0004 שיש סברה לומר שהכופר בהלואה אינו שקרן גמור. ש\u0003אמר רב אידי בר אבין אמר רב חסדא: הכופר במלוה\u0004 — אף שהוכח שכפר בשקר — \u0003כשר לעדות,\u0004 אבל אם כפר \u0003בפקדון\u0004 — \u0003פסול לעדות.\u0004 וטעם הדבר כפי שאמרנו, שהכופר במלוה יתכן שאינו אלא דוחהו לפי שעה. אבל בפקדון אין מקום להשתמטות, ואם אינו מחזיר לו — משמע שרצונו לקנות ממנו.","\u0003רב חביבא מתני אסיפא\u0004 \u0005[שונה את\u0006 דברי רב נחמן על \u0005סופה]\u0006 של המשנה. ששנינו, טענו: \u0003\"מנה לי בידך\", אמר לו\u0004 הנתבע: \u0003\"הן\", למחר אמר לו\u0004 התובע: \u0003\"תנהו לי\",\u0004 וענה לו: \u0003\"נתתיו לך\"\u0004 לאחר שהודיתי — \u0003פטור. ואמר רב נחמן:\u0004 אף על פי כן \u0003משביעין אותו שבועת היסת.\u0004","ומסבירים את הבדל השיטות: \u0003מאן דמתני ארישא\u0004 \u0005[מי ששונה\u0006 דברי רב נחמן \u0005על ראשה]\u0006 של המשנה, שמחייב שבועה במקרה שכפר בעצם החוב, \u0003כל שכן אסיפא\u0004 \u0005[על סופה],\u0006 הוא מחייבו בשבועת היסת, שהרי הודה לו מתחילה שהוא חייב לו."],["\u0003ומאן דמתני לה אסיפא\u0004 \u0005[ומי ששונה\u0006 דברי רב נחמן \u0005על סופה],\u0006 הרי זה בדווקא, שהוא סבור שיש לחלק: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הוא דאיכא דררא דממונא\u0004 \u0005[שיש גרר של ממון],\u0006 שיש אחיזה לטענה, ולכן יש מקום לחייבו שבועה, \u0003אבל התם דליכא דררא דממונא\u0004 \u0005[שם שאין גרר של ממון]\u0006 שאין לו כל אחיזה ובסיס מוקדם לטענתו — \u0003לא,\u0004 אין משביעים אותו אף שבועת היסת.","הואיל והזכרנו שבועת היסת מבררים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין שבועה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003לשבועה דרבנן\u0004 \u0005[מדברי חכמים],\u0006 שבועת היסת? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 \u0003מיפך\u0004 \u0005[היפוך]\u0006 \u0003שבועה,\u0004 שהנתבע אומר: אני איני רוצה להישבע, שיישבע התובע ויטול. \u0003בדאורייתא לא מפכינן\u0004 \u0005[בשל תורה אין אנו מהפכים]\u0006 \u0003שבועה,\u0004 אלא ישבע החייב להישבע או שישלם, \u0003בדרבנן מפכינן\u0004 \u0005[בשל חכמים אנו מהפכים].\u0006","ושואלים: \u0003ול\u0004דעת \u0003מר בר רב אשי\u0004 ש\u0003אמר: בדאורייתא נמי מפכינן\u0004 \u0005[בשל התורה גם כן אנו מהפכים]\u0006 \u0003שבועה,\u0004 אם כן לשיטתו \u0003מאי איכא בין דאורייתא לדרבנן\u0004 \u0005[מה\u0006 הבדל \u0005יש בין\u0006 שבועה \u0005של התורה ל\u0006שבועה \u0005של\u0006 \u0005דברי חכמים]?\u0006 ומשיבים: \u0003איכא בינייהו מיחת לנכסיה\u0004 \u0005[יש ביניהם\u0006 הבדל לענין \u0005ירידה לנכסיו],\u0006 ולגבות מן המחוייב שבועה שלא נשבע, \u0003בדאורייתא נחתינן לנכסיה\u0004 \u0005[בשל התורה יורדים אנו לנכסיו],\u0006 \u0003בדרבנן לא נחתינן לנכסיה\u0004 \u0005[בשל חכמים אין אנו יורדים לנכסיו].\u0006","ושואלים: \u0003ול\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר: בדרבנן נמי נחתינן לנכסיה\u0004 \u0005[בשל חכמים גם כן יורדים אנו לנכסיו],\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מציאת חרש שוטה וקטן,\u0004 אף שאין בהם דעת ואין להם יכולת קנין מדין תורה, מכל מקום הלוקח מהם מציאה שמצאו — \u0003יש בהם גזל מפני דרכי שלום,\u0004 שלא יבוא הדבר לידי ריב, \u0003ר' יוסי אומר: גזל גמור\u0004 הוא. \u0003ואמר רב חסדא: גזל גמור מדבריהם\u0004 (מדברי סופרים), ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזו]\u0006 אם גזל גמור הוא — לענין \u0003להוציאו בדיינין,\u0004 שיורדים לנכסיו של הגזלן ונוטלים ממנו בעל כורחו. ואם כן לשיטת ר' יוסי, שגם בדבר שהוא מדברי סופרים יורדים לנכסיו, \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש],\u0006 \u0003בין דאורייתא לדרבנן\u0004 \u0005[\u0006שבועה \u0005של התורה ל\u0006שבועה \u0005של דברי חכמים]?\u0006","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה \u0003שכנגדו\u0004 (שהנתבע) \u0003חשוד על השבועה, בדאורייתא\u0004 \u0005[ב\u0006שבועה \u0005של התורה]\u0006 — כאשר \u0003שכנגדו חשוד על השבועה אפכינן ליה\u0004 \u0005[אנו מהפכים לו]\u0006 את חובת ה\u0003שבועה ושמו אאידך\u0004 \u0005[על האחר],\u0006 שישבע התובע ויטול. \u0003בדרבנן\u0004 \u0005[ב\u0006שבועה \u0005של חכמים]\u0006 — הרי היא עצמה \u0003תקנתא\u0004 \u0005[תקנה]\u0006 \u0003היא, ותקנתא לתקנתא לא עבדינן\u0004 \u0005[ותקנה לתקנה אין אנו עושים].\u0006","ושואלים: \u0003ולרבנן דפליגי עליה\u0004 \u0005[ול\u0006שיטת \u0005חכמים שחלוקים על]\u0006 \u0003ר' יוסי,\u0004 ש\u0003אמרו: בדרבנן לא נחתינן לנכסיה\u0004 \u0005[בשל חכמים אין אנו יורדים לנכסיו],\u0006 \u0003מאי עבדינן ליה\u0004 \u0005[מה עושים אנו לו],\u0006 לזה שנתחייב להישבע ואינו רוצה? ומשיבים: \u0003משמתינן ליה\u0004 \u0005[מנדים,\u0006 מחרימים \u0005אותו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: האי נקטיה בכובסיה דנשבקיה לגלימיה הוא\u0004 \u0005[זה\u0006 הוא כמו \u0005אוחזו באשכיו\u0006 כדי \u0005שיעזוב את גלימתו הוא]\u0006 כלומר, אם מנדים אותו עד שיישבע, הריהו לחץ כבד, וכמוהו כירידה לנכסיו שנוהגים בשבועה של תורה! \u0003אלא\u0004 אם אין מנדים אותו \u0003מאי עבדינן ליה\u0004 \u0005[מה עושים אנו לו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003משמתינן ליה עד דמטי זמן נגדיה\u0004 \u0005[מנדים אותו עד שיגיע זמן הלקאתו],\u0006 כלומר שלושים יום, \u0003ו\u0004כשמגיע הזמן ולא התפשר עם התובע \u0003נגדינן ליה ושבקינן ליה\u0004 \u0005[מלקים אותו ועוזבים אותו].\u0006","\u0003אמר רב פפא: האי מאן דאפיק שטרא על חבריה\u0004 \u0005[מי שהוציא שטר\u0006 חוב \u0005על חבירו],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 הנתבע: \u0003שטרא\u0004 \u0005[שטר]\u0006 \u0003פרוע הוא,\u0004 שכבר שילמתי לך את החוב, ומפני סיבה כלשהי לא קבלתי את שטרי בחזרה — \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003לאו כל כמינך\u0004 \u0005[אין זה בכוחך]\u0006 להכחיש על ידי טענה בלבד את השטר הכתוב, אלא \u0003זיל שלים\u0004 \u0005[לך שלם].\u0006 \u0003ואם אמר\u0004 הנתבע: \u0003לשתבע\u0004 \u0005[שיישבע]\u0006 \u0003לי\u0004 שלא נפרע ממני — \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 לתובע: \u0003אשתבע ליה\u0004 \u0005[הישבע לו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: ומה בין זה לפוגם את שטרו?\u0004 כלומר, מי שיש בידו שטר חוב על אחרים והודה שכבר נפרע חלק ממנו, שאמרו חכמים שאינו יכול לגבות את השאר אלא בשבועה שלא קיבל יותר משאמר? הרי לפי דברי רב פפא, כל בעל שטר צריך להישבע, אף שלא נפגם שטרו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם אף על גב דלא טעין איהו\u0004 \u0005[שם,\u0006 בפוגם שטרו, \u0005אף על פי שלא טוען הוא]\u0006 הנתבע — \u0003טענינן ליה אנן\u0004 \u0005[טוענים אנו לו\u0006 עבורו\u0005]:\u0006 שמא שילם לך יותר ממה שאתה אומר, ומחייבים אותו להישבע. \u0003הכא אמרינן ליה\u0004 \u0005[כאן,\u0006 כשאין התובע פוגם שטרו, \u0005אומרים אנו לו]\u0006 לנתבע: \u0003זיל שלים ליה\u0004 \u0005[לך שלם לו],\u0006 ככתוב בשטר. \u0003ואי טעין ואמר אשתבע לי\u0004 \u0005[ו\u0006רק \u0005אם הוא טוען ואומר: הישבע לי]\u0006 — \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 לתובע בעל השטר: \u0003זיל אשתבע ליה\u0004 \u0005[לך הישבע לו].\u0006 \u0003ואי צורבא מרבנן\u0004 \u0005[ואם תלמיד חכם]\u0006 \u0003הוא\u0004 — \u0003לא משבעינן ליה\u0004 \u0005[אין אנו משביעים אותו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי:\u0004 \u0003צורבא מרבנן משלח גלימא דאינשי\u0004 \u0005[\u0006וכי \u0005תלמיד חכם פושט גלימות אנשים]?\u0006 וכי מפני שתלמיד חכם הוא יטול ממון שיש עליו טענה? \u0003אלא\u0004 אם תלמיד חכם הוא \u0003לא מזדקקינן ליה לדיניה\u0004 \u0005[אין אנו מזדקקים לו לדינו].\u0006","שנינו במשנה: הטוען לחבירו \u0003מנה לי בידך,\u0004 והודה לו, ואמר לו התובע: אל תפרעני אלא בעדים, וכשחזר ותבעו אומר הנתבע: כבר נתתיו לך — פטור. ובענין זה מביאים מה ש\u0003אמר רב יהודה אמר רב אסי: המלוה את חבירו בעדים\u0004 — \u0003צריך לפורעו בעדים,\u0004 ואם אין לו עדים שפרעו — כאילו לא פרע, וחייב לשלם. הוסיף ואמר רב יהודה: \u0003כי אמריתה\u0004 \u0005[כאשר אמרתי אותה]\u0006 את ההלכה הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל, אמר לי, יכול\u0004 הנתבע \u0003לומר לו: פרעתיך בפני\u0004 עדים \u0003פלוני ופלוני, והלכו להם למדינת הים.\u0004 ודי לו בטענה זו. ומביאים ראיה נגד דברי רב אסי.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"מנה לי בידך\", אמר לו: \"הן\", למחר אמר לו: \"תנהו לי\",\u0004 ואמר הנתבע: \"כבר \u0003נתתיו לך\"\u0004 — \u0003פטור. והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003כיון דתבעיה\u0004 \u0005[שתבעו]\u0006 \u0003בעדים\u0004 והודה לו בפניהם — \u0003כמאן דאוזפיה\u0004 \u0005[כמי שהילווהו]\u0006 \u0003בעדים דמי\u0004 \u0005[נחשב],\u0006 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003פטור,\u0004 משמע אם כן שאין צריך לפורעו בעדים."],["הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטתו של \u0003רב אסי!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב אסי: אנא כי אמרי היכא דמעיקרא אוזפיה\u0004 \u0005[אני כאשר אמרתי\u0006 שצריך לפרוע בעדים, הרי זה \u0005היכן שמתחילה הילווהו]\u0006 \u0003בעדים, דלא לדידיה הימניה\u0004 \u0005[שלא לו האמין]\u0006 אלא דאג להסתמך על עדים, \u0003הכא הא הימניה\u0004 \u0005[כאן הרי האמינו]\u0006 כשהילווהו מתחילה בלי עדים, ולכן אינו צריך לפורעו בעדים.","\u0003רב יוסף מתני הכי\u0004 \u0005[\u0006היה \u0005שונה כך]\u0006 מחלוקת זו, בלשון אחרת: \u0003אמר רב יהודה אמר רב אסי: המלוה את חבירו בעדים\u0004 — \u0003אינו צריך לפורעו בעדים, ואם אמר: \"אל תפרעני אלא בעדים\"\u0004 — \u0003צריך לפורעו בעדים,\u0004 ואם לא — חייב לשלם. והוסיף רב יהודה: \u0003כי אמריתה\u0004 \u0005[כאשר אמרתי אותה]\u0006 את ההלכה הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל, אמר לי:\u0004 הרי \u0003יכול לומר לו: \"פרעתיך בפני פלוני ופלוני והלכו להם למדינת הים\".\u0004 ומביאים ראיה לענין זה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"מנה לי בידך\", אמר לו: \"הן\", אמר לו: \"אל תתנהו לי אלא בפני עדים\",\u0004 אם \u0003למחר אמר לו: \"תנהו לי\",\u0004 ואמר הנתבע: \u0003\"נתתיו לך\"\u0004 — \u0003חייב\u0004 לשלם, \u0003מפני שצריך ליתן לו בעדים.\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטתו של \u0003שמואל!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך שמואל: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים\u0006] \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מלוה האומר ללווה: \u0003\"בעדים הלויתיך, בעדים פרע לי\"\u0004 — \u0003או יתן\u0004 הלווה מה שהלווהו \u0003או יביא ראיה שנתן. ר' יהודה בן בתירא אומר, יכול לומר לו: \"פרעתיך בפני פלוני ופלוני והלכו להם למדינת הים\",\u0004 ואני הולך כשיטת ר' יהודה בן בתירא.","\u0003פריך\u0004 \u0005[הקשה]\u0006 \u0003רב אחא\u0004 על ראיה זו: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק ש\u0003בשעת הלואה קאי\u0004 \u0005[עומד,\u0006 מדובר\u0005]\u0006 שאומר לו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בשעת תביעה קאי\u0004 \u0005[עומד,\u0006 מדובר\u0005],\u0006 שהילווהו מתחילה בלא תנאי, וכשתובעו הלווה טוען שפרע. \u0003והכי קאמר ליה\u0004 \u0005[וכך אומר לו]\u0006 המלוה: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003בעדים הלויתיך? בעדים היה לך לפורעני. אבל\u0004 אם התנה עמו \u0003בשעת הלואה\u0004 — \u0003דברי הכל חייב.\u0004 ואין איפוא ראיה מדברי ר' יהודה בן בתירא לשיטת שמואל.","ולסיכומה של ההלכה \u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, הלכתא\u0004 \u0005[הלכה]:\u0006 \u0003המלוה את חבירו בעדים\u0004 — \u0003צריך לפורעו בעדים. ורב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: המלוה את חבירו בעדים\u0004 — \u0003אין צריך לפורעו בעדים, ו\u0004אולם \u0003אם אמר: \"אל תפרעני אלא בעדים\"\u0004 — \u0003צריך לפורעו בעדים, ואם אמר לו: \"פרעתיך בפני פלוני ופלוני והלכו להם למדינת הים\"\u0004 — \u0003נאמן.\u0004","ומביאים מקרים שונים הקשורים בעדי הלוואה. ונתנו למקרים אלו \u0003סימן: ראוב\"ן ושמעו\"ן דתנ\"ו הלכת\"א יזפ\"י ופר\"ע פלוני ופלוני עפצ\"י סטרא\"י בהימנות\"א כבי תרי.\u0004","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד,\u0006 מלוה, \u0005שאמר לו לחבירו,\u0006 הלווה\u0005]:\u0006 \u0003כי פרעתין\u0004 \u0005[כאשר אתה פורעני]\u0006 — \u0003פרעין\u0004 \u0005[פרע]\u0006 \u0003לי באפי\u0004 \u0005[בפני]\u0006 \u0003ראובן ושמעון.\u0004 \u0003אזל ופרעיה באפי תרי מעלמא\u0004 \u0005[הלך ופרעו בפני שניים סתם],\u0006 ולא אלה שהתנה עמו, ובא המעשה בפני חכמים. \u0003אמר אביי: באפי בי תרי\u0004 \u0005[בפני שנים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לפרוע, \u0003באפי בי תרי פרעיה\u0004 \u0005[בפני שנים פרעו],\u0006 ואינו יכול עוד לתובעו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: להכי קאמר ליה\u0004 \u0005[לכך אמר לו]\u0006 במפורש \u0003באפי\u0004 \u0005[בפני]\u0006 \u0003ראובן ושמעון, כי היכי דלא נדחייה\u0004 \u0005[כדי שלא ידחה אותו]\u0006 על ידי עדים אחרים.","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003כי פרעת\u0004 \u0005[כאשר אתה פורע]\u0006 \u0003לי\u0004 — \u0003פרעין\u0004 \u0005[פרע]\u0006 \u0003לי באפי בי תרי דתנו הלכתא\u0004 \u0005[בפני שנים ששונים הלכות],\u0006 \u0003אזל פרעיה בין דיליה לדיליה\u0004 \u0005[הלך ופרעו בינו לבינו],\u0006 ולאחר מכן \u0003איתניסו הנך זוזי\u0004 \u0005[נאנסו\u0006 נלקחו באונס, \u0005אותם זוזים]\u0006 מן המלוה.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב נחמן, אמר ליה\u0004 \u0005[לו]\u0006 התובע: \u0003אין\u0004 \u0005[כן],\u0006 אכן \u0003קבולי קבלתינהו מיניה\u0004 \u0005[קיבלתי ממנו\u0006 את הכסף\u0005],\u0006 אלא שלא קבלתיו כפרעון, שהרי התניתי שלא יפרע לי אלא בפני שוני הלכות, אלא קבלתיו \u0003דרך פקדון,\u0004 כשומר חינם, \u0003ואמינא\u0004 \u0005[ואמרתי]:\u0006 \u0003ליהוי\u0004 \u0003גבאי פקדון, עד דמתרמו בי תרי דתנו הלכתא ומקיים תנאיה\u0004 \u0005[שיהיה אצלי\u0006 כ\u0005פקדון עד שיזדמנו שנים ששונים הלכות ויתקיים תנאו].\u0006 וכיון שהכסף נלקח באונס וכשומר אינני חייב לפצותו — צריך הוא לחזור ולפרוע לי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003כיון דקא מודית דודאי שקלתינהו מיניה\u0004 \u0005[כיון שאתה מודה שוודאי לקחת אותם,\u0006 את המעות \u0005ממנו]\u0006 — \u0003פרעון מעליא הוי\u0004 \u0005[מעולה הוא],\u0006 \u0003אי אמרת לקיומי תנאיה\u0004 \u0005[אם אתה אומר\u0006 שהוא צריך גם \u0005לקיים תנאו]\u0006 שיפרע לו בפני שוני הלכות — \u0003זיל אייתינהו\u0004 \u0005[לך הבא אותם]\u0006 את המעות שנתן לך, \u0003דהא אנא\u0004 \u0005[שהרי אני]\u0006 \u0003ורב ששת, דתנינא הלכתא\u0004 \u0005[ששנינו הלכות]\u0006 \u0003וספרא וספרי ותוספתא וכולא תלמודא\u0004 \u0005[וכל התלמוד],\u0006 ובפנינו יתן לך אותם, ויתקיים תנאו.","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מאה זוזי דאוזיפתך\u0004 \u0005[זוזים,\u0006 דינרים, \u0005שהילויתיך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא היו דברים מעולם. אזל אייתי סהדי דאוזפיה ופרעיה\u0004 \u0005[הלך הביא עדים שהילווהו ופרעו].\u0006 \u0003אמר אביי: מאי ניעבוד\u0004 \u0005[מה נעשה]\u0006 במקרה זו? \u0003אינהו אמרי אוזפיה\u0004 \u0005[הם\u0006 העדים, \u0005שאמרו הילווהו]\u0006 \u0003אינהו אמרי פרעיה\u0004 \u0005[הם אומרים\u0006 ש\u0005פרעו].\u0006 \u0003רבא אמר: כל האומר \"לא לויתי\"\u0004 — \u0003כאומר \"לא פרעתי\" דמי\u0004 \u0005[נחשב],\u0006 וכיון שעדים מעידים שלווה — צריך לפרוע. ומה שמעידים על הפרעון אינו נחשב, שהרי הלווה עצמו אומר שלא פרע.","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מאה זוזי דמסיקנא בך\u0004 \u0005[זוזים,\u0006 דינרים, \u0005שאני נושה בך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא פרעתיך בפני פלוני ופלוני? אתו\u0004 \u0005[באו]\u0006 \u0003פלוני ופלוני\u0004 שהזכיר, \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003לא היו דברים מעולם,\u0004 שלא פרע בפניהם. \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב ששת למימר\u0004 \u0005[לומר]:\u0006 \u0003הוחזק\u0004 הלווה \u0003כפרן\u0004 (שקרן), שהרי העדים מעידים שלא פרעו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כל מילתא דלא רמיא עליה דאינש\u0004 — \u0003לאו אדעתיה\u0004 \u0005[כל דבר שאינו מוטל על אדם\u0006 — \u0005לא בדעתו]\u0006 הוא, שאדם עשוי לשכוח דבר שאינו מוטל עליו לזכור.","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003הב לי שית מאה זוזי דמסיקנא בך\u0004 \u0005[תן לי שש מאות זוזים,\u0006 דינרים, \u0005שאני נושה בך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ו\u0004כי \u0003לא פרעתיך מאה קבי\u0004 \u0005[קבים]\u0006"],["\u0003עפצי דקיימי בשיתא שיתא\u0004 \u0005[עפצים ש\u0006היו \u0005עומדים,\u0006 נמכרים, \u0005בששה ששה]\u0006 דינרים לקב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו בארבעה ארבעה הוו קיימי\u0004 \u0005[האם לא בארבעה ארבעה\u0006 דינרים לקב \u0005היו עומדים]?\u0006 \u0003אתו תרי סהדי\u0004 \u0005[באו שני עדים]\u0006 \u0003ואמרו: אין\u0004 \u0005[כן],\u0006 \u0003בארבעה ארבעה הוו קיימי\u0004 \u0005[היו עומדים].\u0006 \u0003אמר רבא: הוחזק\u0004 הלווה \u0003כפרן\u0004 (שקרן) שהרי הכחישוהו העדים. \u0003אמר רמי בר חמא, הא\u0004 \u0005[הרי]\u0006 \u0003אמרת: כל מילתא דלא רמיא עליה דאיניש\u0004 — \u0003לאו אדעתיה\u0004 \u0005[כל דבר שאינו מוטל על אדם\u0006 לזוכרו — \u0005אינו בדעתו],\u0006 ושמא שכח את מחיר העפצים באותה שעה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: קצותא דתרעא מידכר דכירי אינשי\u0004 \u0005[קציצת,\u0006 קביעת, \u0005שערים זוכרים אנשים].\u0006","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003הב לי מאה זוזי דמסיקנא בך, והא שטרא\u0004 \u0005[תן לי מאה זוזים\u0006 שאני \u0005נושה בך, והרי השטר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003פרעתיך. אמר ליה\u0004 \u0005[לו]\u0006 התובע \u0005:\u0006 \u0003הנהו סיטראי נינהו\u0004 \u0005[אותם\u0006 מאה שפרעת \u0005מן הצד הם]\u0006 כלומר, הם היו לפרעון חוב אחר שאתה חייב לי, אבל החוב שבשטר זה לא פרעת. \u0003אמר רב נחמן: איתרע שטרא\u0004 \u0005[הורע השטר],\u0006 שהרי התובע מודה שקיבל ממנו כספים באותו סכום, אלא שהוא טוען עכשיו טענה חדשה. \u0003רב פפא אמר: לא איתרע שטרא\u0004 \u0005[הורע השטר].\u0006","ושואלים: \u0003ולרב פפא, מאי שנא\u0004 \u0005[מה שונה]\u0006 מקרה זה \u0003מההוא דאמר ליה לחבריה\u0004 \u0005[שאמר לו לחבירו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מאה זוזי דמסיקנא בך, והא שטרא\u0004 \u0005[מאה זוזים שאני נושה בך, והרי השטר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אתורי יהבת לי, ואתית ואיתיבת אמסחתא וקבילת\u0004 \u0003זוזך\u0004 \u0005[האם לא\u0006 עבור קנית \u0005שוורים נתת לי\u0006 כסף זה, \u0005ובאת וישבת בבית המטבחיים וקיבלת כספך]\u0006 מדמי השוורים השחוטים? \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנהו סיטראי נינהו\u0004 \u0005[אלה\u0006 הכספים שקיבלתי \u0005מן הצד היו],\u0006 \u0003ואמר רב פפא\u0004 כשבא אותו מעשה לפניו: \u0003איתרע שטרא\u0004 \u0005[הורע השטר]!\u0006","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דקאמר: אתורי יהבת לי ומתורי שקלת\u0004 — \u0003איתרע שטרא\u0004 \u0005[כיון שאומר: עבור השוורים נתת לי ומן השוורים נטלת\u0006 — \u0005הורע השטר],\u0006 שהרי אף התובע מודה שכך היה מעשה. \u0003הכא אימור סיטראי נינהו\u0004 \u0005[כאן\u0006 במקרה הקודם \u0005אמור\u0006 שהמעות עבור חוב \u0005מן הצד הם].\u0006","ושואלים: ולמעשה \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הבעיה? כיצד נפסוק? \u0003רב פפי אמר: לא איתרע שטרא\u0004 \u0005[הורע השטר],\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: איתרע שטרא\u0004 \u0005[הורע השטר].\u0006 \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא: \u0003איתרע שטרא\u0004 \u0005[הורע השטר].\u0006","\u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים \u0003דפרעיה באפי סהדי ולא אידכר ליה שטרא\u0004 \u0005[\u0006במקרה \u0005שפרעו בפני עדים ולא הזכיר לו\u0006 את \u0005השטר],\u0006 \u0003אבל פרעיה בין דידיה לדידיה\u0004 \u0005[\u0006במקרה \u0005שפרעו בינו לבינו]\u0006 בלא עדים, \u0003מיגו\u0004 \u0005[מתוך]\u0006 ש\u0003יכול למימר\u0004 \u0005[לומר]:\u0006 \u0003לא היו דברים מעולם\u0004 ולא קיבלתי כסף זה כלל — \u0003יכול נמי למימר: סיטראי נינהו\u0004 \u0005[יכול גם כן לומר: מן הצד הם]\u0006 על חוב אחר, \u0003וכ\u0004מקרה של \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו\u0004 שאירע בו מעשה כזה, ששילם כסף ולא בפני עדים, ואחר כך טענו המלווים שהיה זה עבור חוב אחר.","\u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]\u0006 שהילוה לו: \u0003מהימנת לי כל אימת דאמרת לי \"לא פרענא\"\u0004 \u0005[נאמן אתה עלי כל זמן שתאמר לי \"לא פרעתי\"].\u0006 \u0003אזל פרעיה באפי סהדי\u0004 \u0005[הלך פרע לו בפני עדים],\u0006 והמלוה טוען שלא פרע. \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הא הימניה\u0004 \u0005[הרי האמינו],\u0006 קיבל על עצמו מראש דבריו של התובע, ולכן התובע יכול לחזור ולתבוע. ואין לסמוך על העדים, שהרי הלווה סמך את אמונתו דווקא בו. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: נהי דהימניה טפי מנפשיה\u0004 \u0005[אם אמנם האמינו יותר מעצמו],\u0006 שהתנה שדברי המלוה יהיו נאמנים יותר מדבריו שלו, שלא יוכל לכפור בו, אבל \u0003טפי מסהדי מי הימניה\u0004 \u0005[יותר מעדים האם האמינו]?\u0006 ואם כן, כיון שהיו עדים — הרי זה פרעון גמור!","ועוד בענין זה, מסופר, \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003מהימנת לי כבי תרי כל אימת דאמרת \"לא פרענא\"\u0004 \u0005[נאמן אתה עלי כשני\u0006 עדים \u0005כל זמן שתאמר \"לא פרעתי\"].\u0006 \u0003אזל פרעיה באפי תלתא\u0004 \u0005[הלך\u0006 ו\u0005פרע לו\u0006 את החוב \u0005בפני שלושה].\u0006 \u0003אמר רב פפא: כבי תרי הימניה, כבי תלתא לא הימניה\u0004 \u0005[כשנים האמין אותו, כשלושה לא האמין אותו],\u0006 וכיון שהיו שלושה — יפה כוחם להעיד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אימור דאמרי רבנן דאזלינן בתר\u0004 \u0005[אמור שאמרו חכמים שהולכים אחר]\u0006 \u0003רוב דעות\u0004 כלומר, שכמות האנשים מכריעה — הרי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003לענין אומדנא\u0004 \u0005[אומד]\u0006 שצריך להעיד על ערכם של דברים, \u0003דכמה דנפישי בקיאי טפי\u0004 \u0005[שכמה שהם מרובים בקיאים יותר]\u0006 ולכן הולכים אחר ריבוי האנשים, שסביר שהם יודעים יותר, \u0003אבל לענין עדות\u0004 — הלוא \u0003מאה כתרי\u0004 \u0005[כשנים]\u0006 \u0003ותרי\u0004 \u0005[ושנים]\u0006 \u0003כמאה,\u0004 ולכן אין לחלק בין שניים ושלושה.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 של אותו מעשה כך הוא: \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[\u0006אדם \u0005אחד שאמר לו לחבירו]:\u0006 \u0003מהימנת לי כבי תרי כל אימת דאמרת \"לא פרענא\"\u0004 \u0005[נאמן אתה לי כשנים כל זמן שתאמר \"לא פרעתי\"],\u0006 \u0003אזל ופרעיה באפי תלתא\u0004 \u0005[הלך\u0006 ו\u0005פרע לו בפני שלושה],\u0006 \u0003אמר רב פפא: כבי תרי הימניה, כבי תלתא לא הימניה\u0004 \u0005[כמו שנים האמין אותו, כמו שלושה לא האמין אותו],\u0006 ולכן יש לסמוך על השלושה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 הלוא \u0003תרי\u0004 \u0005[שנים]\u0006 \u0003כמאה ומאה כתרי\u0004 \u0005[כשנים],\u0006 ואין הבדל לענין עדות במספר העדים! ואם כן, בכל מקרה נאמן. \u0003ו\u0004מכל מקום \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מתחילה: נאמן אתה לי \u0003כבי תלתא\u0004 \u0005[כשלושה],\u0006 \u0003ואזל פרעיה באפי בי\u0004 \u0005[והלך ופרע לו לפני]\u0006 \u0003ארבעה,\u0004 במקרה זה, \u0003כיון דנחית\u0004 \u0005[שירד]\u0006 \u0003לדעות\u0004 שהוסיף מספר יתר על צורך העדות — הרי זה \u0003נחית\u0004 \u0005[ירד]\u0006 \u0003לדעות,\u0004 ובענין זה יהא כוחם של ארבעה יפה משלושה, ולא יהא נאמן כנגדם.","שנינו במשנה: \u0003אין נשבעין על טענת חרש שוטה וקטן, ואין משביעין את הקטן.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת מודה במקצת: \u0003\"כי יתן איש אל רעהו כסף או כלים לשמר\"\u0004 (שמות כב, ו), וההדגשה היא: נתינה של איש, שמשמעו דווקא גדול, \u0003ואין נתינת קטן כלום,\u0004 שאין בו דעת.","ועוד שנינו במשנה: \u0003אבל נשבעין לקטן ולהקדש.\u0004 ומקשים: \u0003והא אמרת רישא\u0004 \u0005[והרי אמרת מתחילה]:\u0006 \u0003אין נשבעין על טענת שוטה וקטן,\u0004 וכאן נאמר שנשבעים לקטן!","\u0003אמר רב:\u0004 מדובר פה \u0003ב\u0004קטן ש\u0003בא בטענת\u0004 חוב שחייבים ל\u0003אביו, ו\u0004שיטת \u0003ר' אליעזר בן יעקב היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: פעמים שאדם נשבע על טענת עצמו,\u0004 כלומר, שהוא עצמו גורם שיצטרך להישבע, \u0003כיצד? אמר לו\u0004 לחבירו: \u0003\"מנה לאביך בידי,\u0004 שהייתי חייב לאביך, \u0003והאכלתיו פרס\u0004 כלומר, נתתי לו מזה חצי\" — \u0003הרי זה נשבע\u0004 כמודה במקצת, \u0003וזהו שנשבע על טענת עצמו. וחכמים אומרים:\u0004 כיון שאינו נתבע כלל על הסכום הזה, אלא אומר כן מדעתו, \u0003אינו אלא כמשיב אבידה, ו\u0004משיב אבידה \u0003פטור\u0004 מלהישבע שלא עיכב לעצמו כלום מן האבידה שהחזיר.","ושאלו על כך: \u0003ור' אליעזר בן יעקב לית ליה\u0004 \u0005[אין לו]\u0006 הלכה זו ש\u0003משיב אבידה פטור? אמר רב:\u0004 מדובר פה \u0003בשטענו קטן\u0004 שלא הודה האיש לגמרי מרצונו, אלא הבן הקטן תבע אותו, והודה לו במקצת.","ותוהים: \u0003קטן? והאמרת\u0004 \u0005[והרי אמרת]\u0006 במשנתנו: \u0003אין נשבעין על טענת חרש שוטה וקטן!\u0004 ומשיבים: \u0003לעולם\u0004 מדובר שהטוען היה \u0003גדול, ואמאי קרו ליה\u0004 \u0005[ומדוע קוראים לו]\u0006 \u0003קטן?\u0004 משום שמדובר פה ביורש, \u0003דלגבי מילי דאבוה\u0004 \u0005[שאצל עניינים של אביו]\u0006 \u0003קטן הוא,\u0004 שהרי אינו יודע בדיוק מה היו עסקי אביו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר את דברי ר' אליעזר בן יעקב, יש להקשות על ניסוח הדברים: וכי \u0003טענת עצמו\u0004 היא שהוא נשבע עליה? הלוא \u0003טענת אחרים היא!\u0004 ומשיבים: אמנם \u0003טענת אחרים\u0004 היא, ואולם \u0003הודאת עצמו.\u0004"],["ותהו: הלוא כל הטענות \u0003כולהו נמי\u0004 \u0005[כולן גם כן]\u0006 \u0003טענת אחרים והודאת עצמו נינהו\u0004 \u0005[הן]!\u0006 ומה ההבדל בין טענה זו ואחרת?","\u0003אלא ב\u0004עקרון שאמר \u0003רבה\u0004 לגבי שבועת מודה במקצת \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 ש\u0003אמר רבה: מפני מה אמרה תורה מודה מקצת הטענה ישבע? חזקה אין אדם מעיז פניו בפני בעל חובו,\u0004 שאין בו חוצפה לכפור הכל לאדם שהילוה לו ויודע שהוא משקר, \u0003והאי בכוליה בעי דליכפריה\u0004 \u0005[וזה\u0006 הלווה \u0005בכל\u0006 הסכום \u0005רצה לכפור לו],\u0006 \u0003והאי דלא כפריה\u0004 \u0005[וזה שלא כפר\u0006 בכל\u0005]\u0006 \u0003משום\u0004 ש\u0003אינו מעיז פניו בפני בעל חובו, ו\u0004בעצם","\u0003בכוליה בעי דלודי ליה\u0004 \u0005[בכל רצה להודות לו],\u0006 \u0003והאי דלא אודי ליה\u0004 \u0005[וזה שלא הודה לו\u0006 בכל\u0005]\u0006 — \u0003אישתמוטי הוא דקא משתמיט מיניה\u0004 \u0005[להשתמט הוא שמשתמט ממנו],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 אמתין \u0003עד דהוי\u0004 \u0005[שיהיו]\u0006 \u0003לי זוזי ופרענא ליה\u0004 \u0005[מעות ואפרע לו],\u0006 \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 משום כך: \u0003רמי\u0004 \u0005[הטל]\u0006 \u0003שבועה עילויה כי היכי דלודי ליה בכוליה\u0004 \u0005[עליו כדי שיודה לו בכולו].\u0006","ובענין זה נחלקו, \u0003ר' אליעזר בן יעקב סבר\u0004 \u0005[סבור]\u0006 כי הלווה מאדם \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בו\u0004 במלוה עצמו, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 לגבי \u0003בנו\u0004 של אותו אדם \u0003אינו מעיז\u0004 פניו, \u0003והלכך\u0004 \u0005[ומשום כך]\u0006 המודה במקצת לבן \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משיב אבידה הוא,\u0004 אלא אדם שלא מעיז פניו לכפור הכל, ויש מקום לחייבו שבועה. והוא שיטת משנתנו שנשבעים לקטן. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בפניו\u0004 של בעל חובו \u0003הוא\u0004 ש\u0003אינו מעיז, אבל בפני בנו מעיז, ומ\u0004כיון שכעת הוא \u0003לא מעיז\u0004 ולא אומר שאינו חייב כלום — \u0003משיב אבידה הוא.\u0004","ומקשים: \u0003מי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003כר' אליעזר בן יעקב? הא קתני רישא\u0004 \u0005[הרי שנה בראשה]:\u0006 \u0003\"מנה לאבא בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא חמשים דינר\"\u0004 — \u0003פטור, מפני שמשיב אבידה הוא!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ש\u0003לא אמר \"ברי\u0004 \u0005[ברור\u0006 ודאי\u0005]\u0006 \u0003לי\u0004 שאתה חייב לאבי\", אלא בדרך ספק טען, ולכן הריהו כמשיב אבידה, \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ש\u0003אמר \"ברי לי\u0004 שכך היה הדבר\".","\u0003שמואל אמר\u0004 פירוש אחר למשנתנו: \"נשבעים \u0003לקטן\"\u0004 משמעו — \u0003ליפרע מנכסי קטן,\u0004 שאם הוצרכו לפרוע חוב מנכסי הקטן — יש לתובע להישבע שלא נפרע החוב. וכן מה ששנינו \"נשבעים \u0003להקדש\"\u0004 — \u0003ליפרע מנכסי הקדש,\u0004 כאשר הלווה הקדיש את נכסיו שכבר היו משועבדים לבעל חובו.","ושואלים: מה שפירש שמואל \u0003לקטן\u0004 כוונתו \u0003ליפרע מנכסי קטן,\u0004 הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה להלן: \u0003מנכסי יתומים לא יפרע אלא בשבועה,\u0004 ואם כן, \u0003תרתי\u0004 \u0005[שתי\u0006 הלכות\u0005]\u0006 באותו ענין \u0003למה לי?\u0004","ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[זה משמיע לנו]\u0006 \u0003כ\u0004דברי \u0003אביי קשישא\u0004 \u0005[הזקן],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אביי קשישא\u0004 \u0005[הזקן]:\u0006 \u0003יתומין שאמרו\u0004 בכל מקום — הרי הם יתומים \u0003גדולים\u0004 שירשו, \u0003ואין צריך לומר קטנים,\u0004 ודין זה שווה בהם, \u0003בין לשבועה\u0004 שצריך להישבע כשבאים להיפרע מהם, \u0003בין לזיבורית\u0004 שאין גובים מקרקעות היתומים אלא מן הקרקע הגרועה יותר.","ועוד שואלים: מה שפירש שמואל שנשבעים \u0003להקדש\u0004 כוונתו שנשבעים כשבאים \u0003ליפרע מנכסי הקדש,\u0004 הלוא גם זה \u0003תנינא\u0004 \u0005[שנינו\u0006 אותו\u0005]\u0006 להלן: הבאים להיפרע \u0003מנכסים משועבדים לא יפרעו אלא בשבועה; ומה לי משועבדים\u0004 שנמכרו \u0003להדיוט\u0004 (לכל אדם) \u0003ומה לי משועבדים\u0004 שהוקדשו \u0003לגבוה\u0004 (להקדש)!","ומשיבים: כאן \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 במקרה של \u0003הדיוט\u0004 הטעם שנשבעים \u0003הוא\u0004 משום החשש ש\u0003אדם עושה קנוניא\u0004 אם הלווה \u0003על הדיוט\u0004 לרמות אותו, שבא עם שטר פרוע לגבות מנכסי הלקוחות, ולכן משביעים אותו, שלא יקבל אלא לאחר שנשבע, \u0003אבל הקדש\u0004 היינו אומרים ש\u0003אין אדם עושה קנוניא על הקדש\u0004 לקחת מן ההקדש במרמה, ואינו צריך שבועה. \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת חוששים ואינו נוטל מן ההקדש אלא בשבועה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: שכיב מרע שהקדיש כל נכסיו, ואמר: \"מנה לפלוני בידי\u0004 שאני חייב לו\" — \u0003נאמן\u0004 באמירה זו, כי \u0003חזקה אין אדם עושה קנוניא על הקדש! אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003שכיב מרע,\u0004 באדם שהולך למות, שאין לחשוש שהוא מרמה את ההקדש בשביל אחרים (יורשיו), ש\u0003אין אדם חוטא ולא לו,\u0004 \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003בריא ודאי חיישינן\u0004 \u0005[חוששים אנו]\u0006 אפילו לגבי הקדש, שמא עושה קנוניא.","\u0003ואלו דברים שאין נשבעין עליהן\u0004 שבועה מן התורה: \u0003העבדים, והשטרות, והקרקעות, וההקדשות,\u0004 ו\u0003אין בהן תשלומי כפל\u0004 אם גנב מהם, \u0003ולא תשלומי ארבעה\u0004 (על שה) \u0003וחמשה\u0004 (על שור) אם גנב בהמה וטבח ומכר את מה שגנב, ו\u0003שומר חנם\u0004 שאיבד אחד מאלה \u0003אינו נשבע\u0004 שלא התרשל בשמירה, ו\u0003נושא שכר\u0004 (שומר בשכר) \u0003אינו משלם\u0004 על גניבה ואבידה.","\u0003ר' שמעון אומר:\u0004 בענין הקדשות יש לחלק, \u0003קדשים שחייב באחריותן\u0004 שהמקדיש חייב לשלם להקדש גם אם מתו — \u0003נשבעין עליהן,\u0004 שהרי הם כנכסיו, אבל קדשים \u0003שאינו חייב באחריותן\u0004 — \u0003אין נשבעין עליהן,\u0004 שאין נשבעים על ההקדשות.","\u0003ר' מאיר אומר: יש דברים שהן בקרקע\u0004 ומחוברים לה, \u0003ו\u0004בכל זאת \u0003אינן כקרקע\u0004 לענין הלכה, \u0003ואין חכמים מודים לו. כיצד?\u0004 טענו: \u0003\"עשר גפנים טעונות\u0004 פרי \u0003מסרתי לך\", והלה\u0004 (הנתבע) \u0003אומר: \"אינן אלא חמש\u0004 גפנים\" — \u0003ר' מאיר מחייב שבועה\u0004 כמודה במקצת, \u0003וחכמים אומרים: כל המחובר לקרקע הרי הוא כקרקע.\u0004","ועוד, \u0003אין נשבעין\u0004 שבועה שמן התורה \u0003אלא על דבר שבמדה, ושבמשקל, ושבמנין.\u0004 שצריכה התביעה (וההודאה) להיות בדברים מדוייקים. \u0003כיצד?\u0004 אם אומר לחבירו: \u0003\"בית מלא מסרתי לך\",\u0004 או \u0003\"כיס מלא מסרתי לך\", והלה אומר: \"איני יודע\u0004 מה שהיה בבית או בכיס, \u0003אלא מה שהנחת אתה נוטל\",\u0004 והוא פחות ממה שהמפקיד טוען — הרי זה \u0003פטור,\u0004 משום שאיננו טוען אותו בדבר מסויים. אבל \u0003זה אומר\u0004 שהיה הבית מלא \u0003\"עד הזיז\" וזה אומר:\u0004 \"לא עד הזיז, אלא \u0003עד החלון\"\u0004 — הרי הוא \u0003חייב,\u0004 משום שיש פה דבר שבמידה.","ומבררים: \u0003תשלומי כפל מנלן\u0004 \u0005[מנין לנו]\u0006 שאין משלמים בכל המקרים שמנינו? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הפסוק \"על כל דבר פשע על שור על חמור על שה על שלמה על כל אבידה... אשר ירשיעון אלהים ישלם שנים לרעהו\" (שמות כב, ו): \u0003\"על כל דבר פשע\"\u0004 — הרי זה \u0003כלל, \"על שור ועל חמור ועל שה ועל שלמה\"\u0004 (שמות כב,ח) — הרי זה \u0003פרט, \"על כל אבדה\"\u0004 (שמות כב,ח) — \u0003חזר וכלל,\u0004 נמצא שיש לנו","\u0003כלל ופרט וכלל,\u0004 במקרה כזה \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו ממון\u0004 כלומר, שהוא עצמו שווה כסף, \u0003אף כל דבר המטלטל וגופו ממון\u0004 משלמים עליו תשלומי כפל,","\u0003יצאו קרקעות\u0004 — \u0003שאין מטלטלין, יצאו עבדים\u0004 — \u0003שהוקשו\u0004 (הושוו בכתוב) \u0003לקרקעות, יצאו שטרות\u0004 — \u0003שאף על פי שהן מטלטלין אין גופן ממון,\u0004 שאין הם משמשים אלא לראיה או כאמצעי קנין. ולגבי \u0003הקדש\u0004 שאין משלמים לו כפל, הרי זה משום ש\u0003\"רעהו\" כתיב\u0004 \u0005[נאמר]\u0006 בפסוק זה, והקדש אינו רעהו.","ועוד שנינו במשנה שאינו משלם על אלה \u0003ולא תשלומי כפל ולא ארבעה וחמשה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאינו משלם תשלומי ארבעה וחמישה? שכן \u0003תשלומי ארבעה וחמשה אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא תשלומי שלשה וארבעה,\u0004 והואיל ותשלומי ארבעה וחמישה כוללים תשלומי כפל, נמצא שאם אינו משלם תשלומי כפל אינו משלם גם תשלומים אלו.","שנינו במשנה: \u0003שומר חנם אינו נשבע\u0004 על עבדים ושטרות וקרקעות. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלה]\u0006 שאינו נשבע על אלה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006"],["נאמר בדין שומר חינם: \"כי יתן איש אל רעהו כסף או כלים לשמור\" (שמות כב, ו), \u0003\"כי יתן איש אל רעהו\"\u0004 — הרי זה \u0003כלל, \"כסף או כלים\"\u0004 — הרי זה \u0003פרט, \"לשמר\"\u0004 — \u0003חזר וכלל,\u0004 ואם כן, יש כאן \u0003כלל ופרט וכלל,\u0004 ובענין זה \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש\u0004 — \u0003דבר המטלטל וגופו ממון, אף כל דבר המטלטל וגופו ממון,\u0004","\u0003יצאו קרקעות\u0004 — \u0003שאין מטלטלין, יצאו עבדים\u0004 — \u0003שהוקשו\u0004 (הושוו) \u0003לקרקעות, יצאו שטרות\u0004 — \u0003שאף על פי שמטלטלין אין גופן ממון\u0004 אלא רק ראיה לממון. ולענין \u0003הקדש\u0004 הרי \u0003\"רעהו\" כתיב\u0004 \u0005[נאמר]\u0006 ואין ההקדש נקרא \"רעהו\".","ועוד שנינו כי \u0003נושא שכר אינו משלם.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר על שומר שכר: \"כי יתן איש אל רעהו חמור או שור או שה וכל בהמה לשמור\" (שמות כב, ט), \u0003\"כי יתן איש אל רעהו\"\u0004 — הרי זה \u0003כלל, \"חמור או שור או שה\"\u0004 — הרי זה \u0003פרט, \"וכל בהמה לשמר\"\u0004 — \u0003חזר וכלל, כלל ופרט וכלל כו',\u0004 ולכן יצאו מכאן כל הדברים שאינם דומים לפרט. וכאמור לעיל בענין שומר חינם \u0003עד: הקדש\u0004 הרי \u0003\"רעהו\" כתיב\u0004 \u0005[נאמר]\u0006 ואין הקדש בכלל זה.","שנינו במשנה: \u0003ר' מאיר אומר: יש דברים שהן כקרקע ואינן כקרקע\u0004 ואין חכמים מודים לו. כיצד? \"עשר גפנים טעונות מסרתי לך\" והלה אומר \"אינן אלא חמש\", ר' מאיר מחייב שבועה, וחכמים אומרים: כל המחובר לקרקע הריהו כקרקע. ושואלים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003כל המחובר לקרקע אינו כקרקע?\u0004 אם כן, \u0003אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005חלוקים]\u0006 \u0003ב\u0004גפנים \u0003טעונות,\u0004 מדוע להוסיף פרט זה? \u0003ליפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003בסרוקות\u0004 בגפנים ריקות שאין בהן ענבים כלל, ועדיין מחוברות לקרקע, שר' מאיר סבור שאינן כקרקע!","\u0003(אלא) אמר ר' יוסי בר' חנינא:\u0004 לדעת כולם המחובר לקרקע הריהו כקרקע, אלא \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בענבים\u0004 שכבר בשלו ו\u0003עומדות להבצר\u0004 \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש\u0003ר' מאיר סבר: כבצורות דמיין\u0004 \u0005[נחשבות\u0006 הן\u0005],\u0006 שכיון שעומדות כבר להיבצר הרי זה כאילו נעשה הדבר, ואין דינן כקרקע, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא כבצורות דמיין\u0004 \u0005[נחשבות\u0006 הן\u0005].\u0006","שנינו במשנה ש\u0003אין נשבעין אלא על דבר שבמדה ושבמשקל.\u0004 כיצד? \"בית מלא מסרתי לך...\", והלה אומר: \"איני יודע, אלא מה שהנחת אתה נוטל\" — פטור. \u0003אמר אביי: לא שנו אלא\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"בית\u0004 מלא\" \u0003סתם,\u0004 ועל דבר כזה שאינו מסויים אין נשבעים, \u0003אבל\u0004 אם \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"בית זה מלא\"\u0004 — \u0003ידיעא טענתיה\u0004 \u0005[ידועה טענתו]\u0006 שברור מה הוא תובע, ולכן זו טענה מסויימת, ונשבע עליה הנתבע כשמודה בחלקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה בסוף\u0006 המשנה\u0005]\u0006 ומחלק: \u0003זה אומר \"עד הזיז\" וזה אומר \"עד החלון\"\u0004 — \u0003חייב, ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה ב\u0006תוך הלכה \u0005זו עצמה]:\u0006 \u0003במה דברים אמורים\u0004 — שטוענו \u0003ב\"בית מלא\", אבל \"בית זה מלא\"\u0004 — \u0003חייב!\u0004","\u0003אלא אמר רבא: לעולם אינו חייב עד שיטעננו בדבר שבמדה שבמשקל ושבמנין,\u0004 שיש לו מידה מסויימת, \u0003ויודה לו\u0004 הנתבע גם כן במקצת \u0003בדבר שבמדה ושבמשקל ושבמנין.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא:\u0004 הטוען לחבירו \u0003\"כור תבואה לי בידך\", והלה אומר: \"אין לך בידי\u0004 כלום\" — \u0003פטור\u0004 משבועה, שהרי כפר בכל. טען לו: \u0003\"מנורה גדולה יש לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא מנורה קטנה\"\u0004 — \u0003פטור,\u0004 משום שלא הודה לו במקצת הטענה אלא בדבר אחר. וכן אם טען: \u0003\"אזורה\u0004 (חגורה) \u0003גדולה יש לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא אזורה קטנה\"\u0004 — \u0003פטור,\u0004 שהודה לו בדבר אחר.","\u0003אבל\u0004 אם \u0003אמר לו: \"כור תבואה יש לי בידך\", והלה אומר: \"אין לך בידי אלא לתך\u0004 (חצי כור)\"— \u0003חייב.\u0004 וכן טען כנגדו: \u0003\"מנורה בת\u0004 משקל \u0003עשר ליטרין יש לי בידך\",\u0004 ואמר לו: \u0003\"אין לך בידי אלא\u0004 מנורה \u0003בת חמש ליטרין\"\u0004 — \u0003חייב.\u0004","\u0003כללו של דבר: לעולם אינו חייב עד שיטעננו בדבר שבמדה ושבמשקל ושבמנין, ויודה לו בדבר שבמדה ושבמשקל ושבמנין.\u0004","ויש לשאול: \u0003\"כללו של דבר\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 שלא אמרנו במפורש? \u0003לאו לאתויי\u0004 \u0005[\u0006האם \u0005לא להביא]\u0006 את המקרה של \u0003\"בית זה מלא\"?\u0004 שכיון שאיננו דבר שבמידה — איננו נחשב לטענה של ממש, וכדברי רבא.","ולגופן של ההלכות שבברייתא שואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 שטוען לו ב\u0003מנורה גדולה\u0004 והוא מודה ב\u0003מנורה קטנה\u0004 שפטור, משום ש\u0003מה שטענו לא הודה לו ומה שהודה לו לא טענו? אי הכי\u0004 \u0005[אם כך],\u0006 אם המנורה היא \u0003בת\u0004 משקל \u0003עשר\u0004 ליטרין או \u0003בת חמש, נמי\u0004 \u0005[גם כן]\u0006 \u0003מה שטענו לא הודה לו ומה שהודה לו לא טענו,\u0004 שהרי מודה לו במנורה קטנה!","\u0003אמר ר' שמואל בר רב יצחק: הכא\u0004 \u0005[כאן]\u0006 \u0003במנורה של חליות\u0004 \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 מנורה מתפרקת שעשויה מחוליות חוליות, שניתן להגדילה ולהקטינה, \u0003דקא מודה ליה מינה\u0004 \u0005[שהוא מודה לו ממנה\u0006 עצמה\u0005],\u0006 שהוא מודה בחלק מן החוליות שהלה תובעו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אזורה נמי ניתני\u0004 \u0005[גם כן ישנה]\u0006 מקרה שחייב, \u0003ולוקמי בדלייפי\u0004 \u0005[ושיעמיד אותה במחוברות],\u0006 שהוא תובע אותו בגדולה שמחוברת מכמה חתיכות, והנתבע מודה לו בקטנה שיש בה מספר חתיכות קטן יותר! \u0003אלא\u0004 בהכרח \u0003דלייפי\u0004 \u0005[\u0006אזורה \u0005שמחוברת]\u0006 \u0003לא קתני\u0004 \u0005[שנה\u0006 במשנה\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין מנורה \u0003בשל חליות לא קתני\u0004 \u0005[שנה]!\u0006","\u0003אלא\u0004 יש לדחות פירוש זה ולומר כמו ש\u0003אמר ר' אבא בר ממל: שאני\u0004 \u0005[שונה]\u0006 \u0003מנורה\u0004 שהודאה במנורה הקלה יותר, הודאה מקצת הטענה היא, \u0003הואיל ויכול לגוררה\u0004 (לגרד אותה) את המנורה בת עשר הליטרין \u0003ולהעמידה על חמש ליטרין,\u0004 ואם כן נמצא שיכול להיות שהוא מודה לו על אותה מנורה עצמה, מה שאין כן באזורה.","\u0003המלוה את חבירו על המשכון ואבד המשכון, אמר לו\u0004 המלוה: \u0003\"סלע\u0004 (ארבעה דינרים) \u0003הלויתיך עליו\u0004 על משכון זה, \u0003ושקל\u0004 (שני דינרים) \u0003היה\u0004 המשכון \u0003שוה\",\u0004 ואתה חייב לי עדיין שקל, \u0003והלה\u0004 בעל המשכון \u0003אומר: \"לא כי, אלא סלע הלויתני עליו, וסלע היה\u0004 המשכון \u0003שוה\"\u0004 ושוב איני חייב לך דבר — במקרה זה \u0003פטור\u0004 משבועה, שכפר בכל הטענה.","אבל אם אמר לו: \u0003\"סלע הלויתיך עליו, ושקל היה שוה\"\u0004 ואתה חייב לי שני דינרים, \u0003והלה אומר: \"לא כי, אלא סלע הלויתני עליו, ושלשה דינרים היה שוה\"\u0004 ואיני חייב לך אלא דינר — הרי זה \u0003חייב,\u0004 משום שהוא מודה במקצת.","טען הלווה: \u0003\"סלע הלויתני עליו\u0004 על המשכון, \u0003ושתים\u0004 שני סלעים \u0003היה שוה\"\u0004 ואתה חייב לי מחצית משוויו, \u0003והלה\u0004 (המלוה) \u0003אומר: \"לא כי, אלא סלע הלויתיך עליו, וסלע היה שוה\"\u0004 ואיני חייב לך כלום — הרי זה \u0003פטור,\u0004 שכפר בכל. אבל אם טען לו: \u0003\"סלע הלויתני עליו, ושתים היה שוה\", והלה אומר: \"לא כי, אלא סלע הלויתיך עליו, וחמשה דינרים היה שוה\",\u0004 ואיני חייב לך אלא דינר — \u0003חייב,\u0004 שהרי הודה במקצת.","\u0003ומי נשבע? מי שהפקדון אצלו,\u0004 המלוה, שהוא נשבע מה היה ערכו, \u0003שמא ישבע זה\u0004 הלווה על ערכו של הפקדון, \u0003ויוציא הלה\u0004 המלוה \u0003את הפקדון\u0004 שהיה שמור בידו, ויתברר שהאחר שיקר בשבועתו."],["על הקטע האחרון במשנה זו, שיישבע המלוה, המחזיק בפקדון, שואלים: \u0003אהייא\u0004 \u0005[על איזו\u0006 הלכה במשנה מדובר\u0005]?\u0006 \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על\u0006 המקרה שמדובר בו \u0005בסוף],\u0006 שהלווה טוען שהמשכון עולה בערכו על ההלוואה, יש להקשות: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו מטעם אחר, שה\u0003שבועה\u0004 ממילא \u0003גבי\u0004 \u0005[אצל]\u0006 ה\u0003מלוה,\u0004 שהרי הוא הנתבע לשלם במקרה זה!","\u0003אמר שמואל:\u0004 הלכה זו נאמרה \u0003ארישא\u0004 \u0005[על תחילת\u0006 המשנה\u0005],\u0006 שהלווה הוא הנתבע. \u0003וכן אמר ר' חייא בר רב: ארישא\u0004 \u0005[על תחילת\u0006 המשנה\u0005].\u0006 \u0003וכן אמר ר' יוחנן: ארישא\u0004 \u0005[על תחילת\u0006 המשנה\u0005].\u0006","ומבררים: \u0003מאי רישא\u0004 \u0005[מהו תחילתה]?\u0006 לא ההלכה הראשונה ממש, אלא \u0003סיפא דרישא\u0004 \u0005[\u0006הקטע \u0005האחרון שבתחילתה],\u0006 שהוא: \u0003\"סלע הלויתיך עליו ושקל היה שוה\", והלה אומר: \"לא כי, אלא סלע הלויתני עליו ושלשה דינרין היה שוה\"\u0004 — הרי זה \u0003חייב,\u0004 שה\u0003שבועה גבי\u0004 \u0005[אצל]\u0006 \u0003לוה היא,\u0004 שהוא היה צריך להישבע משום שהוא מודה במקצת, \u0003ושקלוה רבנן\u0004 \u0005[ונטלוה חכמים]\u0006 את השבועה מן ה\u0003לוה\u0004 שהיה צריך להישבע, \u0003ושדיוה\u0004 \u0005[והטילוה]\u0006 על ה\u0003מלוה,\u0004 שהוא ישבע שלא היה המשכון שווה יותר משקל.","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר רב אשי, דקיימא לן\u0004 \u0005[שמוחזק לנו]\u0006 להלכה שיש במשנתנו חיוב נוסף של שבועה, ש\u0003זה\u0004 המלוה המחזיק בפקדון \u0003נשבע שאינה ברשותו, וזה\u0004 הלווה \u0003נשבע כמה שוה, הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את המשנה: \u0003מי\u0004 מהם \u0003נשבע תחלה? מי שהפקדון אצלו,\u0004 שהוא ישבע שאין הפקדון בידו, \u0003שמא ישבע זה\u0004 הלווה כמה היה הפקדון, \u0003ויוציא הלה את הפקדון.\u0004","ומביאים דיון בדיני משכון שהוזכרה בו משנתנו לראיה. \u0003אמר שמואל: האי מאן דאוזפיה אלפא זוזי לחבריה\u0004 \u0005[מי שהילוה אלף זוזים לחבירו]\u0006 \u0003ומשכן ליה קתא דמגלא\u0004 \u0005[לו קת של מגל\u0006 כמשכון\u0005],\u0006 אם \u0003אבד קתא דמגלא\u0004 \u0005[קת המגל]\u0006 — \u0003אבד אלפא זוזי\u0004 \u0005[אלף הזוזים],\u0006 \u0003אבל\u0004 אם היו \u0003תרתי קתאתי\u0004 \u0005[שתי קתות של מגל]\u0006 — \u0003לא,\u0004 שאם אבדה אחת מהן לא איבד את מחצית החוב, אלא כפי שוויו, שהרי לא איבד לגמרי את המשכון.","\u0003ורב נחמן אמר: אפילו\u0004 היו \u0003תרתי קתאתי\u0004 \u0005[שתי קתות],\u0006 אם \u0003אבד חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 — \u0003אבד חמש מאה\u0004 \u0005[מאות]\u0006 מהחוב, \u0003אבד\u0004 גם \u0003אידך\u0004 \u0005[\u0006החלק \u0005האחר]\u0006 — \u0003אבד כוליה\u0004 \u0005[כל\u0006 החוב\u0005],\u0006 \u0003אבל\u0004 אם מישכן לו \u0003קתא ונסכא\u0004 \u0005[קת מגל וחתיכת כסף]\u0006 ואבדה קת המגל — \u0003לא\u0004 אבדה מחצית מהחוב, שבעיקר סמך על משכון הכסף ולא על המגל. \u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003אפילו קתא ונסכא\u0004 \u0005[קת מגל וחתיכת כסף],\u0006 אם \u0003אבד נסכא\u0004 \u0005[חתיכת כסף]\u0006 — \u0003אבד פלגא\u0004 \u0005[חצי\u0006 ההלוואה\u0005],\u0006 \u0003אבד\u0004 גם \u0003קתא\u0004 \u0005[קת המגל]\u0006 — \u0003אבד כוליה\u0004 \u0005[כולו].\u0006","\u0003ו\u0004מקשים ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"סלע הלויתיך עליו ושקל היה שוה\", והלה אומר: \"לא כי, אלא סלע הלויתני עליו ושלשה דינרין היה שוה\"\u0004 — \u0003חייב\u0004 הלווה שבועה; ויש לשאול: לפי דעת שמואל שאם אבד המשכון אבד החוב, \u0003לימא ליה\u0004 \u0005[שיאמר לו\u0006 הלווה\u0005]:\u0006 \u0003הא קבילתיה\u0004 \u0005[הרי קיבלת אותו]\u0006 את חובך!","ומשיבים: \u0003מתניתין בדפריש\u0004 \u0005[משנתנו\u0006 עוסקת \u0005כשפירש]\u0006 שאינו מקבל את המשכון אלא בכדי שוויו, ולכן יש מקום לויכוח כמה היה שווה. ואילו \u0003שמואל\u0004 מדבר \u0003בדלא פריש\u0004 \u0005[כשלא פירש],\u0006 ובסתם ניתן המשכון כנגד ההלוואה כולה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שהדבר שנוי \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו בברייתא: \u0003המלוה את חבירו על המשכון ואבד המשכון\u0004 — \u0003ישבע\u0004 המלוה שאבד המשכון, וייפטר מתשלום. \u0003ויטול\u0004 \u0003את מעותיו, דברי ר' אליעזר. ר' עקיבא אומר, יכול הוא\u0004 הלווה \u0003שיאמר לו\u0004 למלוה: \u0003כלום הלויתני אלא על המשכון,\u0004 כיון ש\u0003אבד המשכון אבדו מעותיך.\u0004","\u0003אבל המלוה אלף זוז בשטר והניח משכון בידו, דברי הכל\u0004 (וגם לדעת ר' אליעזר) — \u0003אבד המשכון אבדו מעותיו.\u0004","ושואלים לגבי ביאור המחלוקת: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דשוי שיעור זוזי\u0004 \u0005[אם\u0006 שהמשכון \u0005שווה\u0006 את \u0005שיעור הכסף\u0006 שהילוה לו\u0005],\u0006"],["אם כן, \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר\u0004 שישלם הלווה? הרי איבד המלוה את המשכון! \u0003אלא לאו בדלא שוי שיעור זוזי\u0004 \u0005[האם לא\u0006 מדובר \u0005כשאינו שווה\u0006 את \u0005שיעור המעות]\u0006, \u0003וב\u0004דברי \u0003שמואל קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 שלדעת ר' אליעזר אין הלכה כשמואל, ואין המלוה מאבד את כל חובו בגלל איבוד המשכון, ור' עקיבא סבור כשמואל?","ודוחים: \u0003לא, בדלא שוי\u0004 \u0005[ב\u0006מקרה \u0005ש\u0006המשכון \u0005אינו שווה]\u0006 שיעור ההלוואה — \u0003כולי עלמא לית להו\u0004 \u0005[הכל אין להם,\u0006 אינם מקבלים\u0005]\u0006 את דברי \u0003שמואל, והכא בדשוי שיעור זוזי\u0004 \u0005[וכאן\u0006 מדובר \u0005כשהיה\u0006 המשכון \u0005שווה שיעור המעות],\u0006 \u0003וב\u0004דברי \u0003ר' יצחק קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 ש\u0003אמר ר' יצחק: מנין לבעל חוב שקונה משכון\u0004 כלומר, שיש לו בעלות ממשית על המשכון? \u0003שנאמר\u0004 בדינו של המלוה המחזיר ללווה את המשכון כדי להשתמש בו: \u0003\"ולך תהיה צדקה\"\u0004 (דברים כד, יג), ו","\u0003אם אינו קונה משכון,\u0004 שאם אין הוא נחשב כשלו — \u0003צדקה מנין לו? מכאן לבעל חוב שקונה משכון.\u0004 ולפי זה המחלוקת בין ר' אליעזר ור' עקיבא היא מה אחריותו של המלוה למשכון, שלדעת ר' אליעזר אינו קונה משכון ואינו עליו אלא כשומר חינם הפטור מגניבה ואבידה. ולדעת ר' עקיבא הריהו כמי שהמשכון בבעלותו, וחייב באחריותו, ולכן אין המלוה מקבל את כל מעותיו אלא בניכוי שווי המשכון.","ותמהים: אם כן, \u0003לימא\u0004 \u0005[נאמר]\u0006 שהלכה זו שאמר \u0003ר'\u0004 \u0003יצחק תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שנחלקו בזה ר' אליעזר ור' עקיבא? \u0003ותיסברא\u0004 \u0005[וכי יכול אתה לסבור כן]?\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יצחק\u0004 הלכה זו שמלוה קונה משכון, במקרה \u0003שמשכנו\u0004 לקח ממנו את המשכון הזה \u0003שלא בשעת הלואה,\u0004 אלא לאחר מכן, כדי לזרזו להחזיר, וכמו שמפורש באותה פרשה, אבל \u0003משכנו בשעת הלואה מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שהוא קונה את המשכון?","\u0003אלא\u0004 כך צריך לומר: \u0003משכנו שלא בשעת הלואתו\u0004 — \u0003כולי עלמא לא פליגי דאית להו\u0004 \u0005[הכל אינם חולקים שיש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר' יצחק, והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003במשכנו בשעת הלואתו, וב\u0004דין של","\u0003שומר אבדה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שמשווים דינו של המחזיק במשכון לדין זה. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שחלקו אמוראים בשאלה: מה דינו של \u0003שומר אבדה\u0004 כשאבדה לו אותה אבידה שמצא? \u0003רבה אמר:\u0004 דינו \u0003כשומר חנם, שאינו\u0004 חייב לא על אבידה ולא על גניבה."],["\u0003ורב יוסף אמר: כשומר שכר דמי\u0004 \u0005[נחשב],\u0006 משום שבשעה שעוסק במצוה זו נפטר ממצוות אחרות שיש בהן הוצאה כספית.","אם כן, \u0003לימא\u0004 \u0005[האם לומר]\u0006 שדברי \u0003רב יוסף תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004 שלדעת ר' אליעזר דינו כשומר חינם, ולכן אם אבד המשכון זכותו לקבל מעותיו, ולדעת ר' עקיבא דינו כשומר שכר, שחייב באבידה, ולכן איבד את מעותיו, וכרב יוסף? ודוחים: \u0003לא, בשומר אבידה\u0004 — \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003רב יוסף, והכא\u0004 \u0005[וכאן]\u0006 \u0003במלוה צריך למשכון קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 במקרה שהמלוה רוצה להשתמש במשכון על מנת לנכות את דמי השימוש מן החוב, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005סבור]\u0006 שאף על פי כן \u0003מצוה קא עביד\u0004 \u0005[הוא עושה],\u0006 ונפטר ממצוות אחרות, ולכן עדיין שומר שכר הוא. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מצוה קא עביד\u0004 \u0005[הוא עושה],\u0006 משום שלצורכו הוא שומרה, ולכן איננו כשומר שכר. ושבים לדון בדברי שמואל, שאמר שהמאבד את המשכון, גם אם היה פחות ערך, איבד את חובו.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת \u0005תנאים]\u0006 היא, ששנינו: \u0003המלוה את חבירו על המשכון ונכנסה\u0004 שנת \u0003שמיטה\u0004 שנשמטים בה החובות, אבל חוב שיש עליו משכון אינו נשמט, הרי \u0003אף על פי ש\u0004המשכון \u0003אינו שוה אלא פלגא\u0004 \u0005[חצי]\u0006 מן החוב — \u0003אינו משמט,\u0004 \u0003דברי רבן שמעון בן גמליאל. ר' יהודה הנשיא אומר: אם היה משכונו\u0004 שוה \u0003כנגד חובו\u0004 — \u0003אינו משמט, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003משמט.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו משמט\" דקאמר תנא קמא\u0004 \u0005[שאומר התנא הראשון\u0006 רבן שמעון בן גמליאל]? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאינו משמט את סכום הכסף שהוא \u0003כנגדו,\u0004 בשוויו של המשכון, \u0003מכלל\u0004 ש\u0003ר' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003כנגדו נמי\u0004 \u0005[גם כן]\u0006 \u0003משמט? אלא\u0004 הואיל וחובו ממילא נשמט בשמיטה \u0003אמאי תפיס\u0004 \u0005[מדוע\u0006 הוא \u0005תופס]\u0006 את ה\u0003משכון\u0004 כלל?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר בהכרח שתנאים אלה חלוקים אם המשכון משמט \u0003כנגד כולו,\u0004 כנגד כל החוב, אף שאינו שווה כל כך, \u0003וב\u0004דברי \u0003שמואל קא מיפלגי\u0004 \u0005[הם חלוקים]\u0006 האם משכון נחשב כשקול לחיוב כולו?","ודוחים: \u0003לא, לעולם\u0004 יש להבין שנחלקו אם משמט \u0003כנגדו, ובהא קמיפלגי\u0004 \u0005[ובזה הם חלוקים],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003כנגדו\u0004 כנגד ערך המשכון אינו משמט, \u0003ור' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003כנגדו נמי\u0004 \u0005[גם כן]\u0006 \u0003משמט; ודקא אמרת\u0004 \u0005[ומה שאתה אומר]:\u0006 אם כן, לדעת ר' יהודה הנשיא \u0003למאי תפיס ליה\u0004 \u0005[למה\u0006 הוא \u0005תופס]\u0006 את ה\u0003משכון? לזכרון דברים בעלמא\u0004 \u0005[בלבד]\u0006 שיהיה זכרון לחוב.","","\u0003כל הנשבעין שבתורה נשבעין ולא משלמין\u0004 שחובת שבועה מן התורה היא רק כדי להיפטר מתביעת תשלום. \u0003ואלו\u0004 שתיקנו חכמים שיהיו \u0003נשבעין ונוטלין: השכיר\u0004 שטוען שלא קיבל את שכרו. \u0003והנגזל\u0004 שטען שגזלוהו ולא התברר הדבר. \u0003והנחבל\u0004 שלא הוכח כיצד ועד כמה נחבל. \u0003ו\u0004מי \u0003שכנגדו\u0004 צריך להישבע ולהיפטר, אבל הוא \u0003חשוד על השבועה,\u0004 והופכים את חובת השבועה. \u0003וחנוני על פנקסו.\u0004","ומפרטים: \u0003השכיר, כיצד? אמר לו\u0004 השכיר: \u0003\"תן לי שכרי שיש לי בידך\", הוא\u0004 בעל הבית \u0003אומר: \"נתתי\", והלה\u0004 השכיר \u0003אומר: \"לא נטלתי\"\u0004 — \u0003הוא\u0004 השכיר \u0003נשבע ונוטל. ר' יהודה אומר: עד שתהא שם מקצת הודאה, כיצד? אמר לו: \"תן לי שכרי חמשים דינר שיש לי בידך\", והוא אומר: \"התקבלת דינר זהב\",\u0004 שהוא עשרים וחמישה דינרי כסף — במקרה זה נשבע ונוטל.","\u0003נגזל, כיצד? היו מעידין אותו שנכנס לביתו למשכנו\u0004 לקחת ממנו דברים \u0003שלא ברשות, הוא\u0004 הנגזל \u0003אומר: \"כליי נטלת\", והוא אומר: \"לא נטלתי\"\u0004 — \u0003הוא\u0004 הנגזל \u0003נשבע ונוטל. ר' יהודה אומר: עד שתהא שם מקצת הודאה, כיצד? אמר לו: \"שני כלים נטלת\", והוא אומר: \"לא נטלתי אלא אחד\".\u0004","\u0003נחבל כיצד? היו מעידים אותו שנכנס תחת ידו\u0004 (רשותו) \u0003שלם ויצא חבול, ואמר לו: \"חבלת בי\", והוא אומר: \"לא חבלתי\"\u0004 — \u0003הרי זה נשבע ונוטל. ר' יהודה אומר: עד שתהא שם מקצת הודאה, כיצד? אמר לו \"חבלת בי שתים\", והלה אומר \"לא חבלתי בך אלא אחת\".\u0004","\u0003שכנגדו חשוד על השבועה, כיצד?\u0004"],["כל שהוא חשוד על שבועה שמן התורה, \u0003אחת שבועת העדות ואחת שבועת הפקדון, ואפילו\u0004 היה חשוד על \u0003שבועת שוא.\u0004 וכן \u0003היה אחד מהן,\u0004 מאלו שנתחייבו שבועה, \u0003משחק בקוביא,\u0004 או \u0003מלוה ברבית,\u0004 או היה מ\u0003מפריחי יונים,\u0004 או מ\u0003סוחרי שביעית,\u0004 שכל אלה פסולים מדברי סופרים — \u0003שכנגדו נשבע ונוטל.\u0004","\u0003היו שניהן חשודין,\u0004 וגם שכנגדו אינו יכול להישבע — \u0003חזרה השבועה למקומה,\u0004 כאשר יבואר בגמרא, \u0003דברי ר' יוסי. ר' מאיר אומר:\u0004 כיון שאינם יכולים להישבע — \u0003יחלוקו.\u0004","\u0003והחנוני על פנקסו,\u0004 שנשבע ונוטל, \u0003כיצד? לא שיאמר לו: \"כתוב על פנקסי שאתה חייב לי מאתים זוז\",\u0004 שבכגון זה לא תיקנו חכמים שישבע החנווני ויטול, \u0003אלא\u0004 כגון ש\u0003אומר לו\u0004 לחנווני: \u0003\"תן לבני סאתים חטין\",\u0004 או: \u0003\"תן לפועלי סלע מעות\",\u0004 ולאחר זמן \u0003הוא\u0004 (החנווני) \u0003אומר: \"נתתי\u0004 להם\", \u0003והן אומרים: \"לא נטלנו\"\u0004 — במקרה זה, שבעל הבית מודה שאמר לו לתת, וגם כתוב הדבר על פנקסו של החנווני — \u0003הוא\u0004 החנווני \u0003נשבע ונוטל, והן\u0004 הפועלים שטוענים שלא קיבלו שכר — גם הם \u0003נשבעין ונוטלין.\u0004","\u0003אמר בן ננס: כיצד אלו ואלו באין לידי שבועת שוא?\u0004 הרי ברור שאחד מהם משקר! \u0003אלא הוא\u0004 החנווני \u0003נוטל שלא בשבועה, והן\u0004 הפועלים \u0003נוטלין שלא בשבועה.\u0004","\u0003אמר לחנוני: \"תן לי בדינר פירות\", ונתן לו.\u0004 לאחר מכן \u0003אמר לו\u0004 החנווני: \u0003\"תן לי אותו דינר\u0004 שאתה חייב לי\", \u0003אמר לו: \"נתתיו לך ונתתו באונפלי\u0004 (בכיס המעות) שלך\" — \u0003ישבע בעל הבית שנתן לו את הדינר. אמר לו\u0004 לחנווני: \u0003\"תן לי את הפירות\", אמר לו: \"נתתים לך והולכתים לתוך ביתך\"\u0004 — במקרה זה \u0003ישבע חנוני. ר' יהודה אומר: כל שהפירות בידו ידו על העליונה\u0004 ואינו צריך להישבע.","ובדומה לזה \u0003אמר לשולחני\u0004 (המחליף מעות ופורטן): \u0003\"תן לי בדינר מעות\", ונתן לו.\u0004 לאחר מכן \u0003אמר לו\u0004 השולחני: \u0003\"תן לי את הדינר\", אמר לו: \"נתתי לך ונתתו באונפלי\"\u0004 — \u0003ישבע בעל הבית\u0004 שנתן. \u0003נתן לו\u0004 בעל הבית \u0003את הדינר, אמר לו\u0004 בעל הבית: \u0003\"תן לי את המעות\", אמר לו: \"נתתים לך והשלכת לתוך כיסך\"\u0004 — \u0003ישבע שולחני. ר' יהודה אומר: אין דרך שולחני ליתן איסר עד שיטול\u0004 \u0003דינר,\u0004 ולכן בכל מקרה שנמצאות המעות בידי המקבל, מן הסתם כבר קיבל השולחני את שלו.","ויש עוד שבועות כיוצא באלה שצריך להישבע לפני שנוטל. \u0003כשם שאמרו\u0004 במשנה במסכת כתובות: \u0003הפוגמת כתובתה\u0004 (אשה המודה שקיבלה מקצת מכתובתה) ותובעת השאר, \u0003לא תפרע\u0004 את שאר הסכום \u0003אלא בשבועה; ו\u0004כן אם \u0003עד אחד מעידה שהיא\u0004 (הכתובה) \u0003פרועה\u0004 כבר, \u0003לא תפרע אלא בשבועה;\u0004 וכיוצא בזה, אם באה לטרוף \u0003מנכסים משועבדים\u0004 נכסי בעלה שנמכרו לאחרים, או לגבות \u0003מנכסי יתומים\u0004 \u0003לא תפרע אלא בשבועה; ו\u0004כן \u0003הנפרעת שלא בפניו\u0004 כאשר הבעל אינו נמצא במקום, \u0003לא תפרע אלא בשבועה;\u0004 \u0003וכן היתומים\u0004 שבאים להיפרע בשטר חוב שירשו מאביהם, \u0003לא יפרעו\u0004 מנכסי הלווים \u0003אלא בשבועה.\u0004","שצריכים הם להישבע: \u0003\"שבועה שלא פקדנו אבא\u0004 שלא ציוונו בשעת מותו שלא נגבה את השטר, \u0003ו\u0004ש\u0003לא אמר לנו אבא\u0004 בחייו ששטר זה כבר נפרע, ו\u0003שלא מצינו\u0004 (מצאנו) \u0003בין שטרותיו של אבא\u0004 שובר המוכיח \u0003ששטר זה פרוע\",\u0004 ואז הם נוטלים. \u0003ר' יוחנן בן ברוקה אומר: אפילו נולד הבן לאחר מיתת האב\u0004 — \u0003הרי זה נשבע ונוטל. אמר ר' שמעון בן גמליאל: אם יש עדים שאמר האב בשעת מיתתו: \"שטר זה אינו פרוע\"\u0004 — \u0003הוא\u0004 הבן \u0003נוטל שלא בשבועה.\u0004","\u0003ואלו נשבעין\u0004 שאינם חייבים ממון, אף \u0003שלא בטענה,\u0004 שגם כאשר אין הצד שכנגד טוען תביעה כספית מוגדרת, מכל מקום יישבעו כדי לברר את הדברים: \u0003השותפין\u0004 נשבעים זה לזה, \u0003והאריסין\u0004 שעובדים אצל אדם תמורת חלק מן היבול, \u0003והאפוטרופין, והאשה הנושאת והנותנת בתוך הבית\u0004 שהיא המנהלת את נכסי היתומים, \u0003ובן הבית\u0004 כלומר, אדם שהיה ממונה על הבית ומטפל בו. ובאיזה מקרה הם נשבעים? כאשר \u0003אמר לו: \"מה אתה טועניני\"?\u0004 והשיב לו שכנגדו: \u0003\"רצוני שתשבע לי\u0004 שלא נטלת לעצמך משלי\" — הרי זה \u0003חייב\u0004 להישבע.","\u0003חלקו השותפין והאריסין\u0004 — \u0003אין יכול\u0004 השותף או בעל הבית \u0003להשביעו\u0004 עוד. אבל אם \u0003נתגלגל לו שבועה ממקום אחר,\u0004 שנתחייב להישבע למי שהיה שותפו, או לבעל הבית — \u0003מגלגלין עליו את הכל,\u0004 שיכול לומר לו שאגב שבועה זו ישבע לו גם על טענה אחרת. \u0003והשביעית\u0004 (שנת השמיטה) כשם שמשמטת את החוב כך היא \u0003משמטת את\u0004 חובת \u0003השבועה\u0004 שצריך אדם להישבע על חובו.","שנינו במשנה: \u0003כל הנשבעין שבתורה נשבעין ולא משלמין.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא דין תורה? ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ולקח בעליו ולא ישלם\"\u0004 (שמות כב, ב), לומר: ש\u0003מי שעליו לשלם\u0004 — \u0003לו\u0004 חובת ה\u0003שבועה.\u0004","שנינו במשנה: \u0003ואלו נשבעין ונוטלין\u0004 השכיר וכו'. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 ה\u0003שכיר דתקינו ליה רבנן דמשתבע ושקיל\u0004 \u0005[שתיקנו לו חכמים שנשבע ונוטל]?\u0006 \u0003אמר רב יהודה אמר שמואל: הלכות גדולות שנו כאן.\u0004 ותוהים: \u0003הלכות, הני הלכתא נינהו\u0004 \u0005[\u0006וכי \u0005אלה הלכות\u0006 למשה מסיני \u0005הן]?\u0006 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון זו: \u0003תקנות גדולות שנו כאן.\u0004","ותוהים שוב על הלשון: \u0003גדולות, מכלל דאיכא\u0004 \u0005[שיש]\u0006 \u0003קטנות?\u0004 ומה הן הקטנות?","\u0003אלא אמר רב נחמן אמר שמואל: תקנות קבועות שנו כאן, עקרוה רבנן\u0004 \u0005[חכמים]\u0006 את ה\u0003שבועה מבעל הבית ושדיוה\u0004 \u0005[והטילוה]\u0006 על ה\u0003שכיר, משום כדי חייו,\u0004 משום שהשכיר נזקק לשכרו כדי לחיות. ושואלים: \u0003משום כדי חייו\u0004 של ה\u0003שכיר קנסינן ליה\u0004 \u0005[קונסים אנו אותו]\u0006 את \u0003בעל הבית?\u0004 ומשיבים: \u0003בעל הבית גופיה\u0004 \u0005[עצמו]\u0006 \u0003ניחא ליה דמשתבע שכיר ושקיל\u0004 \u0005[נוח לו שיישבע השכיר ויטול],\u0006 \u0003כי היכי דאיתגרון ליה\u0004 \u0005[כדי שיישכרו לו]\u0006 \u0003פועלין,\u0004 שאם לא כן יחששו פועלים מלהשכיר עצמם לאדם שאינו משלם.","ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003שכיר ניחא ליה דלשתבע\u0004 \u0005[נוח לו שיישבע]\u0006 \u0003בעל הבית ונפקע\u0004 \u0005[ויפקע\u0006 וייפטר מחובו\u0005],\u0006 \u0003כי היכי דליגריה\u0004 \u0005[כדי שישכרנו]\u0006 \u0003בעל הבית!\u0004 ומשיבים: \u0003בעל הבית על כורחיה אגר\u0004 \u0005[על כורחו\u0006 הוא \u0005שוכר]\u0006 את הפועלים, והוא נזקק להם ביותר. ודוחים: \u0003שכיר נמי\u0004 \u0005[גם כן]\u0006 \u0003על כורחיה מיתגר\u0004 \u0005[על כורחו\u0006 הוא \u0005נשכר]\u0006 שהוא צריך לעבודה! \u0003אלא\u0004 צריך לומר כך, \u0003בעל הבית טרוד בפועליו הוא,\u0004 וכיון שהוא טרוד — יש להניח שהוא שכח ולא שילם.","ושואלים: אם כן, אם אנו חוששים ששכח, \u0003וליתב ליה\u0004 \u0005[ושיתן לו]\u0006 לשכיר \u0003בלא שבועה!\u0004","ומשיבים: השבועה באה \u0003כדי להפיס דעתו של בעל הבית,\u0004 שתנוח דעתו, שלא יחשוב שלקח הפועל ממנו כסף בטענת שוא. ושואלים: \u0003וליתב ליה\u0004 \u0005[וש\u0006יתקנו חכמים ש\u0005יתן לו]\u0006 שכרו \u0003בעדים,\u0004 ולא יהיה עוד ספק! ומשיבים: \u0003טריחא ליה מילתא\u0004 \u0005[טירחה\u0006 היא \u0005בדבר עבורו]\u0006 לחפש עדים. ושואלים: \u0003וליתב ליה מעיקרא\u0004 \u0005[וש\u0006יתקנו חכמים ש\u0005יתן לו מתחילה]\u0006 בזמן שהוא שוכר אותו, ואז לא יצטרכו להישבע! ומשיבים: \u0003שניהן רוצין בהקפה,\u0004 שניהם נוח להם שיהא זה בהקפה, שבעל הבית פעמים שאין בידו כסף מוכן, וגם הפועל מעדיף לקבל את שכרו רק בסוף היום."],["ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאנו חוששים שבעל הבית שכח מתוך טרדתו, \u0003אפילו\u0004 כאשר \u0003קצץ\u0004 (קבע מחיר) \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא כן הדין! \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 אם ה\u0003אומן אומר: \"שתים קצצת לי\"\u0004 כלומר, קבעת לי שאני מקבל שתים, \u0003והלה\u0004 בעל הבית \u0003אומר: \"לא קצצתי לך אלא אחת\"\u0004 — \u0003המוציא מחבירו עליו הראיה\u0004 בעדים, ולא די בשבועה. ומדוע אין אומרים גם פה שיישבע האומן ויטול? ומשיבים: \u0003קציצה\u0004 (קביעת מחיר) \u0003ודאי מידכר דכיר ליה\u0004 \u0005[הוא זוכר אותה].\u0006","ומקשים עוד: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שחוששים מפני טרדת בעל הבית, \u0003אפילו עבר זמנו\u0004 של תביעת השכר \u0003נמי\u0004 \u0005[גם כן]\u0006 ישבע ויטול! \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 אם \u0003עבר זמנו\u0004 של תשלום השכר (במשך הלילה שלאחר יום העבודה) \u0003ולא נתן לו\u0004 — \u0003הרי זה\u0004 האומן \u0003אינו נשבע ונוטל,\u0004 אלא צריך להביא ראיה בעדים!","ומשיבים: \u0003חזקה אין בעל הבית עובר ב\"בל תלין\"\u0004 (\"לא תלין פעולת שכיר אתך עד בוקר\". ויקרא יט, יג), ובוודאי שילם את חובו בזמן. ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003בעל הבית טרוד בפועליו הוא,\u0004 ושמא שכח! ומשיבים: \u0003הני מילי מקמי דלימטי זמן חיובא הוא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005לפני שמגיע זמן החיוב\u0006 לשלם\u0005],\u0006 משום שאז הוא טרוד והוא שוכח, אבל \u0003כי מטי זמן חיובא\u0004 — \u0003רמי אנפשיה ומידכר\u0004 \u0005[כאשר מגיע זמן החיוב\u0006 — \u0005מטיל\u0006 את הדבר \u0005על עצמו ונזכר].\u0006","ושואלים: \u0003וכי\u0004 ה\u0003שכיר עובר משום \"בל תגזול\"\u0004 (\"לא תגזול\". שם), שאנו חושדים בו שהוא תובע שכר כפול? ומשיבים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בעל הבית איכא תרי חזקי\u0004 \u0005[יש שתי חזקות]:\u0006 \u0003חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 ש\u0003אין בעל הבית עובר ב\"בל תלין\", וחדא\u0004 \u0005[ואחת],\u0006 ש\u0003אין שכיר משהא שכרו,\u0004 אלא תובע מיד. ולכן מסתבר שאם לא תבע בזמנו שהצדק עם בעל הבית, ואינו נוטל אלא בראיה.","\u0003אמר רב נחמן אמר שמואל: לא שנו\u0004 הלכה זו שהשכיר נשבע ונוטל את שכרו, \u0003אלא ששכרו\u0004 בעל הבית \u0003בעדים, אבל שכרו שלא בעדים, מתוך שיכול\u0004 בעל הבית \u0003לומר לו: \"לא שכרתיך מעולם\", יכול לומר לו: \"שכרתיך ונתתי לך שכרך\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יצחק: יישר,\u0004 יפה אמרת, \u0003וכן אמר ר' יוחנן.\u0004","ומעירים: האם \u0003מכלל\u0004 הדברים אתה לומד \u0003דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 \u0003ריש לקיש\u0004 בענין זה? ומשיבים: אין הדבר ברור, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003מישתא הוה שתי ליה, ושתיק ליה\u0004 \u0005[שותה היה\u0006 באותה השעה, \u0005ושתק לו],\u0006 ולא נתברר אם חלק עליו. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003מישהא הוה שהי ליה, ושתיק ליה\u0004 \u0005[שוהה היה לו\u0006 עד שיגמור דבריו, \u0005ושתק לו],\u0006 ולא התברר אם בסופו של דבר חלק עליו או לא.","\u0003איתמר נמי\u0004 \u0005[נאמר\u0006 \u0005גם כן]\u0006 בשם אמורא אחר, \u0003אמר רב מנשיא בר זביד אמר רב: לא שנו אלא ששכרו בעדים, אבל שכרו שלא בעדים, מתוך שיכול לומר לו: \"לא שכרתיך מעולם\"\u0004 — \u0003יכול לומר לו: \"שכרתיך, ונתתי לך שכרך\".\u0004","\u0003אמר רמי בר חמא: כמה מעליא הא שמעתא\u0004 \u0005[מעולה שמועה זו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי מעליותא\u0004 \u0005[מה המעלה שבה]?\u0006 \u0003אם כן\u0004 אתה אומר, שסומכים על ה\"מיגו\" שיכול הנתבע לומר שלא היו דברים מעולם, \u0003שבועת שומרין דחייב רחמנא\u0004 \u0005[שחייבה התורה]\u0006 \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 הרי \u0003מתוך שיכול\u0004 השומר \u0003לומר לו\u0004 למפקיד: \u0003\"לא היו דברים מעולם,\u0004 ולא לקחתי ממך דבר\", \u0003יכול לומר לו: \"נאנסו\",\u0004 נאבדו או נלקחו באונס, שאין שומר שכר חייב בזה, ולא יצטרך להישבע, ואם כן, בטלה שבועת השומרים!","ענה לו רמי בר חמא: שבועת השומרים יכולה להתקיים במקרה \u0003דאפקיד ליה\u0004 \u0005[שהפקיד לו]\u0006 \u0003בעדים.\u0004 והקשה לו רבא: בכל זאת, \u0003מתוך שיכול לומר לו \"החזרתיו לך\", יכול לומר לו \"נאנסו\"!\u0004","השיב לו רמי בר חמא: ניתן להעמיד זאת במקרה \u0003דאפקיד ליה בשטרא\u0004 \u0005[שהפקיד לו בשטר],\u0006 ובמקרה כזה אינו יכול לטעון שהחזיר אלא בראיה ברורה.","ומעירים: \u0003מכלל\u0004 הדברים אתה למד \u0003דתרוייהו סבירא להו\u0004 \u0005[ששניהם,\u0006 רמי בר חמא ורבא, \u0005סבורים הם]\u0006 ש\u0003המפקיד אצל חבירו בעדים\u0004 — \u0003אין צריך להחזיר לו בעדים,\u0004 אבל המפקיד \u0003בשטר\u0004 — \u0003צריך להחזיר לו בעדים,\u0004 שהרי גם רבא לא דחה את דברי רמי בר חמא, לומר שיכול גם כאן לומר \"החזרתיו\".","מסופר, \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רמי בר חמא עליה\u0004 \u0005[עליו]\u0006 על \u0003רב ששת\u0004 את הכתוב הזה: \u0003\"וישם דוד את הדברים האלה בלבו\"\u0004 (שמואל א כא, יג), שרב ששת היה מחזר למצוא ראיות או סתירה לדברי רב ושמואל. \u0003דאשכחיה\u0004 \u0005[שמצא אותו]\u0006 \u0003רב ששת לרבה בר שמואל, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תני מר מידי\u0004 \u0005[שנה אדוני דבר]\u0006 \u0003ב\u0004הלכות \u0003שכיר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, תנינא\u0004 \u0005[כן, שניתי]\u0006 ברייתא זו: \u0003שכיר בזמנו נשבע ונוטל, כיצד? בזמן שאמר לו: \"שכרתני ולא נתת לי שכרי\", והלה,\u0004 בעל הבית \u0003אומר: \"שכרתיך ונתתי לך שכרך\". אבל אמר לו: \"שתים קצצת לי\", והלה אומר: \"לא קצצתי לך אלא אחת\"\u0004 — \u0003המוציא מחבירו עליו הראיה.\u0004 עד כאן לשון הברייתא, ורצה רב ששת ללמוד מכאן לענייננו.","\u0003הא מדסיפא\u0004 \u0005[הרי מ\u0006כיון \u0005שסופה]\u0006 \u0003בראיה הוי\u0004 \u0005[הוא],\u0006 \u0003רישא\u0004 \u0005[בתחילה]\u0006 שנשבע ונוטל, מדובר \u0003בלא ראיה,\u0004 ומשמע שאין השכיר צריך להביא ראיה כלשהי לדבריו, ואינו צריך להביא עדים שנשכר לעבודה. והוא שלא כדברי רב ושמואל, שאמרו שאם שכרו שלא בעדים צריך להביא ראיה.","\u0003אמר רב נחמן בר יצחק:\u0004"],["\u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 של אותה ברייתא שניהם \u0003בראיה,\u0004 שאף במקרה הראשון, שהשכיר נשבע ונוטל, מדובר שיש לשכיר גם ראיה שנשכר לעבודה. אלא \u0003ראיה\u0004 שהיא לעצמה מחייבת את בעל הבית \u0003לשלם קתני\u0004 \u0005[שנה],\u0006 \u0003ראיה\u0004 שמביאה רק לחיוב של \u0003שבועה לא קתני\u0004 \u0005[שנה].\u0006","\u0003אמר ר' ירמיה בר אבא, שלחו ליה מבי\u0004 \u0005[לו מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב,\u0004 לאחר מותו, \u0003לשמואל: ילמדנו רבינו, אומן\u0004 בעל מלאכה \u0003אומר: \"שתים קצצת\u0004 (קצבת) \u0003לי\u0004 עבור עבודתי\", \u0003והלה\u0004 בעל הבית \u0003אומר: \"לא קצצתי לך אלא אחת\", מי נשבע? אמר להן: בזו ישבע בעל הבית ויפסיד אומן,\u0004 שחכמים תיקנו שהשכיר נשבע ונוטל משום שבעל הבית טרוד בפועליו ושכח, אבל \u0003קציצה ודאי מידכר דכירי אינשי\u0004 \u0005[זוכרים אנשים]\u0006 ואין לומר ששכח.","ותוהים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רבה בר שמואל\u0004 ברייתא זו: \u0003קצץ\u0004 — \u0003המוציא מחברו עליו הראיה, ו\u0004משמע מכאן: \u0003אי לא מייתי\u0004 \u0005[אם לא מביא]\u0006 האומן \u0003ראיה\u0004 — \u0003פקע\u0004 כלומר, בטלה טענתו. ולפי דברי שמואל \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ישבע בעל הבית ו\u0004רק אז \u0003יפסיד אומן! אמר רב נחמן: לצדדין קתני\u0004 \u0005[שנינו]\u0006 כלומר, הלכה זו יש בה שני צדדים, \u0003או\u0004 שהאומן \u0003מביא ראיה ויטול, או ישבע בעל הבית ויפסיד אומן,\u0004 ולא שנה אלא אחת משתי אפשרויות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי שמואל ממה ששנינו בברייתא: \u0003הנותן טליתו לאומן\u0004 לתיקון, \u0003אומן אומר: \"קצצת לי שתים\", והלה\u0004 בעל הבית \u0003אומר: \"לא קצצתי לך אלא אחת\", כל זמן שטלית ביד אומן\u0004 — \u0003על בעל הבית להביא ראיה\u0004 לדבריו. \u0003נתנה לו\u0004 האומן, ותובע שכרו, אם היה זה \u0003בזמנו\u0004 בזמן בו מוטל על בעל הבית לשלם קודם שיעבור על איסור הלנת שכר — \u0003נשבע\u0004 האומן \u0003ונוטל, עבר זמנו\u0004 — \u0003המוציא מחברו עליו הראיה.\u0004","שנינו איפוא כי \u0003בזמנו מיהא\u0004 \u0005[על כל פנים]\u0006 האומן \u0003נשבע ונוטל,\u0004 ולדברי שמואל \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ישבע בעל הבית ויפסיד אומן!\u0004","\u0003אמר רב נחמן בר יצחק: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: כל זמן ששבועה נוטה אצל בעל הבית,\u0004 שמעיקר הדין היה ראוי שבעל הבית יישבע וייפטר — תיקנו חכמים ש\u0003שכיר נשבע ונוטל.\u0004 אבל לדעת חכמים — בעל הבית נשבע ונפטר.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' יהודה?\u0004 כלומר, מהיכן אנו למדים שכך היא דעתו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' יהודה דמתניתין\u0004 \u0005[של משנתנו],\u0006 הלוא \u0003אחמורי קא מחמיר\u0004 \u0005[מחמיר הוא]\u0006 בענין זה, ומצמצם את המקרים בהם השכיר נשבע ונוטל, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 אין השכיר נשבע ונוטל \u0003עד שתהא שם מקצת הודאה,\u0004 שבעל הבית חייב שבועה מן התורה, אבל אם בעל הבית כופר הכל — אין השכיר נשבע ונוטל. ומן הסתם הוא סבור כן גם במקרה של קציצה!","\u0003אלא\u0004 הכוונה היא לדברי \u0003ר' יהודה\u0004 המפורשים שב\u0003ברייתא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שכיר כל זמן שלא עבר עליו זמנו\u0004 — \u0003הרי זה נשבע ונוטל, ואם לאו,\u0004 שעבר זמנו — \u0003אינו נשבע ונוטל. ואמר ר' יהודה: אימתי? בזמן שאמר לו\u0004 לבעל הבית: \u0003\"תן לי שכרי חמשים דינר שיש לי בידך\" והוא\u0004 בעל הבית \u0003אומר: \"התקבלת מהן דינר זהב\", או שאמר לו: \"שתים קצצת\" והלה אומר: \"לא קצצתי לך אלא אחת\",\u0004 שהיתה כאן הודאה במקצת.","\u0003אבל\u0004 אם \u0003אמר לו\u0004 בעל הבית: \u0003\"לא שכרתיך מעולם\", או שאמר לו: \"שכרתיך ונתתי לך שכרך\"\u0004 — \u0003המוציא מחבירו עליו הראיה.\u0004 הרי שר' יהודה אומר במפורש שבמקרה של קציצה — נשבע השכיר ונוטל.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: אלא\u0004 לפי הסבר זה, ברייתא זו ב\u0003קצץ,\u0004 שאם היה זה בזמנו נשבע השכיר ונוטל, שיטת \u0003ר' יהודה היא ולא רבנן\u0004 \u0005[חכמים]?\u0006 אבל תמוה הדבר, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003היכי\u0004 \u0005[במקום]\u0006 ש\u0003מחמיר ר' יהודה\u0004 על השכיר, במשנתנו, שטוען בעל הבית ששולם כל שכרו, ולדעת ר' יהודה צריך השכיר להביא ראיה — \u0003מקילי רבנן\u0004 \u0005[מקילים חכמים]\u0006 על השכיר, ואומרים שיישבע השכיר ויטול. \u0003היכא דמקיל\u0004 \u0005[במקום שמקל]\u0006 \u0003ר' יהודה,\u0004 בקציצה, שלדעת ר' יהודה השכיר נשבע ונוטל — \u0003מחמרי רבנן\u0004 \u0005[מחמירים חכמים]\u0006 ואומרים שיישבע בעל הבית הבית וייפטר?","על קושיה זו משיבים: \u0003ואלא מאי\u0004 \u0005[מה],\u0006 ברייתא זו שיטת \u0003רבנן\u0004 \u0005[חכמים\u0006 היא\u0005]?\u0006 \u0003ואלא הא דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה]\u0006 \u0003רבה בר שמואל: קצץ\u0004 — \u0003המוציא מחבירו עליו הראיה,\u0004 אם כן, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 שיטת \u0003ר' יהודה ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]!\u0006 שהרי לשיטת חכמים נשבע בעל הבית, ולשיטת ר' יהודה שכיר נשבע גם על הקציצה!","\u0003אלא אמר רבא:\u0004 אין מקום מתחילה לקושייתו של רב שישא, שכן מחלוקת ר' יהודה וחכמים במשנתנו (האם שכיר נשבע ונוטל רק כשבעל הבית מודה במקצת) אינה האם להקל או להחמיר על השכיר, אלא באלו מקרים ניתן לתקן שבועה. ו\u0003בהא קמיפלגי\u0004 \u0005[\u0006בענין \u0005זה חלוקים הם],\u0006 \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003בדאורייתא עבדו ליה תקנתא\u0004 \u0005[ב\u0006דברים \u0005שמן התורה עשו לו תקנה]\u0006 \u0003לשכיר,\u0004 שבכל מקום שיש מן התורה חובת שבועה על בעל הבית (כשהוא מודה במקצת) עשו חכמים תקנה שיישבע השכיר ויטול. \u0003ובדרבנן\u0004 \u0005[ובדברי חכמים]\u0006 במקרים שראו חכמים צורך לתקן שבועה (כאשר בעל הבית כופר בכל), \u0003הואי תקנתא\u0004 \u0005[הרי זו תקנה],\u0006 \u0003ותקנתא לתקנתא לא עבדינן\u0004 \u0005[ותקנה לתקנה אין אנו עושים],\u0006 אלא בעל הבית עצמו יישבע וייפטר.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בדרבנן נמי עבדינן תקנתא\u0004 \u0005[ב\u0006שבועה שמ \u0005דברי חכמים גם כן עושים תקנה]\u0006 \u0003לשכיר,\u0004 שיישבע הוא ויטול. ולאור זה יש להבין את המחלוקת בענין קציצה, שלדעת ר' יהודה כשבעל הבית מודה במקצת יישבע השכיר ויטול, ואילו חכמים סבורים כי \u0003קציצה\u0004 (קציבת מחיר) הוא \u0003מידכר דכיר\u0004 \u0005[זוכר],\u0006 ולכן השאירו את השבועה בידי בעל הבית.","שנינו במשנה: \u0003נגזל כיצד? היו מעידין אותו שנכנס לביתו למשכנו\u0004 שלא ברשות, בעל הבית אומר: \"כלי נטלת\", והוא אומר: \"לא נטלתי\" — בעל הבית נשבע ונוטל. ותוהים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא משכנו,\u0004 שעצם הכניסה על מנת למשכנו אינה ראיה שגזלו! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רב נחמן: האי מאן דנקיט נרגא בידיה\u0004 \u0005[מי שמחזיק גרזן בידו],\u0006 \u0003ואמר: \"איזיל ואקטליה לדקלא דפלניא\"\u0004 \u0005[ואומר \"אלך ואכרות את הדקל של פלוני\"],\u0006 \u0003ואשתכח דקטיל ושדי\u0004 \u0005[ונמצא\u0006 הדקל \u0005כרות ומוטל]\u0006 — \u0003לא אמרינן דהוא קטליה\u0004 \u0005[אין אנו אומרים שהוא כרתו],\u0006 אלא מחפשים ראיה לדבר,","\u0003אלמא עביד איניש דגזים ולא עביד\u0004 \u0005[מכאן שעשוי אדם שמגזים\u0006 ומאיים \u0005ואינו עושה\u0006 מעשה\u0005],\u0006 \u0003הכא נמי דגזים ולא עביד\u0004 \u0005[כאן גם כן\u0006 יש לומר \u0005שהגזים\u0006 ואמר שהולך למשכנו \u0005ולא עשה]!\u0006 ומתרצים, \u0003אימא\u0004 \u0005[אמור]\u0006 במשנתנו: לא שנכנס לביתו כדי למשכנו, אלא: \u0003ומשכנו,\u0004 שראו עדים שלקח משם חפצים. ושואלים: אם כן, שהיו עדים, \u0003וליחזי מאי\u0004 \u0005[ושנראה מה]\u0006 \u0003משכנו!\u0004 ומה צורך בשבועה? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: בטוענו\u0004 בעל הבית ב\u0003כלים\u0004 קטנים \u0003הניטלין תחת כנפיו\u0004 (תחת כנפי הבגד), שטוען שהוא לקח אותם, והעדים לא ראו מה לקח.","\u0003אמר רב יהודה\u0004 בנושא דומה: \u0003ראוהו\u0004 לאדם זר שנכנס לבית \u0003שהטמין כלים תחת כנפיו ויצא,\u0004"],["\u0003ואמר: \"לקוחין הן בידי\"\u0004 כלומר, קניתי אותם — \u0003אינו נאמן. ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאינו נאמן, \u0003אלא\u0004 שיצא מאצל \u0003בעל הבית שאינו עשוי\u0004 בדרך כלל \u0003למכור כליו, אבל\u0004 אם היה זה \u0003בעל הבית העשוי למכור את כליו\u0004 — \u0003נאמן\u0004 המוציא. \u0003ו\u0004בבעל הבית \u0003שאין עשוי למכור את כליו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין המוציא נאמן, \u0003אלא\u0004 כשהוציא תחת כנפיו \u0003דברים שאין דרכן להטמין\u0004 אלא נושאים אותם בגלוי, שכיון שהוא הוציאם בסתר — משמע שנוטלם שלא כדין, \u0003אבל דברים שדרכן להטמין\u0004 — \u0003נאמן\u0004 הוא לומר שקנה אותם.","\u0003ושאין דרכן להטמין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאינו נאמן, \u0003אלא איניש דלא צניע\u0004 \u0005[אדם שאינו צנוע]\u0006 שדרכו לשאת כלים שונים ברבים, \u0003אבל איניש דצניע\u0004 — \u0003היינו אורחיה\u0004 \u0005[אדם צנוע\u0006 — \u0005זו דרכו]\u0006 שהוא מטמין. \u0003ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין הלוקח נאמן, \u0003אלא\u0004 כש\u0003זה\u0004 בעל הבית \u0003אומר \"שאולין\u0004 הכלים בידו, ואני תובע ממנו להחזירם\", \u0003וזה\u0004 הלוקח \u0003אומר: \"לקוחין\u0004 (קנויים) הם בידי\", \u0003אבל\u0004 להאשים אותו שהם \u0003גנובין\u0004 — \u0003לאו כל כמיניה\u0004 \u0005[אין זה בכוחו],\u0006 כי \u0003לאחזוקי איניש בגנבי לא מחזקינן\u0004 \u0005[להחזיק אדם בגניבה אין מחזיקים אנו],\u0006 ואין סומכים על דברי בעל הבית.","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאין הלוקח נאמן \u0003אלא בדברים העשוין להשאיל ולהשכיר,\u0004 שיש מקום לטענת בעל הבית שאדם זה שאל כלים אלו ואינו מחזירם, \u0003אבל דברים שאין עשוין להשאיל ולהשכיר\u0004 — \u0003נאמן,\u0004 ש\u0003שלח רב הונא בר אבין: דברים העשוין להשאיל ולהשכיר,\u0004 שבעל הבית תובעם, \u0003ואמר\u0004 המחזיק בהם: \u0003\"לקוחין הן בידי\"\u0004 — \u0003אינו נאמן. כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבא אפיק זוגא דסרבלא וספרא דאגדתא מיתמי\u0004 \u0005[הוציא מספריים של מעילים וספר אגדה מיתומים],\u0006 שהתובע הוכיח שהיו הדברים הללו שייכים לו, ושאבי היתומים לקח אותם ממנו, והיו אלה \u0003בדברים העשוין להשאיל ולהשכיר.\u0004","על מה ששנינו במשנה כי הנגזל נשבע ונוטל, \u0003אמר רבא:\u0004 לא רק בעל הגזילה עצמו נאמן בכך, אלא \u0003אפילו שומר\u0004 שמסרו לו את שמירת הבית \u0003נשבע, אפילו אשתו של שומר נשבעת. בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: שכירו ולקיטו,\u0004 העובדים עבורו ואינם ממונים לשמור, \u0003מאי\u0004 \u0005[מהו]?\u0006 האם יכולים הם להישבע? לדבר זה לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי:\u0004 אם \u0003טענו\u0004 בעל הבית את הנכנס למשכנו \u0003בכסא דכספא\u0004 \u0005[בכוס כסף]\u0006 שלקח ממנו, והרי היו הכלים שלקח טמונים ואין להוכיח מה לקח, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם יצטרך המוציא מן הבית לשלם אפילו עבור דבר יקר כל כך? אמר לו: \u0003חזינא\u0004 \u0005[רואים אנו],\u0006 \u0003אי איניש דאמיד\u0004 \u0005[אם אדם עשיר]\u0006 \u0003הוא\u0004 בעל הבית, \u0003או איניש דמהימן\u0004 \u0005[אדם נאמן]\u0006 \u0003הוא, דמפקדי אינשי גביה\u0004 \u0005[שמפקידים אנשים אצלו]\u0006 אף שהוא עצמו אינו עשיר — \u0003משתבע ושקיל\u0004 \u0005[נשבע ונוטל],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 אין בו דברים אלה — \u0003לא\u0004 נותנים לו את הזכות להישבע וליטול.","שנינו במשנה: \u0003נחבל כיצד?\u0004 היו מעידים שנכנס שלם תחת ידו, ויצא חבול, והוא טוען שהלה חבל בו — נשבע ונוטל. \u0003אמר רב יהודה אמר שמואל: לא שנו\u0004 שצריך להישבע שפלוני חבל בו, \u0003אלא\u0004 שנחבל בגופו \u0003במקום שיכול\u0004 אדם \u0003לחבל בעצמו,\u0004 שצריך להישבע שההוא חבלו, \u0003אבל במקום שאינו יכול לחבל בעצמו,\u0004 ובוודאי שהלה חבל בו — \u0003נוטל שלא בשבועה.\u0004","ושואלים: \u0003וניחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003בכותל נתחכך\u0004 ומחמת זה היתה הפציעה! \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא:\u0004 מדובר כגון \u0003שעלתה לו נשיכה בגבו ובין אצילי ידיו,\u0004 שנשיכה אינה באה מחיכוך בכותל וכדומה, ובוודאי אינו יכול לעשות זאת לעצמו. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אדם \u0003אחר עביד ליה\u0004 \u0005[עשה לו],\u0006 ולא אדם זה! ומשיבים: מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003אחר,\u0004 שלא היה אדם אחר במקום, אלא זה שנראה שחבל בו.","שנינו במשנה: \u0003וכשנגדו חשוד\u0004 על השבועה כיצד? אחד החשוד על שבועת העדות ואחד החשוד על שבועת הפקדון, \u0003ואפילו שבועת שוא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אפילו שבועת שוא\"?\u0004 מהו \"אפילו\"?","ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]:\u0006 \u0003לא מיבעיא הנך דאית בהו\u0004 \u0005[נצרכה\u0006 ההלכה רק ב\u0005אלה שיש בהם]\u0006 \u0003כפירת ממון,\u0004 כגון שבועת העדות ושבועת הפקדון, \u0003אלא אפילו הא נמי\u0004 \u0005[זו גם כן],\u0006 שבועת שוא, ש\u0003כפירת דברים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ואין לו רווח בזה — בכל זאת \u0003לא מהימן\u0004 \u0005[אינו נאמן]\u0006 בשבועה אחרת, כיון שהוא נשבע לשקר.","ושואלים: \u0003וליתני נמי\u0004 \u0005[ושישנה גם כן]\u0006 מי שחשוד על \u0003שבועת בטוי,\u0004 שאף היא שבועת שקר בלא חיוב ממון! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר הוא שונה]\u0006 הרי זה סוג של \u0003שבועה דכי קא משתבע\u0004 — \u0003בשקרא קא משתבע\u0004 \u0005[שכאשר הוא נשבע\u0006 — \u0005בשקר הוא נשבע],\u0006 \u0003אבל שבועת בטוי דאיכא למימר דבקושטא קא משתבע\u0004 \u0005[שיש מקום לומר\u0006 ש\u0005באמת נשבע],\u0006 אלא שאחר כך שכח, או חזר בו ועבר על שבועתו — \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 שנשבע \u0003\"אוכל\" ו\"לא אוכל\",\u0004 שנשבע שבועת ביטוי לעתיד, שבאלה ייתכן שבשעת השבועה לא שיקר, אבל אם נשבע \u0003\"אכלתי\" ו\"לא אכלתי\" מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי כאן בוודאי נשבע לשקר! ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003שבועת שוא\u0004"],["\u0003וכל דדמי ליה\u0004 \u0005[הדומה לו],\u0006 כל שבועה שכשנשבע — נשבע לשקר.","שנינו במשנה: \u0003היה אחד מהן משחק בקוביא\u0004 ומלוה בריבית — שכנגדו נשבע ונוטל. ושואלים: \u0003הא תו\u0004 \u0005[זה עוד]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003תנא פסולא דאורייתא וקתני פסולא דרבנן\u0004 \u0005[שנה פסול מן התורה ו\u0006גם \u0005שנה פסול\u0006 לשבועה \u0005מדברי סופרים]\u0006 לומר שגם במקרה זה שכנגדו יכול להישבע וליטול.","שנינו: \u0003היו שניהן חשודין\u0004 חזרה שבועה למקומה, דברי ר' יוסי. ר' מאיר אומר: יחלוקו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: היכי תנן\u0004 \u0005[כיצד שנינו]?\u0006 כלומר, מה אמר ר' מאיר ומה אמר ר' יוסי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא\u0004 \u0005[אינני יודע].\u0006 שאל אותו רבא: \u0003הלכתא מאי\u0004 \u0005[מה ההלכה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא\u0004 \u0005[אינני יודע].\u0006","ומעירים כי בענין זה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003אמר רב יוסף בר מניומי אמר רב נחמן, ר' יוסי אומר: יחלוקו. וכן תני\u0004 \u0005[שנה]\u0006 \u0003רב זביד בר אושעיא, ר' יוסי אומר: יחלוקו. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב זביד: אמר ר' אושעיא, ר' יוסי אומר: יחלוקו. אמר רב יוסף בר מניומי, עבד\u0004 \u0005[עשה]\u0006 \u0003רב נחמן עובדא\u0004 \u0005[מעשה]\u0006 ופסק ש\u0003יחלוקו.\u0004","שנינו במשנה: \u0003חזרה שבועה למקומה.\u0004 ושואלים: \u0003להיכן חזרה?\u0004 מה הוא מקומה? \u0003אמר ר' אמי, רבותינו שבבבל אמרו: חזרה שבועה לסיני\u0004 כלומר, השבועה חזרה למה שהשביע הקב\"ה את ישראל בהר סיני לקיים את המצוות, ומכוח שבועה זו, מי שגזל — ייפרע ממנו הקב\"ה, אבל בית דין אינו מתערב בדבר. \u0003רבותינו שבארץ ישראל אמרו: חזרה שבועה למחויב לה\u0004 כלומר, לנתבע, שהוא המחוייב להישבע מעיקר הדין, וכיון שהוא חשוד ואינו יכול להישבע — משלם.","\u0003אמר רב פפא: רבותינו שבבבל\u0004 הם \u0003רב ושמואל, רבותינו שבארץ ישראל\u0004 הוא \u0003ר' אבא.\u0004 ומפרטים: \u0003רבותינו שבבבל\u0004 שהם \u0003רב ושמואל, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003וכן היתומין לא יפרעו\u0004 בשטר חוב שקיבלו מאביהם \u0003אלא בשבועה. והוינן\u0004 \u0005[והיינו\u0006 עוסקים ומתקשים\u0005]\u0006 \u0003בה\u0004 בשאלה הזו: \u0003ממאן\u0004 \u0005[ממי]\u0006 לא ייפרעו אלא בשבועה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מלוה\u0004 שלוה מאביהם, \u0003אבוהון שקיל\u0004 \u0005[אביהם\u0006 היה \u0005נוטל\u0006 ממנו\u0005]\u0006 \u0003בלא שבועה\u0004 מכוח השטר, \u0003ואינהו\u0004 \u0005[והם]\u0006 היתומים, שהקלו חכמים בדינם בכל מקום, \u0003בשבועה? אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכן היתומין מן היתומין לא יפרעו אלא בשבועה. ו\u0004בענין זה","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא שנו\u0004 שהיתומים נוטלים בשבועה מיתומי הלווה, \u0003אלא\u0004 במקרה \u0003שמת\u0004 ה\u0003מלוה בחיי\u0004 ה\u0003לוה,\u0004 שמתחילה יכולים היו בני המלוה לגבות את השטר מן הלווה עצמו בלא שבועה, \u0003אבל מת לוה\u0004 עוד \u0003בחיי מלוה\u0004 — הרי \u0003כבר נתחייב מלוה לבני לוה שבועה,\u0004 שהרי אין נפרעים מן היתומים אלא בשבועה, \u0003ואין אדם מוריש שבועה לבניו,\u0004 והואיל ואינם יכולים להישבע — נשאר הממון במקומו. הרי שלדעת רב ושמואל, במקום שצריך אדם שבועה כדי להיפרע, ואינו יכול להישבע — נשאר המצב בעינו, והוא מה שנאמר שחזרה שבועה לסיני.","\u0003רבותינו שבארץ ישראל\u0004 שאמרו שחזרה השבועה למחוייב לה, הוא \u0003ר' אבא,\u0004 והראיה שזוהי שיטתו: \u0003דההוא גברא דחטף נסכא מחבריה\u0004 \u0005[שאדם אחד חטף חתיכת כסף מחבירו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אמי\u0004 לדין, \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אבא קמיה\u0004 \u0005[לפניו]\u0006 כתלמיד. \u0003אייתי חדא סהדא דמחטף חטפה מיניה\u0004 \u0005[הביא\u0006 התובע \u0005עד אחד ש\u0006הלה \u0005חטף\u0006 את הכסף \u0005ממנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 הנתבע לדיינים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003חטפי, ודידי חטפי\u0004 \u0005[חטפתי, ו\u0006אולם את \u0005שלי חטפתי],\u0006 שכסף זה שלי הוא.","\u0003אמר ר' אמי: היכי לדיינו דייני להאי דינא\u0004 \u0005[איך ידונו הדיינים את הדין הזה]?\u0006 שיש פה בעיה חמורה, \u0003נימא ליה\u0004 \u0005[\u0006אם \u0005נאמר לו\u0006 לחוטף\u0005]:\u0006 \u0003זיל שלים\u0004 \u0005[לך שלם]\u0006 — \u0003ליכא תרי סהדי\u0004 \u0005[אין שני עדים]\u0006 שגזל! \u0003נפטריה\u0004 \u0005[נפטור אותו]\u0006 לגמרי — הלוא \u0003איכא חד סהדא\u0004 \u0005[יש עד אחד]\u0006 שחטף! \u0003נימא ליה\u0004 \u0005[\u0006אם \u0005נאמר לו]:\u0006 \u0003זיל אישתבע\u0004 \u0005[לך הישבע]\u0006 שלא חטפת — \u0003כיון דאמר מיחטף חטפי\u0004 \u0005[שהוא אומר חטפתי],\u0006 \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003כגזלן\u0004 ואינו יכול להישבע!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא: הוה\u0004 \u0005[הריהו]\u0006 אם כן \u0003מחויב שבועה ואין יכול לישבע, ו\u0004כלל הוא: \u0003כל המחויב שבועה ואינו יכול לישבע משלם.\u0004 הרי שר' אבא סבור שהשבועה חוזרת למחוייב לה, וכיון שאינו יכול להישבע — משלם.","\u0003אמר רבא: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' אבא מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' אמי\u0004 ברייתא זו על הכתוב: \u0003\"שבעת ה' תהיה בין שניהם\"\u0004 (שמות כב, י), בין בעלי הדין עצמם — \u0003ולא בין היורשין.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006","\u0003אילימא דאמר ליה\u0004 \u0005[אם תאמר שאמר לו]\u0006 היורש התובע: \u0003מנה לאבא ביד אביך,\u0004 שאביך היה חייב לאבי מאה דינר, ועליך אם כן להחזיר לי אותם, \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003חמשין אית ליה, וחמשין לית ליה\u0004 \u0005[חמישים יש לו\u0006 היה חייב לו, \u0005וחמישים אין לו\u0006 לא היה חייב לו\u0005],\u0006 במקרה זה שהוא טוען טענה וודאית, \u0003מה לי הוא ומה לי אבוהא\u0004 \u0005[אביו]?\u0006 הרי שניהם מודים במקצת הטענה, ובמקצתה כופרים בוודאות, ומדוע לא יישבע?","\u0003אלא לאו דאמר ליה\u0004 \u0005[האם לא שאומר לו]\u0006 התובע: \u0003מנה לאבא ביד אביך, אמר ליה\u0004 \u0005[לו]\u0006 הנתבע: \u0003חמשין ידענא, וחמשין לא ידענא\u0004 \u0005[חמישים אני יודע, וחמישים איני יודע];\u0006"],["ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003אביו כי האי גוונא מיחייב\u0004 \u0005[במקרה כגון זה\u0006 שאומר: חמישים איני יודע, \u0005היה חייב]\u0006 שבועה, ומשום שאינו יכול להישבע, שהרי אינו יודע, היה משלם, \u0003איצטריך קרא למיפטר גבי\u0004 \u0005[הוצרך המקרא לפטור\u0006 במקרה \u0005של]\u0006 \u0003יורשין, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003אביו כי האי גוונא נמי\u0004 \u0005[במקרה כגון זה גם כן]\u0006 \u0003פטור, קרא גבי\u0004 \u0005[מקרא\u0006 מפורש \u0005אצל]\u0006 \u0003יורשין\u0004 לפוטרם משבועה \u0003למה לי?\u0004 ומכאן מוכח ששבועה חוזרת למחוייב לה, ומתוך שאינו יכול להישבע — משלם.","ושואלים: \u0003ורב ושמואל, האי\u0004 \u0005[פסוק זה]\u0006 \u0003\"שבעת ה' \" מאי קא דרשי ביה\u0004 \u0005[מה הם דורשים בו]?\u0006 שהרי לשיטתם אין הבדל בזה בין היורשים לשאר אדם!","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריכים\u0006 אנו \u0005אותו לכמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003שמעון בן טרפון אומר: \"שבעת ה' תהיה בין שניהם\"\u0004 (שמות כב, ד) — \u0003מלמד שהשבועה חלה על שניהם,\u0004 שאם היתה שבועת שקר העונש על שבועה זו חל על שניהם, על הנשבע ועל המשביע. כיון שהוזכר אחד מדבריו של חכם זה מביאים עוד דברים שאמר.","\u0003שמעון בן טרפון אומר: אזהרה לעוקב אחר נואף מנין?\u0004 כלומר, היכן נאמר בתורה שיש איסור לסייע לנואף במעשיו? \u0003תלמוד לומר: \"לא תנאף\"\u0004 (שמות כ, יג), שאנו קוראים בו: \u0003לא תנאיף,\u0004 אל תגרום לאחרים לנאוף.","וכן לגבי חטא המרגלים שנאמר: \u0003\"ותרגנו באהליכם\"\u0004 (דברים א, כז) — \u0003שמעון בן טרפון אומר\u0004 בפירושה של מלה מיוחדת זו: \u0003תרתם\u0004 את הארץ, \u0003וגיניתם\u0004 אותה \u0003באהלו של מקום.\u0004","ועל הפסוק \u0003\"עד הנהר הגדול נהר פרת\"\u0004 (שמות כ, ז) — \u0003שמעון בן טרפון אומר:\u0004 אף שנהר פרת אינו הגדול בנהרות, הרי זה כדרך הפתגם העממי: \u0003קרב לגבי דהינא ואידהן\u0004 \u0005[התקרב אל המשוח בשמן ותשומן\u0006 גם אתה ממנו\u0005],\u0006 שמפני שהנהר סמוך לארץ ישראל קוראים לו משום כבודה \"הנהר הגדול\". \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנו]\u0006 על כך בלשון אחרת: \u0003עבד מלך כמלך.\u0004","שנינו במשנה: \u0003והחנוני על פינקסו,\u0004 שאם אמר לחנווני לתת לפועלים מעות, והחנווני אומר שנתן והפועלים אומרים שלא נטלו — החנווני והפועלים נשבעים שניהם ובעל הבית משלם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: טורח שבועה זו למה?\u0004 מדוע צריכים שניהם להישבע? שיישבע צד אחד והאחר ישלם! \u0003אמר לו ר' חייא, תנינא\u0004 \u0005[שנינו]:\u0006 \u0003שניהם נשבעין ונוטלין מבעל הבית,\u0004 ולכן צריכים להישבע, כדי להפיס דעתו, שאין מרמים אותו.","ושואלים: האם \u0003קיבלה מיניה\u0004 \u0005[קיבל ממנו]\u0006 רבי מר' חייא הלכה זו, ששניהם נשבעים לבעל הבית, \u0003או לא קיבלה מיניה\u0004 \u0005[קיבל אותה ממנו]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: פועלין נשבעין לחנוני. ואם איתא\u0004 \u0005[יש],\u0006 אם אכן קיבל את הדברים, נשבעים \u0003לבעל הבית מיבעי ליה\u0004 \u0005[צריך הוא\u0006 לומר\u0005].\u0006 ומכאן שלא קיבל ממנו.","\u0003אמר רבא:\u0004 צריך להבין כך את דברי רבי: \u0003פועלים נשבעין לבעל הבית במעמד חנוני, כי היכי דליכספו מיניה\u0004 \u0005[כדי שיתביישו ממנו]\u0006 מן החנווני אם הם משקרים, שהרי הוא יודע ורואה אותם בשיקרם.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 בנושא דומה, אם היו \u0003שתי כיתי עדים המכחישות זו את זו\u0004 בעדות, שברור הוא שאחת מהן משקרת, מה יהא דין העדים בעדויות האחרות? \u0003אמר רב הונא:\u0004 כת \u0003זו באה בפני עצמה ומעידה, ו\u0004כת \u0003זו באה בפני עצמה ומעידה,\u0004 שהרי לא הוכח על אף אחת מהם שהיא כת שקרנים. \u0003רב חסדא אמר: בהדי סהדי שקרי\u0004 \u0005[עם עדים שקרנים]\u0006 \u0003למה לי?\u0004 ולכן צריך לפסול את כולם, מפני שכולם חשודים על השקר. ומביאים מקרים שונים הנוגעים לשאלה זו.","אם לאחר שהכחישו אלו את אלו, הלכו והעידו על \u0003שני מלוין ושני לווין ושני שטרות,\u0004 שכת עדים חתומה על שטר אחד, ואחרת על שטר אחר — \u0003היינו פלוגתייהו\u0004 \u0005[זו המחלוקת שלהם],\u0006 שלרב הונא שני השטרות כשרים, שזו מעידה בפני עצמה וזו בפני עצמה, ולרב חסדא שניהם פסולים. אם היו שתי הכתות מעידות על \u0003מלוה ולוה\u0004 אחד \u0003ושני שטרות,\u0004 שכל אחד מהם חתום על ידי כת אחת מאלה — \u0003יד בעל השטר על התחתונה,\u0004 שוודאי שטר אחד מהם פסול, ויכול המלוה לגבות רק את השטר שהסכום שבו קטן יותר.","היו \u0003שני מלוין ולוה אחד ושני שטרות\u0004 — \u0003היינו מתניתין\u0004 \u0005[זו משנתנו],\u0006 שיש שני תובעים המכחישים זה את דברי זה, ושניהם באים לגבות מאדם אחד, ששניהם גובים ממנו, לפי שאינך יכול לפסול שטרו של אף אחד מן התובעים מספק. היו \u0003שני לווין ומלוה אחד ושני שטרות מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם יכול כל אחד מן הלווים לומר: השטר שאתה מוציא עלי נחתם על ידי הכת המשקרת ופסול הוא, או שמא כל לווה צריך להוכיח שהשטר הנוגע לו חתום על ידי עדים פסולים? ומשיבים: שאלה זו לא נפתרה ונשארת ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר יהודה\u0004 ממה ששנינו בענין עדות החודש:"],["עד \u0003אחד אומר:\u0004 היה ירח \u0003גבוה\u0004 לפי מראית העין כמו \u0003שתי מרדעות\u0004 (מקל שמכוונים בו את הבהמות), \u0003ואחד אומר: שלש\u0004 מרדעות — \u0003עדותן קיימת,\u0004 שבכגון זה אנשים טועים. \u0003אחד אומר: שלש, ואחד אומר: חמש\u0004 — \u0003עדותן בטלה; ו\u0004אף על פי ששני עדים אלה מכחישים זה את זה, בכל זאת \u0003מצטרפין לעדות אחרת.\u0004","ושואלים: \u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שכל אחד מהם מצטרף עם עד נוסף \u0003לעדות ממון,\u0004 אף שכל אחד מהם חשוד כמשקר? וקשה לדברי רב חסדא! \u0003אמר רבא:\u0004 לא, כך צריך לפרש: \u0003הוא ואחר מצטרפין לעדות אחרת של ראש חדש,\u0004 שאם יבוא עד נוסף ויאמר כדברי אחד מהם, הריהו מצטרף עמו לעדות. וטעמו של דבר: \u0003דהוי להו תרי וחד\u0004 \u0005[שהרי הם\u0006 עכשיו \u0005שנים\u0006 כנגד \u0005אחד],\u0006 \u0003ואין דבריו של אחד במקום שנים,\u0004 והוא זה שטעה או שיקר.","שנינו במשנה: \u0003אמר לחנוני \"תן לי בדינר פירות\",\u0004 ונתן לו, ואחר כך היו הצדדים מתווכחים אם שילם בעל הבית לחנווני — בעל הבית נשבע שנתן לו את הדינר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: אימתי\u0004 נשבע בעל הבית? \u0003בזמן שהפירות צבורין ומונחין ושניהן עוררין עליהן, אבל\u0004 אם \u0003הפשילן\u0004 את הפירות הללו \u0003בקופתו\u0004 (בסלו) \u0003לאחוריו\u0004 — \u0003המוציא מחברו עליו הראיה,\u0004 שהרי הם עתה ברשות בעל הבית, וצריך החנווני להביא ראיה לתביעתו.","שנינו מעין זה במשנה: \u0003אמר לשולחני \"תן לי\u0004 בדינר מעות\", ונתן לו מעות, וכאשר מתווכחים השולחני ובעל הבית האם נתן לשולחני את הדינר — צריך בעל הבית להישבע שנתן לו את הדינר. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 גם דבר זה להיאמר, אף שהוא לכאורה ממש כמו המקרה בחנווני, \u0003אי אשמעינן הא קמייתא\u0004 \u0005[\u0006ש\u0005אילו היה משמיע לנו\u0006 רק את \u0005זו הראשונה\u0006 בחנווני\u0005],\u0006 היינו אומרים: \u0003בהך קא אמרי רבנן\u0004 \u0005[בזה אומרים חכמים]\u0006 שבעל הבית צריך להישבע ששילם כדי להיפטר מתשלום, \u0003משום דפירי עבידי דמרקבי\u0004 \u0005[שפירות עשויים להירקב],\u0006 \u0003וכיון דמרקבי\u0004 \u0005[ש\u0006הם \u0005נרקבים]\u0006 \u0003לא משהו ליה\u0004 \u0005[משהים אותם],\u0006 וממהר החנווני לתתם לקונה גם אם לא קיבל את הכסף, \u0003אבל מעות דלא מרקבי\u0004 \u0005[שאינם נרקבות]\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודים לו]\u0006 \u0003לר' יהודה,\u0004 שאין השולחני נותן דבר אלא אם כן קיבל כספו תחילה, ואין מקום להשביע את בעל הבית.","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו]\u0006 בשולחני, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דווקא \u0005אמר]\u0006 \u0003ר' יהודה\u0004 שאין בעל הבית צריך להישבע, \u0003אבל בהך אימא מודה להו לרבנן\u0004 \u0005[בההיא\u0006 בחנוני \u0005אמור\u0006 ש\u0005מודה להם לחכמים],\u0006 על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת להיאמר בשני המקרים.","שנינו במשנה \u0003כשם שאמרו: הפוגמת כתובתה\u0004 לא תיפרע אלא בשבועה \u0003וכן היתומין לא יפרעו\u0004 בשטר חוב שקיבלו מאביהם אלא בשבועה. ושואלים: לא יפרעו \u0003ממאן\u0004 \u0005[ממי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מלוה\u0004 עצמו, יש לתמוה: \u0003אבוהון שקיל\u0004 \u0005[אביהם היה נוטל]\u0006 בשטר \u0003בלא שבועה ואינהו\u0004 \u0005[והם]\u0006 \u0003בשבועה?\u0004 וכי מפני שהם יתומים צריכים להישבע? אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכן היתומים\u0004 הבאים להיפרע חוב אביהם \u0003מן היתומים\u0004 של הלווה, \u0003לא יפרעו אלא בשבועה.\u0004","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא שנו\u0004 הלכה זו שנשבעים היתומים ונוטלים, \u0003אלא שמת\u0004 ה\u0003מלוה\u0004 עוד \u0003בחיי לוה, אבל\u0004 אם \u0003מת לוה בחיי מלוה\u0004 — \u0003כבר נתחייב מלוה לבני לוה שבועה,\u0004 שהרי אינו יכול להיפרע מיתומים בלא שבועה שלא נפרע כבר שטר זה, \u0003ואין אדם מוריש\u0004 ממון שיש בו \u0003שבועה לבניו,\u0004 שהרי אינם יכולים להישבע כמו שהיה אביהם נשבע (שאין שטר זה פרוע), ומתוך שאינם יכולים להישבע — אין להם זכות בממון זה.","\u0003שלחוה\u0004 לבעיה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אלעזר\u0004 בארץ ישראל: \u0003שבועה זו מה טיבה?\u0004 מה תוקפה של השבועה ליתומים, עד שמפקיעה את ממונם של בני המלוה? \u0003שלח להו\u0004 \u0005[להם]:\u0006 באמת אין הלכה כך, אלא \u0003יורשין נשבעין שבועת יורשין,\u0004 שאינם יודעים מאביהם ולא באופן אחר שהשטר פרוע, \u0003ונוטלין\u0004 מיתומי הלווה. \u0003שלחוה\u0004 את השאלה הזו לארץ ישראל שוב \u0003בימי ר' אמי, אמר: כולי האי שלחי לה ואזלי\u0004 \u0005[כל כך שולחים אותה והולכים]?\u0006 \u0003אי אשכחינן בה טעמא\u0004 \u0005[אם היינו מוצאים בה טעם\u0006 אחר\u0005],\u0006 \u0003מי לא שלחינן להו\u0004 \u0005[האם לא היינו שולחים להם]?\u0006 \u0003אלא אמר ר' אמי, הואיל ואתא לידן, נימא בה מילתא\u0004 \u0005[הואיל ובא הדבר לידינו, נאמר בו דבר\u0006 של חידוש\u0005]:\u0006 דווקא אם","\u0003עמד\u0004 אביהם המלוה \u0003בדין\u0004 כדי לגבות את השטר \u0003ומת\u0004 — \u0003כבר נתחייב מלוה לבני\u0004 ה\u0003לוה שבועה\u0004 על ידי פסיקת בית דין, \u0003ואין אדם מוריש שבועה לבניו,\u0004 כדברי רב ושמואל. אבל אם האב \u0003לא עמד בדין, ומת,\u0004 ולא נתחייב בשבועה — ה\u0003יורשין נשבעין שבועת יורשין ונוטלין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: אטו בי דינא קא מחייבי ליה\u0004 \u0005[וכי בית הדין הם המחייבים אותו]\u0006 \u0003שבועה?\u0004 הלוא \u0003מעידנא דשכיב לוה איחייב ליה\u0004 \u0005[מזמן שמת הלווה התחייב לו]\u0006 ה\u0003מלוה לבני\u0004 ה\u0003לוה שבועה\u0004 אם הוא רוצה לגבות מהם, ואין הדבר תלוי בפסיקת בית הדין!","\u0003אלא אמר רב נחמן: אי איתא\u0004 \u0005[אם יש\u0006 מקום\u0005]\u0006 לקבל את מה שאמרו \u0003רב ושמואל\u0004 — \u0003איתא\u0004 \u0005[יש]\u0006 לקבלם, \u0003אי ליתא\u0004 \u0005[אם אין]\u0006 — \u0003ליתא\u0004 \u0005[אין],\u0006 אבל אין לעשות פשרה בדבר כמו שעשה ר' אמי. ושואלים: \u0003אלמא מספקא ליה\u0004 \u0005[מכאן שמסופק בעיניו]\u0006 של רב נחמן האם הלכה כרב ושמואל, שפסקו שכאשר אין אפשרות להישבע הממון נשאר בחזקתו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף בר מניומי: עבד\u0004 \u0005[עשה]\u0006 \u0003רב נחמן עובדא\u0004 \u0005[מעשה]\u0006 ופסק כי במקום ששני הצדדים חשודים על השבועה \u0003יחלוקו!\u0004 הרי שלמעשה פסק שלא כמותם! ומשיבים: מה שאמר רב נחמן אם יש או אין לדברי רב ושמואל — \u0003לדבריו\u0004 לשיטתו של \u0003ר' מאיר\u0004 במשנה, שחזרה שבועה למקומה, \u0003קאמר\u0004 \u0005[אמר],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[והוא עצמו לא סבר כן],\u0006 אלא כר' יוסי האומר יחלוקו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא\u0004 ממה ששנינו במסכת כתובות: אם \u0003מתה\u0004 האשה האלמנה בלא שתגבה כתובתה מנכסי בעלה שמת — \u0003יורשיה מזכירין\u0004 ותובעים \u0003את כתובתה עד עשרים וחמש שנים\u0004 מזמן מות הבעל. משמע שהם יכולים לתבוע ולגבות (בשבועה), למרות שהם יתומים הגובים מן היתומים, שלא כדברי רב ושמואל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003שנשבעה\u0004 כבר האשה שלא נפרעה \u0003ומתה,\u0004 ואחר כך היורשים באים לתבוע את הכתובה בפועל. ואין עליהם חובת שבועה — שהרי כבר נשבעה האלמנה שבועה זו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003נשא\u0004 אשה \u0003ראשונה ומתה,\u0004 ולפי תנאי הכתובה בניה יורשים את הבעל לאחר מותו בדמי כתובתה, \u0003נשא שניה ומת הוא\u0004 — אשה \u0003שניה ויורשיה קודמין ליורשי הראשונה,\u0004 כדרך בעלי חוב שגובים מן היורשים. הרי שיורשי האלמנה יכולים לגבות בשבועה מיורשי האשה הראשונה, יתומים מן היתומים, שלא כדברי רב ושמואל, שהם אומרים שאינה יכולה להוריש שבועה! ומשיבים: \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003שנשבעה ומתה.\u0004","ועוד מציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: מי שהתנה עם אשתו שתוכל לגבות את כתובתה ולא תצטרך להישבע, הוא אינו יכול להשביע אותה, \u0003אבל יורשיו משביעין אותה ואת יורשיה ואת הבאין ברשותה.\u0004 הרי שיורשים נשבעים ליורשים, וכאן ברור שאשה זו לא נשבעה!","\u0003אמר רב שמעיה: לצדדין\u0004 באופנים שונים \u0003קתני\u0004 \u0005[שנה]\u0006 משנה זו, מה שאמרנו שמשביעים \u0003אותה\u0004 — הרי זה \u0003באלמנה, ו\u0004מה שנאמר שמשביעים את \u0003יורשיה\u0004 — הרי זה \u0003בגרושה,\u0004 שגירשה בעלה ומתה, ואחריה מת הוא. שהרי זה כמקרה שמת מלוה בחיי לווה, שעדיין לא נתחייב המלוה (האשה) ולא יורשיו (בניה) שבועה כדי להיפרע מן הנכסים, ורק משמת הבעל מתחייבים יורשיה של האשה שבועה זו, ככל הנפרעים מנכסי יתומים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב נתן בר הושעיא\u0004 ממה ששנינו: פעמים ש\u0003יפה כח הבן מכח האב,\u0004 כיצד?"],["\u0003שהבן גובה בין בשבועה ובין שלא בשבועה, והאב אינו גובה אלא בשבועה.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 בהכרח צריך לומר ש\u0003מת לוה בחיי\u0004 ה\u0003מלוה,\u0004 שרק מפני שמת הלווה אין האב (המלוה) יכול לגבות מן היתומים אלא בשבועה,","\u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003שהבן גובה בין בשבועה ובין שלא בשבועה, בשבועה\u0004 — כוונתו \u0003שבועת יורשין\u0004 שהרי אינו יכול להישבע אלא שבועה זו, \u0003שלא בשבועה\u0004 — \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל,\u0004 במשנתנו, שאם היו עדים שאמר האב המלווה בשעת מותו שאין שטר זה פרוע — סומכים על כך, וגובה היורש שלא בשבועה. ומכל מקום רואים מכאן שהאב מוריש שבועה לבניו, שלא כדברי רב ושמואל!","\u0003אמר רב יוסף: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[נחשב],\u0006 וכיון שדנים את השטר כאילו היה ממון ממש, הרי אין חסרון השבועה מעכב בגבייתו.","ובפסיקת ההלכה בענין זה, מסופר \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רב נחמן\u0004 פעם \u0003ל\u0004עיר \u0003סורא, עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב חסדא ורבה בר\u0004 \u0005[בן]\u0006 \u0003רב הונא, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליתי מר נעקרא להא\u0004 \u0005[שיבוא אדוני ונעקור את\u0006 הפסק \u0005הזה]\u0006 שפסקו \u0003רב ושמואל,\u0004 שקשה לקבל את סברתם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכפלי ואתאי כל הני פרסי למעקרא להא\u0004 \u0005[וכי טרחתי ובאתי כל אותן פרסות\u0006 ממקומי עד לכאן כדי \u0005לעקור את זו]\u0006 שאמרו \u0003רב ושמואל? אלא\u0004 נעשה אחרת, \u0003הבו דלא לוסיף עלה\u0004 \u0005[תנו שלא להוסיף עליה],\u0006 להשתמש בה במקרים אחרים, אלא תישאר כהלכה לעצמה. ומסבירים: \u0003כגון מאי\u0004 \u0005[מה]\u0006 ש\u0003אמר רב פפא:\u0004 בעל חוב \u0003הפוגם את שטרו\u0004 שמודה שכבר קיבל מקצתו, והוא חייב שבועה, \u0003ומת\u0004 — \u0003יורשין נשבעין שבועת יורשין ונוטלין\u0004 מן הלווה.","ומביאים מקרה נוסף, \u0003ההוא דשכיב ושבק ערבא\u0004 \u0005[אדם אחד,\u0006 לווה, \u0005מת והניח ערב],\u0006 ורצו יתומי המלוה לגבות חובם מן הערב, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב פפא למימר\u0004 \u0005[לומר]:\u0006 \u0003הא נמי דלא לוסיף עלה\u0004 \u0005[זה גם כן\u0006 מאותם הדברים \u0005שלא להוסיף עליה]\u0006 \u0003הוא,\u0004 שרב ושמואל פסקו כן ביתומים בלבד, שאין יתומים נפרעים מהם, ולא במי שנפרע מן הערב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אטו ערבא לאו בתר יתמי אזיל\u0004 \u0005[וכי הערב לא אחר היתומים הולך]?\u0006 הרי לאחר מכן יבוא לגבות את מה ששילם מרכוש היתומים, ואם כן, בסופו של דבר הרי זה דין של יתומי הלווה.","ועוד מסופר, \u0003ההוא דשכיב ושבק אחא\u0004 \u0005[אדם אחד שמת והניח אח\u0006 שירשו\u0005],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]:\u0006 \u0003הא נמי דלא לוסיף עלה\u0004 \u0005[זה גם כן\u0006 מאותם הדברים \u0005שלא להוסיף עליה]\u0006 \u0003הוא,\u0004 ויכול לגבות מיורשי הלווה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מה לי\u0004 מה ההבדל אם נשבע היורש \u0003\"שלא פקדני אבא\", ומה לי\u0004 אם הוא אומר \u0003\"שלא פקדני אחי\",\u0004 כיון שהוא יורש — הרי דינו כדין יתום, ואינו יורש שבועה.","\u0003אמר רב חמא: השתא דלא איתמר הלכתא\u0004 \u0005[עכשיו שלא נאמרה\u0006 ונקבעה \u0005הלכה]\u0006 \u0003לא כרב ושמואל ולא כר' אלעזר, האי דיינא דעבד\u0004 \u0005[דיין זה שעושה]\u0006 \u0003כ\u0004דעת \u0003רב ושמואל\u0004 — \u0003עבד\u0004 \u0005[עשה],\u0006 \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003כר' אלעזר\u0004 — \u0003עבד\u0004 \u0005[עשה].\u0006","\u0003אמר רב פפא: האי שטרא דיתמי\u0004 \u0005[שטר זה של יתומים]\u0006 שבא לפנינו, \u0003לא מקרע קרעינן ליה ולא אגבויי מגבינן ביה\u0004 \u0005[אין אנו קורעים אותו, ו\u0006מצד אחר \u0005לא גובים בו].\u0006 \u0003אגבויי לא מגבינן ביה\u0004 \u0005[לגבות אין גובים בו]\u0006 — \u0003דלמא סבירא לן\u0004 \u0005[שמא אנו סבורים]\u0006 \u0003כרב ושמואל\u0004 שאין יתומים גובים, שהרי אינם יכולים להישבע. \u0003ומקרע לא קרעינן ליה\u0004 \u0005[ואין אנו קורעים אותו]\u0006 — \u0003דהאי דיינא דעבד\u0004 \u0005[ש\u0006הרי \u0005אותו דיין שעשה]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר\u0004 — \u0003עבד\u0004 \u0005[עשה].\u0006","מסופר, \u0003ההוא דיינא דעבד\u0004 \u0005[דיין אחד שעשה]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר, הוה צורבא מרבנן במתיה\u0004 \u0005[היה תלמיד חכם בעירו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו תלמיד חכם: \u0003אייתינה איגרתא ממערבא דלית הלכתא\u0004 \u0005[אביא מכתב\u0006 מארץ ישראל \u0005שאין הלכה]\u0006 \u0003כר' אלעזר! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכי תייתי\u0004 \u0005[כאשר תביא],\u0006 ובינתיים אני עומד על פסקי. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רב חמא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האי דיינא דעבד\u0004 \u0005[אותו דיין שעשה]\u0006 \u0003כר' אלעזר\u0004 — \u0003עבד\u0004 \u0005[עשה],\u0006 ואי אפשר לבטל את מעשיו.","שנינו במשנה: \u0003ואלו נשבעין\u0004 שלא כטענה השותפים והאריסים וכו'. ותוהים: \u0003אטו\u0004 \u0003בשופטני עסקינן\u0004 \u0005[וכי בשוטים עוסקים אנו],\u0006 שיבואו להישבע גם כאשר אין טוענים כנגדם כלום? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003ואלו נשבעין שלא בטענת ברי, אלא\u0004 אפילו \u0003בטענת שמא,\u0004 שאם טוענים כנגדם: אנו חושדים שמא לקחתם דבר שלא כדין — נשבעים. והם: \u0003השותפין והאריסין\u0004 ושאר המנויים במשנה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003בן בית שאמרו\u0004 שצריך להישבע, \u0003לא\u0004 באדם \u0003שנכנס ויוצא ברגליו\u0004 לאותו בית כידיד המשפחה, שוודאי אין משביעים אותו, \u0003אלא\u0004 מדובר בבן בית כזה ש\u0003מכניס לו פועלין ומוציא לו פועלין, מכניס לו פירות ומוציא לו פירות,\u0004 שמנהל מקצת מעסקיו.","ושואלים: \u0003ומאי שנא הני\u0004 \u0005[ובמה שונים אלה]\u0006 השותפים, האריסין ובן בית, שניתן להשביעם? ומשיבים: \u0003משום דמורו בה התירא\u0004 \u0005[שמורים בה היתר\u0006 לעצמם\u0005]\u0006 לקחת משהו מן הנכסים, בגלל טרחתם.","וביחס לשבועה זו, \u0003אמר רב יוסף בר מניומי אמר רב נחמן: והוא שיש טענה בינייהו\u0004 \u0005[ביניהם]\u0006 בשווי \u0003שתי כסף,\u0004 אז יכול התובע להשביעו.","ותוהים: \u0003כמאן\u0004 \u0005[כמי]\u0006 הוא פוסק בדיני טענה? \u0003כשמואל,\u0004 שאמר בדין שבועת המודה במקצת שדי שהטענה עצמה שתי כסף כדי לחייב את המודה במקצת להישבע? \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 ברייתא \u0003לסיועיה\u0004 \u0005[\u0006שיש בה \u0005לסייע]\u0006 \u0003ל\u0004דברי \u0003רב,\u0004 שרק כאשר הכפירה של הנתבע היא בשווי שתי כסף צריך להישבע! אלא \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן: צריך שתהא ביניהם \u0003כפירת טענה\u0004 של שתי כסף כדי לחייב שבועה, \u0003כ\u0004דברי \u0003רב.\u0004","שנינו במשנה: \u0003חלקו השותפין והאריסין\u0004 אין יכולים עוד להשביעם בטענות ספק. אבל אם נתחייבו שבועה מצד אחר, מגלגלים עליהם גם שבועה זו יחד עמה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003מהו לגלגל\u0004 שבועה \u0003בדרבנן\u0004 \u0005[בדברי סופרים]?\u0006 כלומר, אם חובת שבועה ראשונה היתה רק מדברי סופרים, האם אפשר לגלגל תביעות גם על סמך שבועה זו, או דווקא כאשר השבועה שמתחייבים בה היא שבועה שמן התורה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003לוה הימנו ערב שביעית\u0004 (שנת השמיטה), \u0003ולמוצאי שביעית נעשה לו שותף או אריס\u0004 — \u0003אין מגלגלין\u0004 עליו שבועה. שאף שנשבע לו שבועת השותפים, אינו יכול לגלגל עליו שבועה על ההלוואה שלווה קודם לכן, משום שהחוב כבר נשמט. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003לוה הימנו ערב שביעית, דאתיא\u0004 \u0005[שבאה]\u0006 שנת ה\u0003שביעית אפקעתיה\u0004 \u0005[והפקיעה אותו]\u0006 את החוב, וממילא גם את השבועה שעליו, הדין כן. \u0003הא\u0004 \u0005[אבל]\u0006 ב\u0003שאר שני שבוע\u0004 (השמיטה) \u0003מגלגלין\u0004 עליו שבועה, אף על פי ששבועת האריס היא רק מדברי סופרים!","ודוחים: \u0003לא תימא\u0004 \u0005[תאמר\u0006 ותדייק\u0005]:\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 ב\u0003שאר שני שבוע\u0004 — \u0003מגלגלין, אלא אימא\u0004 \u0005[אמור]\u0006 ודייק כך: אם \u0003נעשה לו שותף או אריס ערב שביעית, ולמוצאי שביעית לוה הימנו\u0004 ונתחייב לו שבועה מן התורה — \u0003מגלגלין.\u0004","ותוהים: דבר זה אינו צריך לדיוק, \u0003הא בהדיא קתני לה\u0004 \u0005[הרי במפורש שנה אותה]:\u0006 \u0003נעשה לו שותף או אריס ערב שביעית, ולמוצאי שביעית לוה הימנו\u0004 — \u0003מגלגלין!\u0004 אלא יש לדייק כמו שאמרנו קודם, \u0003שמע מינה\u0004 \u0005[\u0006ו\u0005למד מכאן]\u0006 ש\u0003מגלגלין בדרבנן\u0004 \u0005[ב\u0006שבועה שמ \u0005דברי סופרים].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רב הונא:\u0004"],["\u0003לכל\u0004 כלומר, על ידי כל שבועה מדברי סופרים \u0003מגלגלין\u0004 על הנשבע כל שבועה אחרת, \u0003חוץ משכיר שאין מגלגלין\u0004 שבועה, משום שעיקר שבועתו אינה אלא מפני תקנה. \u0003רב חסדא אמר: לכל\u0004 המחוייב שבועה \u0003אין מקילין,\u0004 אלא מגלגלים עליהם שבועה, \u0003חוץ משכיר\u0004 ש\u0003מקילין\u0004 עליו. ושואלים: כיון שמסקנת דבריהם היא אותה מסקנה, \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין רב הונא ורב חסדא? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]:\u0006 \u0003לפתוח לו\u0004 אם לא דרש התובע שיגלגלו שבועה, האם יציעו לו בית דין לגלגל או לא?","שנינו במשנה: \u0003והשביעית משמטת\u0004 לא רק את החוב אלא גם את השבועה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב גידל אמר רב,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וזה דבר השמטה\"\u0004 (דברים טו, ב), לומר: \u0003ואפילו דיבור משמטת\u0004 כלומר, אפילו דיבור כגון שבועה, גם כן משמטת השמיטה.","","\u0003ארבעה\u0004 סוגי \u0003שומרין הן: שומר חנם והשואל, נושא שכר\u0004 (שומר בשכר) \u0003והשוכר.\u0004 וכללם: \u0003שומר חנם\u0004 — \u0003נשבע על הכל,\u0004 שנשבע על שלא פשע, ונפטר בשבועה זו מכל האשמות (נגנב, אבד וכו'). \u0003והשואל\u0004 — \u0003משלם את הכל,\u0004 שבכל מקרה צריך להחזיר מה ששאל, בין בגניבה ובין באונס. \u0003נושא שכר והשוכר\u0004 — \u0003נשבעין\u0004 כאשר הם טוענים שאירע לדבר אונס \u0003על השבורה\u0004 או \u0003על השבויה ועל המתה\u0004 ונפטרים, \u0003ומשלמין את האבדה ואת הגניבה.\u0004","","","ופרטי הדינים. \u0003אמר לשומר חנם: \"היכן שורי\"? אמר לו\u0004 השומר: \u0003\"מת\", ו\u0004מה שבאמת היה \u0003הוא\u0004 \u0003שנשבר או נשבה או נגנב או אבד.\u0004 או אמר לו השומר: \u0003\"נשבר\", והוא שמת או נשבה או נגנב או אבד.\u0004 או אמר לו: \u0003\"נשבה\", והוא שמת או נשבר או נגנב או אבד.\u0004 או אמר לו: \u0003\"נגנב\", והוא שמת או נשבר או נשבה או אבד.\u0004 או אמר לו: \u0003\"אבד\", והוא שמת או נשבר או נשבה או נגנב.\u0004 על כל אלה, אם אמר לו בעל השור: \u0003\"משביעך אני\" ואמר: \"אמן\"\u0004 למרות שנשבע לשקר, בכל זאת \u0003פטור\u0004 מקרבן אשם על השבועה, משום שבכל אחד מן המקרים הללו לא נפטר מחיוב תשלום על ידי שבועתו. וכן אם אמר לו לשומר חינם: \u0003\"היכן שורי\"?\u0004 ו\u0003אמר לו\u0004 השומר: \u0003\"איני יודע מה אתה סח\", והוא שמת או נשבר או נשבה או נגנב או אבד,\u0004 ואמר לו: \u0003\"משביעך אני\" ואמר\u0004 השומר \u0003\"אמן\"\u0004 — \u0003פטור,\u0004 שהרי אינו חייב לשלם באף אחד מן המקרים הללו. אמר לו: \u0003\"היכן שורי\"? אמר לו \"אבד\". \"משביעך אני\", ואמר\u0004 השומר: \u0003\"אמן\", והעדים מעידים אותו\u0004 \u0003שאכלו\u0004 — הרי זה \u0003משלם\u0004 למפקיד \u0003את הקרן,\u0004 את מחיר השור, שהרי נטלו לעצמו. אבל אם \u0003הודה מעצמו\u0004 לאחר שנשבע, ששיקר, בלא עדים — \u0003משלם\u0004 כמו כל מי שנשבע שבועת הפקדון לשקר, \u0003קרן וחומש\u0004 לבעלים, \u0003ו\u0004מביא קרבן \u0003אשם\u0004 לכפרה.","","","במקרה דומה, שאמר לו: \u0003\"היכן שורי\"? ואמר לו\u0004 השומר: \u0003\"נגנב\".\u0004 אמר לו בעל השור: \u0003\"משביעך אני\", ואמר \"אמן\", והעדים מעידים אותו ש\u0004הוא עצמו \u0003גנבו\u0004 — \u0003משלם\u0004 השומר \u0003תשלומי כפל,\u0004 ואם \u0003הודה מעצמו\u0004 — \u0003משלם קרן וחומש ואשם.\u0004","\u0003אמר לאחד בשוק,\u0004 שאיננו שומר: \u0003\"היכן שורי שגנבת\"?\u0004 ו\u0003הוא אומר: \"לא גנבתי\", והעדים מעידים אותו שגנבו\u0004 — הרי הוא \u0003משלם תשלומי כפל\u0004 כדין המפורש בגנב. אם \u0003טבח\u0004 האיש \u0003ומכר\u0004 את הבהמה — \u0003משלם תשלומי ארבעה וחמשה. ראה\u0004 הנאשם \u0003עדים שממשמשין ובאין\u0004 להעיד כנגדו, ו\u0003אמר: \"גנבתי, אבל לא טבחתי ולא מכרתי\"\u0004 — \u0003אינו משלם אלא קרן,\u0004 שהרי הודה מעצמו. אם \u0003אמר\u0004 בעל הבית \u0003לשואל: \"היכן שורי\", אמר לו:\u0004",""],["\u0003\"מת\", והוא שנשבר או נשבה או נגנב או אבד.\u0004 או אמר לו: \u0003\"נשבר\u0004 השור\", \u0003והוא שמת או נשבה או נגנב או אבד.\u0004 או אמר לו: \u0003\"נשבה\u0004 השור\", \u0003והוא שמת או נשבר או נגנב או אבד.\u0004 או אמר לו: \u0003\"נגנב\", והוא שמת או נשבר או נשבה או אבד.\u0004 או אמר לו: \u0003\"אבד\", והוא שמת או נשבר או נשבה או נגנב,\u0004 בכל אלה, אם אמר בעל השור: \u0003\"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003פטור\u0004 מקרבן על השבועה, שהרי בין כה וכה היה צריך לשלם, והשבועה לא פטרה אותו.","אבל אם אמר לו: \u0003\"היכן שורי\"? אמר לו: \"איני יודע מה אתה סח\", והוא שמת\u0004 השור, \u0003או נשבר או נשבה או נגנב או נאבד,\u0004 אמר לו: \u0003\"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003חייב\u0004 בקרבן על שבועה זו, שהרי רצה לפטור את עצמו מתשלום.","\u0003אמר לנושא שכר\u0004 או ל\u0003שוכר: \"היכן שורי\"? אמר לו\u0004 השוכר: \u0003\"מת\", והוא שנשבר או נשבה.\u0004 וכן אם אמר לו: \u0003\"נשבר\",\u0004 \u0003והוא\u0004 על פי האמת \u0003מת או נשבה.\u0004 או אמר לו: \u0003\"נשבה\", והוא שמת או נשבר.\u0004 או אמר לו: \u0003\"נגנב\"\u0004 — \u0003והוא שאבד.\u0004 וכן במקרה שאמר לו: \u0003\"אבד\"\u0004 — \u0003והוא שנגנב.\u0004 בכל אלו, אם אמר לו: \u0003\"משביעך אני\", ואמר\u0004 השומר: \u0003\"אמן\"\u0004 — \u0003פטור\u0004 מקרבן על השבועה, משום שאיננו משנה את דינו על ידי השבועה, שבין לפי האמת ובין לפי דבריו פטור הוא.","אבל אם אמר השומר: \u0003\"מת\" או \"נשבר\" או \"נשבה\", ו\u0004מה שקרה \u0003הוא שנגנב או אבד,\u0004 אמר בעל השור \u0003\"משביעך אני\" ואמר\u0004 השומר \u0003\"אמן\"\u0004 — \u0003חייב,\u0004 שהרי רצה לפטור את עצמו בטענת אונס שלא כדין. ומצד אחר, אם אמר השומר: \u0003\"אבד\" או \"נגנב\", והוא שמת או נשבר או נשבה, \"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003פטור,\u0004 שהרי חייב עצמו בממון שלא היה חייב לשלמו.","\u0003זה הכלל: כל\u0004 שומר הנשבע לשקר, ובשבועתו \u0003משנה מ\u0004דבר \u0003חובה\u0004 לשלמו \u0003ל\u0004דבר אחר ש\u0003חובה\u0004 עליו, \u0003ו\u0004כן משנה \u0003מפטור לפטור\u0004 או \u0003מפטור לחובה\u0004 — בכל המקרים הללו \u0003פטור\u0004 מהחיוב על השבועה. אבל כל מי שנשבע לשקר ומשנה \u0003מחובה לפטור\u0004 — \u0003חייב. זה הכלל: כל הנשבע להקל על עצמו\u0004 — \u0003חייב, להחמיר על עצמו\u0004 — \u0003פטור.\u0004","ומבררים: \u0003מאן תנא\u0004 \u0005[מי\u0006 הוא התנא \u0005ששנה]\u0006 שיש \u0003ארבעה שומרין? אמר רב נחמן אמר רבה בר אבוה:\u0004 שיטת \u0003ר' מאיר היא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מי איכא\u0004 \u0005[וכי יש]\u0006 \u0003תנא דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003ארבעה שומרין,\u0004 שאתה שואל מי שנה משנה זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי קאמינא לך\u0004 \u0005[כך אני אומר לך],\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ש\u0003אמר: שוכר כנושא שכר דמי\u0004 \u0005[נחשב]?\u0006 ועל כך \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 שיטת \u0003ר' מאיר היא.\u0004 ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' מאיר איפכא שמעינן ליה\u0004","\u0005[ההיפך שמענו אותו\u0006 אומר\u0005]!\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שוכר כיצד משלם? ר' מאיר אומר: כשומר חנם, ר' יהודה אומר: כנושא שכר!\u0004 ומשיבים: \u0003רבה בר אבוה איפכא תני\u0004 \u0005[להיפך היה שונה],\u0006 שר' מאיר אומר שדינו כשומר שכר, ולכן אמר שמשנתנו כשיטתו.","ושואלים לעצם הענין: וכי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003ארבעה הוו\u0004 \u0005[הם]?\u0006 הלא \u0003שלשה הוו\u0004 \u0005[הם],\u0006 שהרי אין הבדל בהלכה בין נושא שכר ושוכר! \u0003אמר רב נחמן בר יצחק: ארבעה שומרין\u0004 מבחינת האופן שבו קיבלו את הדבר לשמירה, אבל \u0003דיניהן\u0004 מבחינת ההלכה הם \u0003שלשה.\u0004","שנינו במשנה: \u0003אמר לשומר חנם כו'. היכן שורי כו'. אמר לאחד בשוק כו'. אמר לשומר כו'. היכן שורי? אמר לו איני יודע מה אתה סח כו'.\u0004 ומסקנת הדברים היא שאלו שאינם מקילים על עצמם בשבועתם — פטורים, למרות שנשבעו לשקר. \u0003אמר רב: וכולן\u0004 כל אלה אמנם \u0003פטורין משבועת שומרין,\u0004 אבל \u0003חייבין משום שבועת ביטוי,\u0004 שהרי שמכל מקום נשבעו לשקר. \u0003ושמואל אמר: אף פטורין משום שבועת ביטוי.\u0004","ושואלים: \u0003במאי קמפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005הם חלוקים]?\u0006 \u0003שמואל סבר:\u0004 שבועה זו \u0003ליתא\u0004 \u0005[איננה]\u0006 \u0003בלהבא\u0004 שאינו יכול להישבע בדבר זה בלהבא (שימות, או ייגנב, או יאבד וכיוצא בזה), וכל שבועה שאינו יכול להישבע להבא, לדעת שמואל אין בה משום שבועת ביטוי. \u0003ורב סבר: איתיה\u0004 \u0005[ישנו]\u0006 \u0003בלאו והן\u0004 הרי יכול להישבע עליה גם ב\"לאו\" (בלשון שלילה \"שלא נגנב\" וכו') וגם ב\"הן\" (\"נגנב\" וכו'), ובשבועה כזאת מתחייב משום שבועת ביטוי.","ושואלים: \u0003והא איפליגו\u0004 \u0005[והרי נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]:\u0006 אם אמר: \u0003\"שבועה שזרק פלוני צרור לים\",\u0004 או: \u0003\"שבועה שלא זרק\"\u0004 — \u0003רב אמר: חייב\u0004 משום שבועת ביטוי אם היה זה שקר, \u0003ושמואל אמר: פטור. רב אמר חייב\u0004 משום \u0003דאיתא\u0004 \u0005[שישנה]\u0006 \u0003בלאו והן,\u0004 וכל דבר שישנו בלאו והן חייבים עליו. \u0003ושמואל אמר פטור\u0004 משום \u0003דליתא\u0004 \u0005[שאינה\u0006 קיימת\u0005]\u0006 \u0003ב\u0004דבר שיהיה \u0003להבא,\u0004 שהרי אדם אינו יכול להישבע על מה שיעשה או לא יעשה אדם אחר!","ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה]\u0006 המחלוקת להיאמר גם במקרה זה, \u0003דאי אשמעינן בהא\u0004 \u0005[שאם היה משמיע לנו בזו]\u0006 ב\"שבועה שזרק פלוני\", היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב\u0004 שהוא חייב, \u0003משום דמנפשיה קמישתבע\u0004 \u0005[שמעצמו הוא נשבע]\u0006 לשקר, \u0003אבל בהך דבי דינא משבעי ליה\u0004 \u0005[בזו\u0006 שבמשנתנו, \u0005שבית דין משביעים אותו]\u0006 — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לשמואל, כ\u0004דברי \u0003ר' אמי,\u0004 ש\u0003אמר ר' אמי: כל שבועה שהדיינים משביעין אותה אין חייבין עליה משום שבועת ביטוי. ו\u0004להיפך, \u0003אי איתמר בהא\u0004 \u0005[אם היה נאמר\u0006 רק \u0005בזו]\u0006 שבמשנתנו, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שפטור, כדברי ר' אמי, \u0003אבל בהך אימא מודה ליה\u0004 \u0005[בזו אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב\u0004 שחייב, על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 ההלכה להיאמר בשני המקרים.","","ומביאים, \u0003גופא\u0004 \u0005[גופה]\u0006 של אותה הלכה, \u0003אמר ר' אמי: כל שבועה שהדיינין משביעין אותה אין בה משום שבועת ביטוי, שנאמר: \"או נפש כי תשבע לבטא בשפתים\"\u0004 (ויקרא ה, ד), כלומר \u0003מעצמו,\u0004 וכיצד מובן דבר זה מן הכתוב? \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 הביטוי \u0003\"כי\" משתמש\u0004 כלומר, יש לו משמעות בתורה \u0003בארבע לשונות: אי\u0004 \u0005[אם],\u0006 \u0003דלמא\u0004 \u0005[שמא],\u0006 \u0003אלא,\u0004 \u0003דהא\u0004 \u0005[שהרי].\u0006 וכאן המשמעות שלה היא \"אם\", כלומר, אם אדם נשבע מעצמו, אבל לא כשבית דין משביעים אותו. \u0003ר' אלעזר אומר: כולן\u0004 השנויים במשנתנו שפטור — \u0003פטורין משבועת שומרין וחייבין משום שבועת ביטוי, חוץ מ\"איני יודע מה אתה סח\"\u0004 שאומר ה\u0003שואל,\u0004 או טענת \u0003גניבה ואבידה\u0004 של \u0003נושא שכר ושבשוכר\u0004 — \u0003שהוא חייב\u0004 בהם משום שבועת שומרים, ומדוע? \u0003שהרי כפרו ממון,\u0004 שרצה לפטור עצמו מתשלום. והוא כדעת רב.","",""]]};
